    function [1:0] checkINIT ; 
        input [31:0] dev_code ; 
        begin
            case (dev_code)
            _FCODE_LIFCL_ : 
                checkINIT = 1 ;
            _FCODE_AP6_ : 
                checkINIT = 2 ;
            default : 
                checkINIT = 0 ;
            endcase 
        end
    endfunction
    function [31:0] getTrueByteWidth ; 
        input [31:0] dwid_in ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                getTrueByteWidth = (((dwid_in == 36) || (dwid_in == 32)) ? 4 : (((dwid_in == 18) || (dwid_in == 16)) ? 2 : 1)) ;
            _FCODE_ICE_ : 
                getTrueByteWidth = ((dwid_in == 16) ? 2 : 1) ;
            _FCODE_AP6_ : 
                getTrueByteWidth = (((dwid_in == 72) || (dwid_in == 64)) ? 8 : (((dwid_in == 36) || (dwid_in == 32)) ? 4 : (((dwid_in == 18) || (dwid_in == 16)) ? 2 : 1))) ;
            default : 
                getTrueByteWidth = 1 ;
            endcase 
        end
    endfunction
    function [31:0] procData ; 
        input [31:0] TARGET_DATA ; 
        input isECC ; 
        input [31:0] FAMILY_CODE ; 
        begin
            procData = 1 ;
            while ((procData < TARGET_DATA))
                begin
                    case (FAMILY_CODE)
                    _FCODE_LIFCL_ : 
                        begin
                            if (isECC) 
                                begin
                                    if ((procData < 32)) 
                                        begin
                                            procData = 32 ;
                                        end
                                    else
                                        begin
                                            procData = (procData * 2) ;
                                        end
                                end
                            else
                                begin
                                    if ((procData < 8)) 
                                        begin
                                            procData = (procData * 2) ;
                                        end
                                    else
                                        begin
                                            if ((procData == 8)) 
                                                begin
                                                    procData = 9 ;
                                                end
                                            else
                                                if (((procData % 9) == 0)) 
                                                    begin
                                                        procData = ((procData / 9) * 16) ;
                                                    end
                                                else
                                                    begin
                                                        procData = ((procData / 8) * 9) ;
                                                    end
                                        end
                                end
                        end
                    _FCODE_ICE_ : 
                        procData = (procData * 2) ;
                    _FCODE_AP6_ : 
                        begin
                            if (isECC) 
                                begin
                                    if ((procData < 64)) 
                                        begin
                                            procData = 64 ;
                                        end
                                    else
                                        begin
                                            procData = (procData * 2) ;
                                        end
                                end
                            else
                                begin
                                    if ((procData < 8)) 
                                        begin
                                            procData = (procData * 2) ;
                                        end
                                    else
                                        begin
                                            if ((procData == 8)) 
                                                begin
                                                    procData = 9 ;
                                                end
                                            else
                                                if (((procData % 9) == 0)) 
                                                    begin
                                                        procData = ((procData / 9) * 16) ;
                                                    end
                                                else
                                                    begin
                                                        procData = ((procData / 8) * 9) ;
                                                    end
                                        end
                                end
                        end
                    default : 
                        procData = TARGET_DATA ;
                    endcase 
                end
        end
    endfunction
    function [31:0] getSingularCase ; 
        input [31:0] port_use ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    if ((port_use > 32)) 
                        getSingularCase = 36 ;
                    else
                        if ((port_use > 18)) 
                            getSingularCase = 32 ;
                        else
                            if ((port_use > 16)) 
                                getSingularCase = 18 ;
                            else
                                if ((port_use > 9)) 
                                    getSingularCase = 16 ;
                                else
                                    if ((port_use > 8)) 
                                        getSingularCase = 9 ;
                                    else
                                        getSingularCase = (2 ** clog2(port_use)) ;
                end
            _FCODE_ICE_ : 
                getSingularCase = (2 ** clog2(port_use)) ;
            _FCODE_AP6_ : 
                begin
                    if ((port_use > 64)) 
                        getSingularCase = 72 ;
                    else
                        if ((port_use > 36)) 
                            getSingularCase = 64 ;
                        else
                            if ((port_use > 32)) 
                                getSingularCase = 36 ;
                            else
                                if ((port_use > 18)) 
                                    getSingularCase = 32 ;
                                else
                                    if ((port_use > 16)) 
                                        getSingularCase = 18 ;
                                    else
                                        if ((port_use > 9)) 
                                            getSingularCase = 16 ;
                                        else
                                            if ((port_use > 8)) 
                                                getSingularCase = 9 ;
                                            else
                                                getSingularCase = (2 ** clog2(port_use)) ;
                end
            default : 
                getSingularCase = 8 ;
            endcase 
        end
    endfunction
    function [31:0] getCASE1DataImpl ; 
        input [31:0] wr_addr_depth ; 
        input [31:0] wr_data_width ; 
        input [31:0] rd_addr_depth ; 
        input [31:0] rd_data_width ; 
        input is_taking_write_port ; 
        input is_taking_total_ebr ; 
        input is_ecc ; 
        input [31:0] family_code ; 
        reg [5:0] num0, 
            num1, 
            limit ; 
        reg [31:0] divisor, 
            wr_addr_div, 
            wr_data_div, 
            rd_addr_div, 
            rd_data_div ; 
        reg [31:0] wr_addr_chk, 
            wr_data_chk, 
            rd_addr_chk, 
            rd_data_chk ; 
        reg [31:0] EBR_usage, 
            prod ; 
        begin
            divisor = ((wr_addr_depth > rd_addr_depth) ? (wr_addr_depth / rd_addr_depth) : (rd_addr_depth / wr_addr_depth)) ;
            EBR_usage = 32'hffffffff ;
            getCASE1DataImpl = 0 ;
            if ((is_ecc == 1)) 
                begin
                    if ((is_taking_write_port == 1)) 
                        begin
                            if ((family_code == _FCODE_AP6_)) 
                                getCASE1DataImpl = 64 ;
                            else
                                getCASE1DataImpl = 32 ;
                        end
                    else
                        begin
                            if ((family_code == _FCODE_AP6_)) 
                                getCASE1DataImpl = (64 / divisor) ;
                            else
                                getCASE1DataImpl = (32 / divisor) ;
                        end
                end
            else
                begin
                    if ((((family_code == _FCODE_LIFCL_) && (divisor <= 4)) || ((family_code == _FCODE_AP6_) && (divisor <= 8)))) 
                        begin
                            limit = ((family_code == _FCODE_LIFCL_) ? 3 : 4) ;
                            for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                                begin
                                    wr_data_div = getDatabase(9,
                                            num0,
                                            family_code) ;
                                    wr_addr_div = data_to_addr(wr_data_div,
                                            family_code) ;
                                    wr_addr_chk = roundUP(wr_addr_depth,
                                            wr_addr_div) ;
                                    wr_data_chk = roundUP(wr_data_width,
                                            wr_data_div) ;
                                    for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                                        begin
                                            rd_data_div = getDatabase(9,
                                                    num1,
                                                    family_code) ;
                                            rd_addr_div = data_to_addr(rd_data_div,
                                                    family_code) ;
                                            rd_addr_chk = roundUP(rd_addr_depth,
                                                    rd_addr_div) ;
                                            rd_data_chk = roundUP(rd_data_width,
                                                    rd_data_div) ;
                                            if (((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk))) 
                                                begin
                                                    if ((((wr_data_width % wr_data_div) == 0) && ((rd_data_width % rd_data_div) == 0))) 
                                                        begin
                                                            prod = (wr_addr_chk * wr_data_chk) ;
                                                            if ((prod < EBR_usage)) 
                                                                begin
                                                                    EBR_usage = prod ;
                                                                    if ((is_taking_total_ebr == 1'b1)) 
                                                                        getCASE1DataImpl = EBR_usage ;
                                                                    else
                                                                        if ((is_taking_write_port == 1'b1)) 
                                                                            getCASE1DataImpl = wr_data_div ;
                                                                        else
                                                                            getCASE1DataImpl = rd_data_div ;
                                                                end
                                                        end
                                                end
                                        end
                                end
                        end
                    limit = ((family_code == _FCODE_LIFCL_) ? 6 : 7) ;
                    for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                        begin
                            wr_data_div = getDatabase(8,
                                    num0,
                                    family_code) ;
                            wr_addr_div = data_to_addr(wr_data_div,
                                    family_code) ;
                            wr_addr_chk = roundUP(wr_addr_depth,
                                    wr_addr_div) ;
                            wr_data_chk = roundUP(wr_data_width,
                                    wr_data_div) ;
                            for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                                begin
                                    rd_data_div = getDatabase(8,
                                            num1,
                                            family_code) ;
                                    rd_addr_div = data_to_addr(rd_data_div,
                                            family_code) ;
                                    rd_addr_chk = roundUP(rd_addr_depth,
                                            rd_addr_div) ;
                                    rd_data_chk = roundUP(rd_data_width,
                                            rd_data_div) ;
                                    if (((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk))) 
                                        begin
                                            if ((((wr_data_width % wr_data_div) == 0) && ((rd_data_width % rd_data_div) == 0))) 
                                                begin
                                                    prod = (wr_addr_chk * wr_data_chk) ;
                                                    if ((prod < EBR_usage)) 
                                                        begin
                                                            EBR_usage = prod ;
                                                            if ((is_taking_total_ebr == 1'b1)) 
                                                                getCASE1DataImpl = EBR_usage ;
                                                            else
                                                                if ((is_taking_write_port == 1'b1)) 
                                                                    getCASE1DataImpl = wr_data_div ;
                                                                else
                                                                    getCASE1DataImpl = rd_data_div ;
                                                        end
                                                end
                                        end
                                end
                        end
                end
        end
    endfunction
