    function [31:0] getMinimaData ; 
        input [31:0] depth_impl ; 
        input [31:0] width_impl ; 
        input is_byte_enable ; 
        input [31:0] byte_size ; 
        input is_ecc ; 
        input [31:0] family_code ; 
        reg [31:0] temp_00, 
            temp_01, 
            temp_02, 
            temp_03, 
            temp_04, 
            temp_05, 
            temp_06 ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    if (is_ecc) 
                        begin
                            getMinimaData = 32 ;
                        end
                    else
                        begin
                            temp_00 = EBR_impl(depth_impl,
                                    width_impl,
                                    512,
                                    36) ;
                            temp_01 = EBR_impl(depth_impl,
                                    width_impl,
                                    1024,
                                    18) ;
                            temp_02 = EBR_impl(depth_impl,
                                    width_impl,
                                    2048,
                                    9) ;
                            temp_03 = EBR_impl(depth_impl,
                                    width_impl,
                                    4096,
                                    4) ;
                            temp_04 = EBR_impl(depth_impl,
                                    width_impl,
                                    8192,
                                    2) ;
                            temp_05 = EBR_impl(depth_impl,
                                    width_impl,
                                    16384,
                                    1) ;
                            if (((is_byte_enable == 1) && ((width_impl % 9) != 0))) 
                                begin
                                    temp_00 = EBR_impl(depth_impl,
                                            width_impl,
                                            512,
                                            32) ;
                                    temp_01 = EBR_impl(depth_impl,
                                            width_impl,
                                            1024,
                                            16) ;
                                    temp_02 = EBR_impl(depth_impl,
                                            width_impl,
                                            2048,
                                            8) ;
                                    if ((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05))) 
                                        getMinimaData = 32 ;
                                    else
                                        if (((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05))) 
                                            getMinimaData = 16 ;
                                        else
                                            if ((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05))) 
                                                getMinimaData = 8 ;
                                            else
                                                if (((temp_03 < temp_04) && (temp_03 < temp_05))) 
                                                    getMinimaData = 4 ;
                                                else
                                                    if ((temp_04 < temp_05)) 
                                                        getMinimaData = 2 ;
                                                    else
                                                        getMinimaData = 1 ;
                                end
                            else
                                begin
                                    if ((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05))) 
                                        getMinimaData = 36 ;
                                    else
                                        if (((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05))) 
                                            getMinimaData = 18 ;
                                        else
                                            if ((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05))) 
                                                getMinimaData = 9 ;
                                            else
                                                if (((temp_03 < temp_04) && (temp_03 < temp_05))) 
                                                    getMinimaData = 4 ;
                                                else
                                                    if ((temp_04 < temp_05)) 
                                                        getMinimaData = 2 ;
                                                    else
                                                        getMinimaData = 1 ;
                                end
                        end
                end
            _FCODE_ICE_ : 
                begin
                    temp_00 = EBR_impl(depth_impl,
                            width_impl,
                            256,
                            16) ;
                    temp_01 = EBR_impl(depth_impl,
                            width_impl,
                            512,
                            8) ;
                    temp_02 = EBR_impl(depth_impl,
                            width_impl,
                            1024,
                            4) ;
                    temp_03 = EBR_impl(depth_impl,
                            width_impl,
                            2048,
                            2) ;
                    if ((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03))) 
                        getMinimaData = 16 ;
                    else
                        if (((temp_01 < temp_02) && (temp_01 < temp_03))) 
                            getMinimaData = 8 ;
                        else
                            if ((temp_02 < temp_03)) 
                                getMinimaData = 4 ;
                            else
                                getMinimaData = 2 ;
                end
            _FCODE_AP6_ : 
                begin
                    if (is_ecc) 
                        begin
                            getMinimaData = 64 ;
                        end
                    else
                        begin
                            temp_00 = EBR_impl(depth_impl,
                                    width_impl,
                                    512,
                                    72) ;
                            temp_01 = EBR_impl(depth_impl,
                                    width_impl,
                                    1024,
                                    36) ;
                            temp_02 = EBR_impl(depth_impl,
                                    width_impl,
                                    2048,
                                    18) ;
                            temp_03 = EBR_impl(depth_impl,
                                    width_impl,
                                    4096,
                                    9) ;
                            temp_04 = EBR_impl(depth_impl,
                                    width_impl,
                                    8192,
                                    4) ;
                            temp_05 = EBR_impl(depth_impl,
                                    width_impl,
                                    16384,
                                    2) ;
                            temp_06 = EBR_impl(depth_impl,
                                    width_impl,
                                    32768,
                                    1) ;
                            if (((is_byte_enable == 1) && ((width_impl % 9) != 0))) 
                                begin
                                    temp_00 = EBR_impl(depth_impl,
                                            width_impl,
                                            512,
                                            64) ;
                                    temp_01 = EBR_impl(depth_impl,
                                            width_impl,
                                            1024,
                                            32) ;
                                    temp_02 = EBR_impl(depth_impl,
                                            width_impl,
                                            2048,
                                            16) ;
                                    temp_03 = EBR_impl(depth_impl,
                                            width_impl,
                                            4096,
                                            8) ;
                                    if (((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05)) && (temp_00 < temp_06))) 
                                        getMinimaData = 64 ;
                                    else
                                        if ((((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05)) && (temp_01 < temp_06))) 
                                            getMinimaData = 32 ;
                                        else
                                            if (((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05)) && (temp_02 < temp_06))) 
                                                getMinimaData = 16 ;
                                            else
                                                if ((((temp_03 < temp_04) && (temp_03 < temp_05)) && (temp_03 < temp_06))) 
                                                    getMinimaData = 8 ;
                                                else
                                                    if (((temp_04 < temp_05) && (temp_04 < temp_06))) 
                                                        getMinimaData = 4 ;
                                                    else
                                                        if ((temp_05 < temp_06)) 
                                                            getMinimaData = 2 ;
                                                        else
                                                            getMinimaData = 1 ;
                                end
                            else
                                begin
                                    if (((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05)) && (temp_00 < temp_06))) 
                                        getMinimaData = 72 ;
                                    else
                                        if ((((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05)) && (temp_01 < temp_06))) 
                                            getMinimaData = 36 ;
                                        else
                                            if (((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05)) && (temp_02 < temp_06))) 
                                                getMinimaData = 18 ;
                                            else
                                                if ((((temp_03 < temp_04) && (temp_03 < temp_05)) && (temp_03 < temp_06))) 
                                                    getMinimaData = 9 ;
                                                else
                                                    if (((temp_04 < temp_05) && (temp_04 < temp_06))) 
                                                        getMinimaData = 4 ;
                                                    else
                                                        if ((temp_05 < temp_06)) 
                                                            getMinimaData = 2 ;
                                                        else
                                                            getMinimaData = 1 ;
                                end
                        end
                end
            default : 
                getMinimaData = 8 ;
            endcase 
        end
    endfunction
    function [31:0] getByteSize ; 
        input [31:0] data_width ; 
        input [31:0] dev_code ; 
        begin
            case (dev_code)
            _FCODE_LIFCL_ : 
                begin
                    if (((data_width % 9) == 0)) 
                        getByteSize = 9 ;
                    else
                        getByteSize = 8 ;
                end
            _FCODE_ICE_ : 
                getByteSize = 8 ;
            _FCODE_AP6_ : 
                begin
                    if (((data_width % 9) == 0)) 
                        getByteSize = 9 ;
                    else
                        getByteSize = 8 ;
                end
            default : 
                getByteSize = 8 ;
            endcase 
        end
    endfunction
    function is_byte_enable_good ; 
        input [31:0] max_data ; 
        input [31:0] min_data ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_ICE_ : 
                is_byte_enable_good = ((((max_data / min_data) == 2) && ((max_data % 16) == 0)) ? 1'b1 : 1'b0) ;
            _FCODE_LIFCL_ : 
                begin
                    if (((max_data / min_data) == 4)) 
                        is_byte_enable_good = ((((max_data % 36) == 0) || ((max_data % 32) == 0)) ? 1'b1 : 1'b0) ;
                    else
                        if (((max_data / min_data) == 2)) 
                            is_byte_enable_good = ((((max_data % 16) == 0) || ((max_data % 18) == 0)) ? 1'b1 : 1'b0) ;
                        else
                            is_byte_enable_good = 1'b0 ;
                end
            _FCODE_AP6_ : 
                begin
                    if (((max_data / min_data) == 8)) 
                        is_byte_enable_good = ((((max_data % 72) == 0) || ((max_data % 64) == 0)) ? 1'b1 : 1'b0) ;
                    else
                        if (((max_data / min_data) == 4)) 
                            is_byte_enable_good = ((((max_data % 36) == 0) || ((max_data % 32) == 0)) ? 1'b1 : 1'b0) ;
                        else
                            if (((max_data / min_data) == 2)) 
                                is_byte_enable_good = ((((max_data % 16) == 0) || ((max_data % 18) == 0)) ? 1'b1 : 1'b0) ;
                            else
                                is_byte_enable_good = 1'b0 ;
                end
            default : 
                is_byte_enable_good = 1'b0 ;
            endcase 
        end
    endfunction
    function [31:0] EBR_impl ; 
        input [31:0] DEPTH_IMPL ; 
        input [31:0] WIDTH_IMPL ; 
        input [31:0] ADDR_DEPTH_X ; 
        input [31:0] DATA_WIDTH_X ; 
        begin
            EBR_impl = (roundUP(DEPTH_IMPL,
                    ADDR_DEPTH_X) * roundUP(WIDTH_IMPL,
                    DATA_WIDTH_X)) ;
        end
    endfunction
    function [31:0] roundUP ; 
        input [31:0] dividend ; 
        input [31:0] divisor ; 
        begin
            if ((divisor == 1)) 
                begin
                    roundUP = dividend ;
                end
            else
                if ((divisor == dividend)) 
                    begin
                        roundUP = 1 ;
                    end
                else
                    begin
                        roundUP = ((dividend / divisor) + (((dividend % divisor) == 0) ? 0 : 1)) ;
                    end
        end
    endfunction
    function [31:0] clog2 ; 
        input [31:0] value ; 
        reg [31:0] num ; 
        begin
            num = (value - 1) ;
            for (clog2 = 0 ; (num > 0) ; clog2 = (clog2 + 1))
                num = (num >> 1) ;
        end
    endfunction
