    function [31:0] getByteWidth ; 
        input [31:0] data_width ; 
        input [31:0] dev_code ; 
        begin
            case (dev_code)
            _FCODE_LIFCL_ : 
                begin
                    if (((data_width == 36) || (data_width == 32))) 
                        getByteWidth = 4 ;
                    else
                        if (((data_width == 18) || (data_width == 16))) 
                            getByteWidth = 2 ;
                        else
                            getByteWidth = 1 ;
                end
            _FCODE_ICE_ : 
                begin
                    if ((data_width == 16)) 
                        getByteWidth = 2 ;
                    else
                        getByteWidth = 1 ;
                end
            _FCODE_AP6_ : 
                begin
                    if (((data_width == 72) || (data_width == 64))) 
                        getByteWidth = 8 ;
                    else
                        if (((data_width == 36) || (data_width == 32))) 
                            getByteWidth = 4 ;
                        else
                            if (((data_width == 18) || (data_width == 16))) 
                                getByteWidth = 2 ;
                            else
                                getByteWidth = 1 ;
                end
            default : 
                getByteWidth = 1 ;
            endcase 
        end
