                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                            else
                                                getCASE1DataImpl_wBEN = (4 * byte_size) ;
                                        end
                                    else
                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = byte_size ;
                                            else
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                        end
                                end
                        end
                end
            default : 
                getCASE1DataImpl_wBEN = 8 ;
            endcase 
        end
    endfunction
    function [31:0] getCASE1DataImpl ; 
        input [31:0] addr_a_depth ; 
        input [31:0] data_a_width ; 
        input [31:0] addr_b_depth ; 
        input [31:0] data_b_width ; 
        input is_taking_port_a ; 
        input is_taking_total_ebr ; 
        input [31:0] family_code ; 
        reg [5:0] num0, 
            num1, 
            limit ; 
        reg [31:0] divisor, 
            addr_div_prtA, 
            data_div_prtA, 
            addr_div_prtB, 
            data_div_prtB ; 
        reg [31:0] portA_addr_chk, 
            portA_data_chk, 
            portB_addr_chk, 
            portB_data_chk ; 
        reg [31:0] EBR_usage, 
            PROD ; 
        begin
            divisor = ((addr_a_depth > addr_b_depth) ? (addr_a_depth / addr_b_depth) : (addr_b_depth / addr_a_depth)) ;
            EBR_usage = {32{1'b1}} ;
            getCASE1DataImpl = 0 ;
            if ((((family_code == _FCODE_LIFCL_) && (divisor <= 2)) || ((family_code == _FCODE_AP6_) && (divisor <= 4)))) 
                begin
                    limit = ((family_code == _FCODE_LIFCL_) ? 2 : 3) ;
                    for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                        begin
                            data_div_prtA = getDatabase(9,
                                    num0,
                                    family_code) ;
                            addr_div_prtA = data_to_addr(data_div_prtA,
                                    family_code) ;
                            portA_addr_chk = roundUP(addr_a_depth,
                                    addr_div_prtA) ;
                            portA_data_chk = roundUP(data_a_width,
                                    data_div_prtA) ;
                            for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                                begin
                                    data_div_prtB = getDatabase(9,
                                            num1,
                                            family_code) ;
                                    addr_div_prtB = data_to_addr(data_div_prtB,
                                            family_code) ;
                                    portB_addr_chk = roundUP(addr_b_depth,
                                            addr_div_prtB) ;
                                    portB_data_chk = roundUP(data_b_width,
                                            data_div_prtB) ;
                                    if (((portA_addr_chk == portB_addr_chk) && (portA_data_chk == portB_data_chk))) 
                                        begin
                                            if ((((data_a_width % data_div_prtA) == 0) && ((data_b_width % data_div_prtB) == 0))) 
                                                begin
                                                    PROD = (portA_addr_chk * portA_data_chk) ;
                                                    if ((PROD < EBR_usage)) 
                                                        begin
                                                            EBR_usage = PROD ;
                                                            if ((is_taking_total_ebr == 1'b1)) 
                                                                getCASE1DataImpl = EBR_usage ;
                                                            else
                                                                if ((is_taking_port_a == 1'b1)) 
                                                                    getCASE1DataImpl = data_div_prtA ;
                                                                else
                                                                    getCASE1DataImpl = data_div_prtB ;
                                                        end
                                                end
                                        end
                                end
                        end
                end
            limit = ((family_code == _FCODE_LIFCL_) ? 5 : 6) ;
            for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                begin
                    data_div_prtA = getDatabase(8,
                            num0,
                            family_code) ;
                    addr_div_prtA = data_to_addr(data_div_prtA,
                            family_code) ;
                    portA_addr_chk = roundUP(addr_a_depth,
                            addr_div_prtA) ;
                    portA_data_chk = roundUP(data_a_width,
                            data_div_prtA) ;
                    for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                        begin
                            data_div_prtB = getDatabase(8,
                                    num1,
                                    family_code) ;
                            addr_div_prtB = data_to_addr(data_div_prtB,
                                    family_code) ;
                            portB_addr_chk = roundUP(addr_b_depth,
                                    addr_div_prtB) ;
                            portB_data_chk = roundUP(data_b_width,
                                    data_div_prtB) ;
                            if (((portA_addr_chk == portB_addr_chk) && (portA_data_chk == portB_data_chk))) 
                                begin
                                    if ((((data_a_width % data_div_prtA) == 0) && ((data_b_width % data_div_prtB) == 0))) 
                                        begin
                                            PROD = (portA_addr_chk * portA_data_chk) ;
                                            if ((PROD < EBR_usage)) 
                                                begin
                                                    EBR_usage = PROD ;
                                                    if ((is_taking_total_ebr == 1'b1)) 
                                                        getCASE1DataImpl = EBR_usage ;
                                                    else
                                                        if ((is_taking_port_a == 1'b1)) 
                                                            getCASE1DataImpl = data_div_prtA ;
                                                        else
                                                            getCASE1DataImpl = data_div_prtB ;
                                                end
                                        end
                                end
                        end
                end
        end
    endfunction
    function [31:0] procData ; 
        input [31:0] max_data ; 
        input [31:0] family_code ; 
        begin
            procData = 1 ;
            while ((procData < max_data))
                begin
                    case (family_code)
                    _FCODE_LIFCL_,
                            _FCODE_AP6_ : 
                        begin
                            if ((procData < 8)) 
                                begin
                                    procData = (procData * 2) ;
                                end
                            else
                                begin
                                    if ((procData == 8)) 
                                        begin
                                            procData = 9 ;
                                        end
                                    else
                                        if (((procData % 9) == 0)) 
                                            begin
                                                procData = ((procData / 9) * 16) ;
                                            end
                                        else
                                            begin
                                                procData = ((procData / 8) * 9) ;
                                            end
                                end
                        end
                    default : 
                        procData = max_data ;
                    endcase 
                end
        end
    endfunction
    function [31:0] data_to_addr ; 
        input [31:0] data_size ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    case (data_size)
                    18 : 
                        data_to_addr = 1024 ;
                    16 : 
                        data_to_addr = 1024 ;
                    9 : 
                        data_to_addr = 2048 ;
                    8 : 
                        data_to_addr = 2048 ;
                    4 : 
                        data_to_addr = 4096 ;
                    2 : 
                        data_to_addr = 8192 ;
                    default : 
                        data_to_addr = 16384 ;
                    endcase 
                end
            _FCODE_AP6_ : 
                begin
                    case (data_size)
                    36 : 
                        data_to_addr = 1024 ;
                    32 : 
                        data_to_addr = 1024 ;
                    18 : 
                        data_to_addr = 2048 ;
                    16 : 
                        data_to_addr = 2048 ;
                    9 : 
                        data_to_addr = 4096 ;
                    8 : 
                        data_to_addr = 4096 ;
                    4 : 
                        data_to_addr = 8192 ;
                    2 : 
                        data_to_addr = 16384 ;
                    default : 
                        data_to_addr = 32768 ;
                    endcase 
                end
            default : 
                data_to_addr = 1024 ;
            endcase 
        end
    endfunction
    function [31:0] getMinimaData ; 
        input [31:0] depth_impl ; 
        input [31:0] width_impl ; 
        input is_byte_en ; 
        input [31:0] byte_size ; 
        input [31:0] family_code ; 
        reg [31:0] temp_00, 
            temp_01, 
            temp_02, 
            temp_03, 
            temp_04, 
            temp_05 ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    temp_00 = EBR_impl(depth_impl,
                            width_impl,
                            1024,
                            18) ;
                    temp_01 = EBR_impl(depth_impl,
                            width_impl,
                            2048,
                            9) ;
                    temp_02 = EBR_impl(depth_impl,
                            width_impl,
                            4096,
                            4) ;
                    temp_03 = EBR_impl(depth_impl,
                            width_impl,
                            8192,
                            2) ;
                    temp_04 = EBR_impl(depth_impl,
                            width_impl,
                            16384,
                            1) ;
                    if (((is_byte_en == 1) && ((width_impl % 9) != 0))) 
                        begin
                            temp_00 = EBR_impl(depth_impl,
                                    width_impl,
                                    1024,
                                    16) ;
                            temp_01 = EBR_impl(depth_impl,
                                    width_impl,
                                    2048,
                                    8) ;
                            if (((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04))) 
                                getMinimaData = 16 ;
                            else
                                if ((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04))) 
                                    getMinimaData = 8 ;
                                else
                                    if (((temp_02 < temp_03) && (temp_02 < temp_04))) 
                                        getMinimaData = 4 ;
                                    else
                                        if ((temp_03 < temp_04)) 
                                            getMinimaData = 2 ;
                                        else
                                            getMinimaData = 1 ;
                        end
                    else
                        begin
                            if (((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04))) 
                                getMinimaData = 18 ;
                            else
                                if ((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04))) 
                                    getMinimaData = 9 ;
                                else
                                    if (((temp_02 < temp_03) && (temp_02 < temp_04))) 
                                        getMinimaData = 4 ;
                                    else
                                        if ((temp_03 < temp_04)) 
                                            getMinimaData = 2 ;
                                        else
                                            getMinimaData = 1 ;
                        end
                end
            _FCODE_AP6_ : 
                begin
                    temp_00 = EBR_impl(depth_impl,
                            width_impl,
                            1024,
                            36) ;
                    temp_01 = EBR_impl(depth_impl,
                            width_impl,
                            2048,
                            18) ;
                    temp_02 = EBR_impl(depth_impl,
                            width_impl,
                            4096,
                            9) ;
                    temp_03 = EBR_impl(depth_impl,
                            width_impl,
                            8192,
                            4) ;
                    temp_04 = EBR_impl(depth_impl,
                            width_impl,
                            16384,
                            2) ;
                    temp_05 = EBR_impl(depth_impl,
                            width_impl,
                            32768,
                            1) ;
                    if (((is_byte_en == 1) && ((width_impl % 9) != 0))) 
                        begin
                            temp_00 = EBR_impl(depth_impl,
                                    width_impl,
                                    1024,
                                    32) ;
                            temp_01 = EBR_impl(depth_impl,
                                    width_impl,
                                    2048,
                                    16) ;
                            temp_02 = EBR_impl(depth_impl,
                                    width_impl,
                                    4096,
                                    8) ;
                            if ((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05))) 
                                getMinimaData = 32 ;
                            else
                                if (((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05))) 
                                    getMinimaData = 16 ;
                                else
                                    if ((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05))) 
                                        getMinimaData = 8 ;
                                    else
                                        if (((temp_03 < temp_04) && (temp_03 < temp_05))) 
                                            getMinimaData = 4 ;
                                        else
                                            if ((temp_04 < temp_05)) 
                                                getMinimaData = 2 ;
                                            else
                                                getMinimaData = 1 ;
                        end
                    else
                        begin
                            if ((((((temp_00 < temp_01) && (temp_00 < temp_02)) && (temp_00 < temp_03)) && (temp_00 < temp_04)) && (temp_00 < temp_05))) 
                                getMinimaData = 36 ;
                            else
                                if (((((temp_01 < temp_02) && (temp_01 < temp_03)) && (temp_01 < temp_04)) && (temp_01 < temp_05))) 
                                    getMinimaData = 18 ;
                                else
                                    if ((((temp_02 < temp_03) && (temp_02 < temp_04)) && (temp_02 < temp_05))) 
                                        getMinimaData = 9 ;
                                    else
                                        if (((temp_03 < temp_04) && (temp_03 < temp_05))) 
                                            getMinimaData = 4 ;
                                        else
                                            if ((temp_04 < temp_05)) 
                                                getMinimaData = 2 ;
                                            else
                                                getMinimaData = 1 ;
                        end
                end
            default : 
                getMinimaData = 8 ;
            endcase 
        end
    endfunction
    function [31:0] getByteSize ; 
        input [31:0] data_width ; 
        input [31:0] dev_code ; 
        begin
            case (dev_code)
            _FCODE_LIFCL_,
                    _FCODE_AP6_ : 
                begin
                    if (((data_width % 9) == 0)) 
                        getByteSize = 9 ;
                    else
                        getByteSize = 8 ;
                end
            default : 
                getByteSize = 8 ;
            endcase 
        end
    endfunction
    function [31:0] EBR_impl ; 
        input [31:0] DEPTH_IMPL ; 
        input [31:0] WIDTH_IMPL ; 
        input [31:0] ADDR_DEPTH_X ; 
        input [31:0] DATA_WIDTH_X ; 
        begin
            EBR_impl = (roundUP(DEPTH_IMPL,
                    ADDR_DEPTH_X) * roundUP(WIDTH_IMPL,
                    DATA_WIDTH_X)) ;
        end
    endfunction
    function [31:0] roundUP ; 
        input [31:0] dividend ; 
        input [31:0] divisor ; 
        begin
            if ((divisor == 1)) 
                begin
                    roundUP = dividend ;
                end
            else
                if ((divisor == dividend)) 
                    begin
                        roundUP = 1 ;
                    end
                else
                    begin
                        roundUP = ((dividend / divisor) + (((dividend % divisor) == 0) ? 0 : 1)) ;
                    end
        end
    endfunction
    function [31:0] clog2 ; 
        input [31:0] value ; 
        reg [31:0] num ; 
        begin
            num = (value - 1) ;
            for (clog2 = 0 ; (num > 0) ; clog2 = (clog2 + 1))
                num = (num >> 1) ;
        end
    endfunction
