    // -----------------------------------------------------------------------------
    // Input/Output Ports
    // -----------------------------------------------------------------------------
    input wr_clk_i, 
    input rd_clk_i, 
    input rst_i, 
    input wr_clk_en_i, 
    input rd_clk_en_i, 
    input wr_en_i, 
    input [(WDATA_WIDTH - 1):0] wr_data_i, 
    input [(WADDR_WIDTH - 1):0] wr_addr_i, 
    input rd_en_i, 
    input [(RADDR_WIDTH - 1):0] rd_addr_i, 
    output [(RDATA_WIDTH - 1):0] rd_data_o) ;
    // -----------------------------------------------------------------------------
    // Local Parameters
    // -----------------------------------------------------------------------------
    // -----------------------------------------------------------------------------
    // Register Declarations
    // -----------------------------------------------------------------------------
    (* syn_ramstyle="distributed" *) reg [(RDATA_WIDTH - 1):0] mem [((2 ** RADDR_WIDTH) - 1):0] ; 
    reg [(RDATA_WIDTH - 1):0] out_raw ; 
    reg [(RDATA_WIDTH - 1):0] out_buffer ; 
    wire write_enable = (wr_clk_en_i & wr_en_i) ; 
    wire read_enable = (rd_clk_en_i & rd_en_i) ; 
    assign rd_data_o = ((REGMODE == "noreg") ? out_raw : out_buffer) ; 
    // -----------------------------------------------------------------------------
    // Initial Block
    // -----------------------------------------------------------------------------
    initial
        begin
            if (((INIT_MODE == "mem_file") && (INIT_FILE != "none"))) 
                begin
                    if ((INIT_FILE_FORMAT == "hex")) 
                        begin
                            $readmemh (INIT_FILE,
                                    mem,
                                    0,
                                    (RADDR_DEPTH - 1)) ;
                        end
                    else
                        begin
                            $readmemb (INIT_FILE,
                                    mem,
                                    0,
                                    (RADDR_DEPTH - 1)) ;
                        end
                end
        end
    // -----------------------------------------------------------------------------
    // Generate Sequential Blocks
    // -----------------------------------------------------------------------------
    always
        @(posedge wr_clk_i)
        begin
            if ((write_enable == 1'b1)) 
                begin
                    mem[wr_addr_i] <=  wr_data_i ;
                end
        end
    always
        @(*)
        begin
            out_raw = mem[rd_addr_i] ;
        end
    if ((REGMODE == "reg")) 
        begin : REG
            if ((RESETMODE == "async")) 
                begin : ASYNC
                    always
                        @(posedge rd_clk_i or 
                            posedge rst_i)
                        begin
                            if ((rst_i == 1'b1)) 
                                begin
                                    out_buffer <=  'h0 ;
                                end
                            else
                                if ((read_enable == 1'b1)) 
                                    begin
                                        out_buffer <=  out_raw ;
                                    end
                        end
                end
            else
                begin : genblk1
                    always
                        @(posedge rd_clk_i)
                        begin
                            if ((rst_i == 1'b1)) 
                                begin
                                    out_buffer <=  'h0 ;
                                end
                            else
                                if ((read_enable == 1'b1)) 
                                    begin
                                        out_buffer <=  out_raw ;
                                    end
                        end
                end
        end
    //------------------------------------------------------------------------------
    // Function Definition
    //------------------------------------------------------------------------------
    function [31:0] clog2 ; 
        input [31:0] value ; 
        reg [31:0] num ; 
        begin
            num = (value - 1) ;
            for (clog2 = 0 ; (num > 0) ; clog2 = (clog2 + 1))
                num = (num >> 1) ;
        end
    endfunction
endmodule



