module lpddr4_mc_ipgen_lscc_apb_cdc #(parameter ADDR_WIDTH = 10, 
        parameter DATA_WIDTH = 32, 
        parameter PSLVERR_EN = 0, 
        parameter REVEAL_DBG_EN = 1) (
    input apb_s0_pclk_i, 
    input apb_s0_presetn_i, 
    input apb_s0_psel_slv_i, 
    input [(ADDR_WIDTH - 1):0] apb_s0_paddr_slv_i, 
    input apb_s0_pwrite_slv_i, 
    input [(DATA_WIDTH - 1):0] apb_s0_pwdata_slv_i, 
    input apb_s0_penable_slv_i, 
    output apb_s0_pready_slv_o, 
    output apb_s0_pslverr_slv_o, 
    (* syn_preserve=1 *) output [(DATA_WIDTH - 1):0] apb_s0_prdata_slv_o, 
    input apb_m0_pclk_i, 
    input apb_m0_presetn_i, 
    input apb_m0_pready_mst_i, 
    input apb_m0_pslverr_mst_i, 
    input [(DATA_WIDTH - 1):0] apb_m0_prdata_mst_i, 
    output apb_m0_psel_mst_o, 
    (* syn_preserve=1 *) output [(ADDR_WIDTH - 1):0] apb_m0_paddr_mst_o, 
    (* syn_preserve=1 *) output apb_m0_pwrite_mst_o, 
    (* syn_preserve=1 *) output [(DATA_WIDTH - 1):0] apb_m0_pwdata_mst_o, 
    output apb_m0_penable_mst_o) ;
    localparam S2M_WIDTH = ((ADDR_WIDTH + DATA_WIDTH) + 1) ; 
    wire apb_s0_req, 
        apb_s0_rdy ; 
    wire apb_m0_valid, 
        apb_m0_ack ; 
    wire apb_s0_pend_w ; 
    reg apb_s0_pend_r ; 
    reg apb_m0_valid_mst_r ; 
    wire [(S2M_WIDTH - 1):0] apb_s0_wdata, 
        apb_m0_wdata ; 
    wire [(DATA_WIDTH - 1):0] in_data_mst, 
        out_data_slv ; 
    assign apb_s0_req = apb_s0_pend_w ; 
    assign apb_s0_wdata = {apb_s0_pwrite_slv_i,
                apb_s0_paddr_slv_i,
                apb_s0_pwdata_slv_i} ; 
    lpddr4_mc_ipgen_lscc_cdc_hs_bus #(.WIDTH(S2M_WIDTH),
            .SYNC_STAGE(2),
            .UNRELATED_RST(1'b1),
            .SRC_RST_MODE("ASYNC"),
            .DEST_RST_MODE("ASYNC"),
            .RST_INIT({S2M_WIDTH{1'b0}}),
            .SRC_REQ_EN(1'b1),
            .REGMODE(1'b0),
            .SIM_ASSERT_EN(1'b0)) u_s2m_cdc (.src_rst_n(apb_s0_presetn_i), 
                .src_clk(apb_s0_pclk_i), 
                .src_req(apb_s0_req), 
                .src_ready(apb_s0_rdy), 
                .in_data(apb_s0_wdata), 
                .dest_rst_n(apb_m0_presetn_i), 
                .dest_clk(apb_m0_pclk_i), 
                .dest_valid(apb_m0_valid), 
                .dest_ack(apb_m0_ack), 
                .out_data(apb_m0_wdata)) ; 
    // PENABLE has to be one clock after PSEL 
    always
        @(posedge apb_m0_pclk_i or 
            negedge apb_m0_presetn_i)
        begin
            if ((!apb_m0_presetn_i)) 
                apb_m0_valid_mst_r <=  1'b0 ;
            else
                apb_m0_valid_mst_r <=  apb_m0_valid ;
        end
    assign apb_m0_ack = apb_m0_pready_mst_i ; 
    assign apb_m0_psel_mst_o = apb_m0_valid ; 
    assign apb_m0_penable_mst_o = (apb_m0_valid_mst_r & apb_m0_valid) ; 
    assign apb_m0_pwrite_mst_o = apb_m0_wdata[(S2M_WIDTH - 1)] ; 
    assign apb_m0_paddr_mst_o = apb_m0_wdata[(S2M_WIDTH - 2):DATA_WIDTH] ; 
    assign apb_m0_pwdata_mst_o = apb_m0_wdata[(DATA_WIDTH - 1):0] ; 
    localparam M2S_WIDTH = (DATA_WIDTH + 1) ; 
    wire apb_m0_req, 
        apb_s0_valid, 
        apb_s0_ack ; 
    wire [(M2S_WIDTH - 1):0] apb_s0_rdata, 
        apb_m0_rdata ; 
    assign apb_s0_ack = apb_s0_valid ; 
    assign apb_m0_req = (apb_m0_valid & apb_m0_ack) ; 
    assign apb_m0_rdata = {apb_m0_pslverr_mst_i,
                apb_m0_prdata_mst_i} ; 
    lpddr4_mc_ipgen_lscc_cdc_hs_bus #(.WIDTH(M2S_WIDTH),
            .SYNC_STAGE(2),
            .UNRELATED_RST(1'b1),
            .SRC_RST_MODE("ASYNC"),
            .DEST_RST_MODE("ASYNC"),
            .RST_INIT({M2S_WIDTH{1'b0}}),
            .SRC_REQ_EN(1'b1),
            .REGMODE(1'b0),
            .SIM_ASSERT_EN(1'b0)) u_m2s_cdc (.src_rst_n(apb_m0_presetn_i), 
                .src_clk(apb_m0_pclk_i), 
                .src_req(apb_m0_req), 
                .src_ready(), 
                .in_data(apb_m0_rdata), 
                .dest_rst_n(apb_s0_presetn_i), 
                .dest_clk(apb_s0_pclk_i), 
                .dest_valid(apb_s0_valid), 
                .dest_ack(apb_s0_ack), 
                .out_data(apb_s0_rdata)) ; 
    // apb_s0_valid wired to apb_s0_ack ensures that apb_s0_pready_slv_o is
    // single cycle
    assign apb_s0_pready_slv_o = apb_s0_valid ; 
    assign apb_s0_prdata_slv_o = apb_s0_rdata[(DATA_WIDTH - 1):0] ; 
    assign apb_s0_pslverr_slv_o = (apb_s0_rdata[(M2S_WIDTH - 1)] && PSLVERR_EN) ; 
    wire apb_m2s_resetn ; 
    lpddr4_mc_ipgen_lscc_reset_sync #(.SYNC_STAGE(2),
            .SIM_ASSERT_EN(1'b0)) u_lscc_reset_sync (.src_rst_n(apb_m0_presetn_i), 
                .dest_clk(apb_s0_pclk_i), 
                .dest_rst(), 
                .dest_rst_n(apb_m2s_resetn)) ; 
    assign apb_s0_pend_w = apb_s0_pend_r ; 
    always
        @(posedge apb_s0_pclk_i or 
            negedge apb_s0_presetn_i)
        begin
            if ((!apb_s0_presetn_i)) 
                begin
                    apb_s0_pend_r <=  1'b0 ;
                end
            else
                begin
                    if ((((apb_s0_psel_slv_i & apb_s0_penable_slv_i) & apb_s0_rdy) & (!apb_s0_pend_r))) 
                        begin
                            apb_s0_pend_r <=  1'b1 ;
                        end
                    if (apb_s0_valid) 
                        begin
                            apb_s0_pend_r <=  1'b0 ;
                        end
                    if ((!apb_m2s_resetn)) 
                        begin
                            apb_s0_pend_r <=  1'b0 ;
                        end
                end
        end
endmodule



