module lpddr4_mc_ipgen_mem_sync #(parameter POWER_ON_CLK_CBT = 1) (
    // -------------------------------------------------
    //  PORT DECLARATION
    // -------------------------------------------------
    input sclk_i, 
    input rst_i,  // Active high reset signal
    input sync_clk_i,  // oscillator clk or other constant running low speed
    // clk. Note that this clk should not be coming from
    // clk sources that this module will stop or reset
    // (e.g. ECLKSYNC, CLKDIV, etc.)
    input sync_rst_n_i, 
    input dll_lock_i,  // Lock signal from DDRDLL
    input pll_lock_i,  // Lock signal from PLL
    input ddr_clk_sel_i,  // Selects between operating clock or CBT clk
    input dll_update_en_i,  // Enable DLL code update at the end of clock frequency change
    input ddr_clk_update_i,  // Signal to trigger clock frequency have changed
    input dllcode_upd_n_i, 
    input ddr_ck_en_i, 
    output wire pause_o,  // Pause signal for DQSBUF
    output wire stop_o,  // Stop signal for ECLKSYNC
    output wire freeze_o,  // Freeze signal for DDRDLL
    output wire uddcntln_o,  // Update code signal for DDRDLL
    output reg dll_rst_o,  // Reset signal for DDRDLL
    output wire ddr_rst_o,  // Reset signal for CLKDIV and DDR components
    output reg ddr_ck_en_o, 
    output reg ready_o,  // Ready signal to indicate sync done
    output reg op_clk_en_o, 
    //output reg        sync_rst_o      , // a reset that is synchronized to sync_clk_i
    output sync_clk_update_o, 
    output sync_clk_sel_o, 
    input sync_clk_update_done_i) ;
    // -------------------------------------------------
    //  SIGNAL DECLARATION
    // -------------------------------------------------
    reg [3:0] count ; // Counter for both 4T and 8T delay cycles
    (* syn_preserve=1 *) reg [5:0] cs_memsync ; 
    // FSM Current state
    reg [5:0] ns_memsync ; // FSM Next state
    reg [1:0] flag ; // Signal to determine next FSM state
    reg [1:0] flag_d ; // Registered flag_d signal
    reg lock_d1 ; // Sync register for pll_lock_i & dll_lock_i input
    reg lock_d2 ; // Sync register for pll_lock_i & dll_lock_i input
    reg ddr_rst_d1 ; // DDR reset when rst input is detected
    reg rst_r ; 
    reg update_sr0 ; 
    reg update_sr1 ; 
    reg update_sr2 ; 
    reg update_r ; 
    //reg                clksw_done_r;
    reg dll_update_d1_r ; 
    reg dll_update_d2_r ; 
    reg dll_update_int_r ; // internal dll update_en
    (* syn_preserve=1 *) reg ddr_clk_update_i_r ; 
    (* syn_preserve=1 *) reg ddr_clk_sel_i_r ; 
    (* syn_preserve=1, CDC_Register=2 *) reg ddr_clk_sel_d1_r ; 
    reg ddr_clk_sel_d2_r ; 
    //reg                count_en_r;
    //reg [5:0]          count_r;
    reg ddr_rst_en_r ; 
    (* syn_preserve=1 *) reg friz2init_tgle_r ; 
    (* syn_preserve=1 *) reg friz2init_tgle_rep_r ; 
    wire friz2init_tgle_nxt ; 
    (* syn_preserve=1, CDC_Register=2 *) reg friz2init_tgle_sr0 ; 
    reg friz2init_tgle_sr1 ; 
    reg friz2init_tgle_sr2 ; 
    (* syn_preserve=1, CDC_Register=2 *) reg sync_clk_update_sr0 ; 
    reg sync_clk_update_sr1 ; 
    reg sync_clk_update_sr2 ; 
    wire counter_4t ; // Signal for counter to count up to 4T only
    wire ddr_rst_d ; // DDR reset output of FSM
    wire update_w ; 
    // -------------------------------------------------
    //  PARAMETERS
    // -------------------------------------------------
    // FSM States
    // Each bit is equivalent to an fsm output in the following order
    //     FORMAT:       freeze stop ddr_rst pause uddcntln ready
    localparam INIT = 6'b000010 ; 
    localparam FREEZE = 6'b100010 ; 
    localparam STOP = 6'b110010 ; 
    localparam DDR = 6'b111010 ; 
    localparam PAUSE = 6'b000110 ; 
    localparam UDDCNTLN = 6'b000100 ; 
    localparam READY = 6'b000011 ; 
    localparam UPDATE_PAUSE = 6'b000111 ; 
    localparam UPDATE_UDDCNTLN = 6'b000101 ; 
    // Maximum Count
    localparam COUNT_8T = 15 ; // 7; // 8T timing 
    localparam COUNT_4T = 7 ; // 3; // 4T timing
    localparam COUNT_LOCK = 13 ; // 5; // 8T timing for synchronized lock
    // -------------------------------------------------
    //  CONTINUOUS ASSIGNMENTS
    // -------------------------------------------------
    (* syn_preserve=1 *) reg ready_r ; 
    wire ready ; 
    assign ready = cs_memsync[0] ; 
    // Note: The uddcntln_o is async to ECLK on DDRDLL
    assign uddcntln_o = (cs_memsync[1] & dllcode_upd_n_i) ; // For periodic VT compensation
    assign pause_o = cs_memsync[2] ; 
    assign ddr_rst_d = cs_memsync[3] ; 
    assign stop_o = cs_memsync[4] ; 
    assign freeze_o = cs_memsync[5] ; 
    //assign ddr_rst   = ddr_rst_d || ddr_rst_d1;
    // Assert counter_4t to count only up to CNT_4T parameter
    assign counter_4t = (cs_memsync[5] || cs_memsync[2]) ; 
    // -------------------------------------------------
    //  SYNCHRONIZER FOR DLL_LOCK and clock update
    // -------------------------------------------------
    reg [3:0] dll_lock_i_r ; 
    always
        @(posedge sync_clk_i or 
            negedge sync_rst_n_i)
        begin
            if ((!sync_rst_n_i)) 
                begin
                    lock_d1 <=  1'b0 ;
                    lock_d2 <=  1'b0 ;
                    ddr_rst_en_r <=  1'b1 ;
                    sync_clk_update_sr0 <=  1'b0 ;
                    sync_clk_update_sr1 <=  1'b0 ;
                    sync_clk_update_sr2 <=  1'b0 ;
                    dll_lock_i_r <=  4'b1111 ;
                end
            else
                begin
                    lock_d1 <=  (dll_lock_i & pll_lock_i) ;
                    lock_d2 <=  lock_d1 ;
                    if (((cs_memsync == READY) && update_w)) 
                        ddr_rst_en_r <=  1'b0 ;
                    else
                        if (((cs_memsync == STOP) && flag[0])) 
                            // reset phase is done
                            ddr_rst_en_r <=  1'b1 ;
                    sync_clk_update_sr0 <=  ddr_clk_update_i_r ;
                    sync_clk_update_sr1 <=  sync_clk_update_sr0 ;
                    sync_clk_update_sr2 <=  sync_clk_update_sr1 ;
                    dll_lock_i_r <=  {dll_lock_i_r[2:0],
                            dll_lock_i} ;
                end
        end
    // -------------------------------------------------
    //  CURRENT STATE & OUTPUT REGISTERS
    // -------------------------------------------------
    wire sync_reset ; 
    assign sync_reset = (((~sync_rst_n_i) | sync_clk_update_o) | (dll_lock_i_r[3:2] == 2'b10)) ; 
    always
        @(posedge sync_clk_i or 
            posedge sync_reset)
        begin
            if (sync_reset) 
                begin
                    cs_memsync <=  INIT ;
                    ready_r <=  1'b0 ;
                    ddr_rst_d1 <=  1'b1 ;
                    dll_rst_o <=  1'b1 ;
                    flag <=  2'b00 ;
                end
            else
                begin
                    cs_memsync <=  ns_memsync ;
                    ready_r <=  ns_memsync[0] ;
                    ddr_rst_d1 <=  1'b0 ;
                    dll_rst_o <=  1'b0 ;
                    flag <=  flag_d ;
                end
        end
    wire friz2init_tgle_w = (friz2init_tgle_sr2 ^ friz2init_tgle_sr1) ; 
    wire dll_rst_in_w = ((!sync_rst_n_i) | (friz2init_tgle_w & dll_update_en_i)) ; 
    reg dll_rst_in_r ; 
    // DLL reset synchronizer use SCLK since ECLK is very fast for the fabric
    // This is OK since SCLK is in sync with ECLK
    always
        @(posedge sclk_i or 
            posedge dll_rst_in_w)
        begin
            if (dll_rst_in_w) 
                begin
                    dll_rst_in_r <=  1'b1 ;
                    //dll_rst_o         <= 1'b1;
                end
            else
                begin
                    dll_rst_in_r <=  1'b0 ;
                    //dll_rst_o         <= dll_rst_in_r;
                end
        end
    //reg ddr_rst_in_w = sync_rst_o | (ddr_rst_d & ddr_rst_en_r);
    //reg ddr_rst_in_r;
    // DDR primitives reset synchronizer
    // This is sync to sync_clk_i because ddr clock is stopped during reset
    //always @ (posedge sync_clk_i or posedge sync_rst_o) begin
    //  if (sync_rst_o) begin
    //    ddr_rst_in_r      <= 1'b1;
    //    ddr_rst_o         <= 1'b1;
    //  end
    //  else begin
    //    ddr_rst_in_r      <= 1'b0;
    //    //ddr_rst_o         <= ddr_rst_in_r | (ddr_rst_d & ddr_rst_en_r);
    //    ddr_rst_o         <= ddr_rst_in_r | ddr_rst_d;// ns_memsync[3];
    //  end
    //end
    // DDR primitives have different reset time  
    assign ddr_rst_o = ddr_rst_d ; // ns_memsync[3];
    reg [2:0] freeze_sr ; 
    reg freeze2init ; 
    (* syn_preserve=1 *) reg clk_update_r ; 
    reg clk_update_d1_r ; 
    reg clk_update_d2_r ; 
    reg clk_update_d3_r ; 
    reg clk_update_d4_r ; 
    reg ddr_ck_en_r ; 
    (* syn_preserve=1, CDC_Register=2 *) reg ready_r0 ; 
    reg ready_r1 ; 
    reg ready_r2 ; 
    wire ddr_clk_update_rise = ((!clk_update_r) && ddr_clk_update_i) ; // ddr_clk_update_i asserts
    assign sync_clk_update_o = ((~sync_clk_update_sr2) & sync_clk_update_sr1) ; 
    assign sync_clk_sel_o = ddr_clk_sel_d2_r ; 
    always
        @(posedge sclk_i or 
            posedge rst_i)
        begin
            if (rst_i) 
                begin
                    ddr_ck_en_o <=  1'b1 ;
                    freeze_sr <=  3'h0 ;
                    ddr_clk_update_i_r <=  1'b0 ;
                    clk_update_r <=  1'b0 ;
                    clk_update_d1_r <=  1'b0 ;
                    clk_update_d2_r <=  1'b0 ;
                    clk_update_d3_r <=  1'b0 ;
                    clk_update_d4_r <=  1'b0 ;
                    ready_r0 <=  1'b0 ;
                    ready_r1 <=  1'b0 ;
                    ready_r2 <=  1'b0 ;
                    ready_o <=  1'b0 ;
                    friz2init_tgle_sr0 <=  1'b0 ;
                    friz2init_tgle_sr1 <=  1'b0 ;
                    friz2init_tgle_sr2 <=  1'b0 ;
                    ddr_ck_en_r <=  1'b0 ;
                    ddr_clk_sel_i_r <=  1'b0 ;
                end
            else
                begin
                    freeze_sr <=  {freeze_sr[1:0],
                            freeze_o} ;
                    // delay clock update until DDR ck_o is disabled
                    ddr_clk_update_i_r <=  ddr_clk_update_i ;
                    clk_update_r <=  ddr_clk_update_i ;
                    clk_update_d1_r <=  clk_update_r ;
                    clk_update_d2_r <=  clk_update_r ;
                    clk_update_d3_r <=  clk_update_d2_r ;
                    clk_update_d4_r <=  clk_update_d3_r ;
                    ready_r0 <=  ready_r ;
                    ready_r1 <=  ready_r0 ;
                    ready_r2 <=  ready_r1 ;
                    ddr_ck_en_r <=  ddr_ck_en_i ;
                    if ((ddr_clk_update_rise || (!ddr_ck_en_i))) 
                        ddr_ck_en_o <=  1'b0 ;
                    else
                        //else if (freeze_sr[2] && !freeze_sr[1])  // freeze negates
                        if ((friz2init_tgle_w || ((!ddr_ck_en_r) && ddr_ck_en_i))) 
                            ddr_ck_en_o <=  1'b1 ;
                    if ((ddr_clk_update_rise || (ready_r2 && (!ready_r1)))) 
                        ready_o <=  1'b0 ;
                    else
                        if (((!ready_r2) && ready_r1)) 
                            // internal ready asserts
                            ready_o <=  1'b1 ;
                    friz2init_tgle_sr0 <=  friz2init_tgle_r ;
                    friz2init_tgle_sr1 <=  friz2init_tgle_sr0 ;
                    friz2init_tgle_sr2 <=  friz2init_tgle_sr1 ;
                    ddr_clk_sel_i_r <=  ddr_clk_sel_i ;
                end
        end
    // -------------------------------------------------
    //  RESET SEQUENCE ONE-HOT FSM
    // -------------------------------------------------
    always
        @(*)
        begin
            ns_memsync = cs_memsync ;
            freeze2init = 1'b0 ;
            case (cs_memsync)
            INIT : 
                // INITIAL STATE
                begin
                    // If there is on-going DLL update, wait for it
                    //      if (count_en_r && dll_update_int_r) begin 
                    //        ns_memsync = cs_memsync;
                    //        flag_d     = flag;
                    //      end 
                    //      // Wait for DDRDLL lock
                    //      else 
                    if (((lock_d2 && (flag == 0)) && (count == COUNT_LOCK))) 
                        begin
                            ns_memsync = FREEZE ;
                            flag_d = flag ;
                        end
                    else
                        if (((flag != 0) && (count == COUNT_8T))) 
                            begin
                                if (flag[1]) 
                                    begin
                                        ns_memsync = READY ;
                                        flag_d = flag ;
                                    end
                                else
                                    if (flag[0]) 
                                        begin
                                            ns_memsync = PAUSE ;
                                            flag_d = 2'd0 ;
                                        end
                            end
                        else
                            begin
                                ns_memsync = cs_memsync ;
                                flag_d = flag ;
                            end
                end
            FREEZE : 
                // ASSERT FREEZE STATE
                begin
                    if ((count == COUNT_4T)) 
                        begin
                            if (flag[0]) 
                                begin
                                    //if (sync_clk_update_done_i) begin
                                    freeze2init = 1'b1 ;
                                    ns_memsync = INIT ;
                                    flag_d = flag ;
                                    //end
                                    //else begin // delay the transition
                                    //  ns_memsync = cs_memsync;
                                    //  flag_d     = flag;
                                    //end
                                end
                            else
                                begin
                                    ns_memsync = STOP ;
                                    flag_d = flag ;
                                end
                        end
                    else
                        begin
                            ns_memsync = cs_memsync ;
                            flag_d = flag ;
                        end
                end
            STOP : 
                // ASSERT STOP STATE
                begin
                    if ((count == COUNT_4T)) 
                        begin
                            if (flag[0]) 
                                begin
                                    ns_memsync = FREEZE ;
                                    flag_d = flag ;
                                end
                            else
                                begin
                                    ns_memsync = DDR ;
                                    flag_d = flag ;
                                end
                        end
                    else
                        begin
                            ns_memsync = cs_memsync ;
                            flag_d = flag ;
                        end
                end
            DDR : 
                // ASSERT DDR_RST STATE
                begin
                    flag_d = 2'd1 ;
                    if ((count == COUNT_4T)) 
                        begin
                            ns_memsync = STOP ;
                        end
                    else
                        begin
                            ns_memsync = cs_memsync ;
                        end
                end
            PAUSE : 
                // ASSERT PAUSE STATE
                begin
                    if ((count == COUNT_4T)) 
                        begin
                            if (flag[0]) 
                                begin
                                    ns_memsync = INIT ;
                                    flag_d = 2'd2 ;
                                end
                            else
                                begin
                                    //if (dll_update_int_r) begin
                                    ns_memsync = UDDCNTLN ;
                                    flag_d = flag ;
                                    //end
                                    //else begin
                                    //  ns_memsync = PAUSE;   // dont assert UDDCNTLN 
                                    //  flag_d     = 2'd1;
                                    //end
                                end
                        end
                    else
                        begin
                            ns_memsync = cs_memsync ;
                            flag_d = flag ;
                        end
                end
            UDDCNTLN : 
                // ASSERT UDDCNTLN STATE
                begin
                    flag_d = 2'd1 ;
                    if ((count == COUNT_4T)) 
                        begin
                            ns_memsync = PAUSE ;
                        end
                    else
                        begin
                            ns_memsync = cs_memsync ;
                        end
                end
            READY : 
                // ASSERT READY STATE
                begin
                    flag_d = 2'd0 ;
                    // Check if DDRDLL is still locked
                    if ((!lock_d2)) 
                        begin
                            ns_memsync = INIT ;
                        end
                    else
                        // Check if there is an update request
                        //else if (update_w) begin
                        //    ns_memsync = FREEZE;
                        //    flag_d = 3'd0;
                        //end
                        begin
                            ns_memsync = cs_memsync ;
                        end
                end
            default : 
                // Default State
                begin
                    ns_memsync = cs_memsync ;
                    flag_d = flag ;
                end
            endcase 
        end
    // -------------------------------------------------
    //  COUNTER
    // -------------------------------------------------
    always
        @(posedge sync_clk_i or 
            negedge sync_rst_n_i)
        begin
            if ((!sync_rst_n_i)) 
                begin
                    count <=  'h0 ;
                end
            else
                if (((((counter_4t && (count == COUNT_4T)) || ((cs_memsync == INIT) && (!lock_d2))) || ((flag == 0) && (count == COUNT_LOCK))) || ((cs_memsync == READY) && ready))) 
                    begin
                        count <=  'h0 ;
                    end
                else
                    begin
                        count <=  (count + 3'd1) ;
                    end
        end
    //// Reset generation
    //always @(posedge sync_clk_i or posedge rst_i) begin
    //  if (rst_i) begin
    //     rst_r         <= 1'b1;
    //     sync_rst_o    <= 1'b1;
    //  end
    //  else begin
    //     rst_r         <= 1'b0;
    //     sync_rst_o    <= rst_r;
    //  end
    //end
    assign update_w = ((~update_sr2) & update_sr1) ; // rising edge after double FF
    reg freeze_r ; 
    assign friz2init_tgle_nxt = (freeze2init ? (~friz2init_tgle_rep_r) : friz2init_tgle_rep_r) ; 
    always
        @(posedge sync_clk_i or 
            negedge sync_rst_n_i)
        begin
            if ((!sync_rst_n_i)) 
                begin
                    op_clk_en_o <=  1'b1 ;//~POWER_ON_CLK_CBT[0];
                    freeze_r <=  1'b0 ;
                    update_sr0 <=  1'b0 ;
                    update_sr1 <=  1'b0 ;
                    update_sr2 <=  1'b0 ;
                    update_r <=  1'b0 ;
                    ddr_clk_sel_d1_r <=  1'b0 ;
                    ddr_clk_sel_d2_r <=  1'b0 ;
                    dll_update_d1_r <=  1'b0 ;
                    dll_update_d2_r <=  1'b0 ;
                    dll_update_int_r <=  1'b1 ;
                    friz2init_tgle_r <=  1'b0 ;
                    friz2init_tgle_rep_r <=  1'b0 ;
                end
            else
                begin
                    update_sr0 <=  clk_update_d4_r ;// need to delay until ddr_ck_o disables to 1'b0
                    update_sr1 <=  update_sr0 ;
                    update_sr2 <=  update_sr1 ;
                    ddr_clk_sel_d1_r <=  ddr_clk_sel_i_r ;
                    ddr_clk_sel_d2_r <=  ddr_clk_sel_d1_r ;
                    dll_update_d1_r <=  dll_update_en_i ;
                    dll_update_d2_r <=  dll_update_d1_r ;
                    if (update_w) 
                        begin
                            dll_update_int_r <=  dll_update_d2_r ;
                            update_r <=  1'b1 ;// indicates on-going clock frequency change
                        end
                    else
                        if (ready) 
                            begin
                                dll_update_int_r <=  1'b0 ;
                                update_r <=  1'b0 ;
                            end
                    freeze_r <=  cs_memsync[4] ;
                    if (freeze_r) 
                        begin
                            // disable clocks during FREEZE
                            op_clk_en_o <=  1'b0 ;
                        end
                    else
                        if (freeze2init) 
                            begin
                                op_clk_en_o <=  1'b1 ;
                            end
                    friz2init_tgle_r <=  friz2init_tgle_nxt ;
                    friz2init_tgle_rep_r <=  friz2init_tgle_nxt ;
                end
        end
    reg [(17 * 8):1] cs_memsync_str ; 
    always
        @(*)
        begin
            case (cs_memsync)
            INIT : 
                cs_memsync_str <=  "INIT" ;
            FREEZE : 
                cs_memsync_str <=  "FREEZE" ;
            STOP : 
                cs_memsync_str <=  "STOP" ;
            DDR : 
                cs_memsync_str <=  "DDR" ;
            PAUSE : 
                cs_memsync_str <=  "PAUSE" ;
            UDDCNTLN : 
                cs_memsync_str <=  "UDDCNTLN" ;
            READY : 
                cs_memsync_str <=  "READY" ;
            UPDATE_PAUSE : 
                cs_memsync_str <=  "UPDATE_PAUSE" ;
            UPDATE_UDDCNTLN : 
                cs_memsync_str <=  "UPDATE_UDDCNTLN" ;
            default : 
                cs_memsync_str <=  "INVALID" ;
            endcase 
        end

//mem_sync
endmodule



