module lpddr4_mc_ipgen_ca_grp #(parameter integer CS_WIDTH = 1, 
        parameter integer ODT_WIDTH = 1, 
        parameter integer CK_WIDTH = 1, 
        parameter integer CA_WIDTH = 6, 
        parameter integer GEARING = 4, 
        parameter CK_DELAY_VAL = "60") (
    // -----------------------------------------------------------------------------
    // Module Parameters
    // -----------------------------------------------------------------------------
    // Currently fixed to 1
    // 6 for LPDDR4
    // -----------------------------------------------------------------------------
    // Input/Output Ports
    // -----------------------------------------------------------------------------
    // Clock and reset
    input eclk_i, 
    input rst_i, 
    input ddr_rst_i, 
    input sclk_i, 
    input ck_en_i, 
    input ready_i, 
    // User Interface
    input [((GEARING * ODT_WIDTH) - 1):0] odt_i, 
    input ck_oe_n_i, 
    input [((GEARING * CS_WIDTH) - 1):0] cke_i, 
    input ca_oe_n_i, 
    input [((GEARING * CS_WIDTH) - 1):0] cs_i, 
    input [((GEARING * CA_WIDTH) - 1):0] ca_i, 
    input reset_n_i, 
    input [1:0] rank_sel_i, 
    input rank_enable, 
    input ca_dly_rk0_upd, 
    input ca_dly_rk1_upd, 
    input cs_dly_rk0_upd, 
    input cs_dly_rk1_upd, 
    input [(CS_WIDTH - 1):0] cmd_cs, 
    input [(CS_WIDTH - 1):0] rd_data_cs, 
    input [(CS_WIDTH - 1):0] wr_data_cs, 
    // LPDDR4 Interface
    //output [CK_WIDTH-1:0]          ck_t_o,
    //output [CK_WIDTH-1:0]          ck_c_o,
    output [(CK_WIDTH - 1):0] ck_o, 
    output [(CS_WIDTH - 1):0] cke_o, 
    output [(CS_WIDTH - 1):0] cs_o, 
    output [(CA_WIDTH - 1):0] ca_o, 
    output [(ODT_WIDTH - 1):0] odt_o, 
    output reg reset_n_o, 
    // Per Bit Delay Adjustment
    input [(CS_WIDTH - 1):0] cs_adj_load_n_i, 
    input [(CS_WIDTH - 1):0] cs_adj_move_i, 
    input [(CS_WIDTH - 1):0] cs_adj_dir_i, 
    output [(CS_WIDTH - 1):0] cs_adj_cout_o, 
    input ca_adj_load_n_i, 
    input ca_adj_move_i, 
    input ca_adj_dir_i, 
    output ca_adj_cout_o, 
    input ck_adj_load_n_i, 
    input ck_adj_move_i, 
    input ck_adj_dir_i, 
    output ck_adj_cout_o) ;
    // -----------------------------------------------------------------------------
    // Wire Declarations
    // -----------------------------------------------------------------------------
    wire [(CK_WIDTH - 1):0] ck_t_o_w ; 
    //wire [CK_WIDTH-1:0]             ck_c_o_w;
    wire [(CS_WIDTH - 1):0] cs_o_w ; 
    wire [(ODT_WIDTH - 1):0] odt_o_w ; 
    wire [(CS_WIDTH - 1):0] cke_o_w ; 
    wire [(CA_WIDTH - 1):0] ca_o_w ; 
    wire [(CK_WIDTH - 1):0] ck_t_w ; 
    //wire [CK_WIDTH-1:0]             ck_c_w ;
    wire [(CS_WIDTH - 1):0] cs_w ; 
    wire [(ODT_WIDTH - 1):0] odt_w ; 
    wire [(CS_WIDTH - 1):0] cke_w ; 
    wire [(CA_WIDTH - 1):0] ca_w ; 
    wire [(CA_WIDTH - 1):0] ca_adj_cout_w ; 
    wire [(CK_WIDTH - 1):0] ck_adj_cout_w ; 
    reg [(CA_WIDTH - 1):0] ca_adj_cout_r ; 
    reg [(CK_WIDTH - 1):0] ck_adj_cout_r ; 
    reg [(CS_WIDTH - 1):0] cke_last_r ; 
    localparam ST_W = 3 ; 
    localparam ST_IDLE = 3'h0 ; 
    localparam ST_LOADN = 3'h1 ; 
    localparam ST_LDMOV = 3'h2 ; 
    localparam ST_LOAD = 3'h3 ; 
    localparam ST_WAIT = 3'h4 ; 
    localparam ST_MOV = 3'h5 ; 
    localparam ST_DONE = 3'h6 ; 
    localparam LAST_CNT = (CK_DELAY_VAL << 1) ; 
    reg ck_adj_load_n_r ; 
    reg ck_adj_move_r ; 
    reg [7:0] ck_cntr_r ; 
    reg [(ST_W - 1):0] CK_AdjCurrState ; 
    reg [(ST_W - 1):0] CK_AdjNextState ; 
    //wire            cnt_eq_3_w;
    //wire            cnt_eq_4_w;
    //wire            cnt_done_w;
    wire rank_sel_w ; 
    assign rank_sel_w = ((CS_WIDTH == 2) ? cmd_cs[(CS_WIDTH - 1)] : 1'b0) ; 
    //assign cnt_eq_3_w = ck_cntr_r[1:0] == 2'h3;
    //assign cnt_eq_4_w = ck_cntr_r[2:0] == 3'h4;
    //assign cnt_done_w = ck_cntr_r      == LAST_CNT[7:0];
    assign ca_adj_cout_o = (|ca_adj_cout_r) ; 
    assign ck_adj_cout_o = (|ck_adj_cout_r) ; 
    // -----------------------------------------------------------------------------
    // Generate Variables
    // -----------------------------------------------------------------------------
    genvar i ; 
    // -----------------------------------------------------------------------------
    // Submodule Instantiations
    // -----------------------------------------------------------------------------
    always
        @(posedge sclk_i or 
            posedge rst_i)
        begin
            if (rst_i) 
                cke_last_r <=  'b0 ;
            else
                cke_last_r <=  cke_i[((GEARING - 1) * CS_WIDTH) +: CS_WIDTH] ;
        end
    //always @(*) begin
    //   CK_AdjNextState = CK_AdjCurrState;
    //   case (CK_AdjCurrState) 
    //      ST_IDLE : CK_AdjNextState = ready_i ? ST_LOADN : ST_IDLE;
    //      ST_LOADN: CK_AdjNextState = cnt_eq_3_w ? ST_LDMOV : ST_LOADN;
    //      ST_LDMOV: CK_AdjNextState = cnt_eq_3_w ? ST_LOAD  : ST_LDMOV;
    //      ST_LOAD : CK_AdjNextState = cnt_eq_3_w ? ST_WAIT  : ST_LOAD ;
    //      ST_WAIT : CK_AdjNextState = cnt_eq_3_w ? ST_MOV   : ST_WAIT ;
    //      ST_MOV  : CK_AdjNextState = cnt_done_w ? ST_DONE  : ST_MOV  ;
    //      ST_DONE : CK_AdjNextState = ST_DONE;  // only rst_i can move out of ST_DONE
    //      default : CK_AdjNextState = ST_IDLE;
    //   endcase
    //end
    //
    //always @(posedge sclk_i or posedge rst_i) begin
    //   if (rst_i)
    //     CK_AdjCurrState <= ST_IDLE;
    //   else
    //     CK_AdjCurrState <= CK_AdjNextState;
    //end
    //
    //always @(posedge sclk_i or posedge rst_i) begin
    //   if (rst_i) begin
    //     ck_adj_load_n_r <= 1'b1;
    //     ck_adj_move_r   <= 1'b0;
    //     
    //   end
    //   else begin
    //     ck_adj_load_n_r <= ~((CK_AdjCurrState == ST_LOADN) | (CK_AdjCurrState == ST_LDMOV) | (CK_AdjCurrState == ST_LOAD));
    //     ck_adj_move_r   <= (CK_AdjCurrState == ST_LDMOV) | ((CK_AdjCurrState == ST_MOV) & ck_cntr_r[0]);
    //     if (CK_AdjCurrState == ST_IDLE)
    //        ck_cntr_r     <= 8'h00;
    //     else if ((CK_AdjCurrState == ST_WAIT) && cnt_eq_3_w)
    //        ck_cntr_r     <= 8'h00;
    //     else if (CK_AdjCurrState == ST_DONE)
    //        ck_cntr_r     <= ck_cntr_r;   // dont increment
    //     else 
    //        ck_cntr_r     <= ck_cntr_r + 8'h01;
    //   end
    //end
    generate
        // CK Generation Logic
        for (i = 0;(i < CK_WIDTH);i = (i + 1))
        begin : CK
            if ((GEARING == 2)) 
            //      BB u_CK_c_BB (
            //         .B          (ck_c_o[i]  ),
            //         .I          (ck_c_o_w[i]),
            //         .T          (ck_oe_n_i  ),
            //         .O          (           ));  // No data coming in
                begin : CK_X2
                    ODDRX4 u_CK_t (.D0(1'b0), 
                                .D1(ck_en_i), 
                                .D2(1'b0), 
                                .D3(ck_en_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .ECLK(eclk_i), 
                                .Q(ck_t_w[i])) ; 
                end
            else
                begin : CK_X4
                    ODDRX4 u_CK_t (.D0(1'b0), 
                                .D1(ck_en_i), 
                                .D2(1'b0), 
                                .D3(ck_en_i), 
                                .D4(1'b0), 
                                .D5(ck_en_i), 
                                .D6(1'b0), 
                                .D7(ck_en_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .ECLK(eclk_i), 
                                .Q(ck_t_w[i])) ; 
                end
            //      DELAYB #(
            //         .DEL_MODE ("USER_DEFINED"),
            //         .DEL_VALUE(CK_DELAY_VAL  ))
            //      u_CK_DLB (
            //         .A   (ck_w[i]), 
            //         .Z   (ck_o_w[i]));
            DELAYC #(.DEL_MODE("USER_DEFINED"),
                    .DEL_VALUE("0"),
                    .COARSE_DELAY_MODE("STATIC"),
                    .COARSE_DELAY("0NS"),
                    .EDGE_MONITOR("DISABLED"),
                    .WAIT_FOR_EDGE("DISABLED")) u_CK_t_DLA (.A(ck_t_w[i]), 
                        .LOAD_N(ck_adj_load_n_i), 
                        .MOVE(ck_adj_move_i), 
                        .DIRECTION(1'b0),  // always increment
                    .COARSE0(1'b0),  // Check behavior
                    .COARSE1(1'b0),  // Check behavior
                    .Z(ck_t_o_w[i]), 
                        .EDETERR(),  // open
                    .CFLAG(ck_adj_cout_w[i]), 
                        .SCLK(sclk_i), 
                        .ECLK(eclk_i), 
                        .RANKSELECT(1'b0), 
                        .RANKENABLE(1'b0), 
                        .RANK0UPDATE(1'b0), 
                        .RANK1UPDATE(1'b0)) ; // Select from the counter
            //      DELAYA #(
            //         .DEL_MODE ("USER_DEFINED"),
            //         .DEL_VALUE("0"           ))
            //         //.DEL_MODE("DQS_CMD_CLK"  ))
            //      u_CK_c_DLA (
            //         .A          (ck_c_w[i]      ), 
            //         .LOAD_N     (ck_adj_load_n_r), 
            //         .MOVE       (ck_adj_move_r  ), 
            //         .DIRECTION  (1'b0           ), // always increment
            //         .COARSE0    (1'b0           ), // Check behavior
            //         .COARSE1    (1'b0           ), // Check behavior
            //         .Z          (ck_c_o_w[i]    ), 
            //         .EDETERR    (               ), // open
            //         .CFLAG      (               ), 
            //         .RANKSELECT (1'b0           ), 
            //         .RANKENABLE (1'b0           ), 
            //         .RANK0UPDATE(1'b0           ), 
            //         .RANK1UPDATE(1'b0           ));
            BB u_CK_t_BB (//         .B          (ck_t_o[i]  ),
                    .B(ck_o[i]), 
                        .I(ck_t_o_w[i]), 
                        .T(ck_oe_n_i), 
                        .O()) ; // No data coming in
        end
        // CKE Generation Logic
        for (i = 0;(i < CS_WIDTH);i = (i + 1))
        begin : CKE
            if ((GEARING == 2)) 
                begin : CKE_X2
                    ODDRX2 u_CKE (.D0(cke_i[((0 * CS_WIDTH) + i)]), 
                                .D1(cke_i[((0 * CS_WIDTH) + i)]), 
                                .D2(cke_i[((1 * CS_WIDTH) + i)]), 
                                .D3(cke_i[((1 * CS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(cke_w[i])) ; 
                end
            else
                begin : CKE_X4
                    ODDRX4 u_CKE (.D0(cke_i[((0 * CS_WIDTH) + i)]), 
                                .D1(cke_i[((0 * CS_WIDTH) + i)]), 
                                .D2(cke_i[((1 * CS_WIDTH) + i)]), 
                                .D3(cke_i[((1 * CS_WIDTH) + i)]), 
                                .D4(cke_i[((2 * CS_WIDTH) + i)]), 
                                .D5(cke_i[((2 * CS_WIDTH) + i)]), 
                                .D6(cke_i[((3 * CS_WIDTH) + i)]), 
                                .D7(cke_i[((3 * CS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(cke_w[i])) ; 
                end
            //      DELAYB #(
            //         .DEL_MODE ("USER_DEFINED"),
            //         .DEL_VALUE(CK_DELAY_VAL  ))
            //         //.DEL_MODE("DQS_CMD_CLK"  ))
            //      u_CKE_DLB (
            //         .A   (cke_w[i]), 
            //         .Z   (cke_o_w[i]));
            DELAYC #(.DEL_MODE("USER_DEFINED"),
                    .DEL_VALUE("0"),
                    .COARSE_DELAY_MODE("STATIC"),
                    .COARSE_DELAY("0NS"),
                    .EDGE_MONITOR("DISABLED"),
                    .WAIT_FOR_EDGE("DISABLED")) u_CKE_DLA (.A(cke_w[i]), 
                        .LOAD_N(ck_adj_load_n_i), 
                        .MOVE(ck_adj_move_i), 
                        .DIRECTION(1'b0),  // always increment
                    .COARSE0(1'b0),  // Check behavior
                    .COARSE1(1'b0),  // Check behavior
                    .Z(cke_o_w[i]), 
                        .EDETERR(),  // open
                    .CFLAG(), 
                        .SCLK(sclk_i), 
                        .ECLK(eclk_i), 
                        .RANKSELECT(1'b0), 
                        .RANKENABLE(1'b0), 
                        .RANK0UPDATE(1'b0), 
                        .RANK1UPDATE(1'b0)) ; 
            BB u_CKE_BB (.B(cke_o[i]), 
                        .I(cke_o_w[i]), 
                        .T(ck_oe_n_i), 
                        .O()) ; // No data coming in
        end
        // ODT Generation Logic
        for (i = 0;(i < ODT_WIDTH);i = (i + 1))
        begin : ODT
            if ((GEARING == 2)) 
            // for loop (ODT)
                begin : ODT_X2
                    //         OSHX2 u_ODT (
                    //            .D0  (odt_i[0*CS_WIDTH+i]), 
                    //            .D1  (odt_i[1*CS_WIDTH+i]), 
                    //            .ECLK(eclk_i     ), 
                    //            .SCLK(sclk_i     ), 
                    //            .RST (ddr_rst_i  ), 
                    //            .Q   (odt_w[i]    ));
                    ODDRX2 u_ODT (.D0(odt_i[((0 * CK_WIDTH) + i)]), 
                                .D1(odt_i[((0 * CK_WIDTH) + i)]), 
                                .D2(odt_i[((1 * CK_WIDTH) + i)]), 
                                .D3(odt_i[((1 * CK_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(odt_w[i])) ; 
                end
            else
                begin : ODT_X4
                    //         OSHX4 u_ODT (
                    //            .D0  (odt_i[0*ODT_WIDTH+i]), 
                    //            .D1  (odt_i[1*ODT_WIDTH+i]), 
                    //            .D2  (odt_i[2*ODT_WIDTH+i]), 
                    //            .D3  (odt_i[3*ODT_WIDTH+i]), 
                    //            .ECLK(eclk_i      ), 
                    //            .SCLK(sclk_i      ), 
                    //            .RST (ddr_rst_i   ), 
                    //            .Q   (odt_w[i]    ));
                    ODDRX4 u_ODT (.D0(odt_i[((0 * ODT_WIDTH) + i)]), 
                                .D1(odt_i[((0 * ODT_WIDTH) + i)]), 
                                .D2(odt_i[((1 * ODT_WIDTH) + i)]), 
                                .D3(odt_i[((1 * ODT_WIDTH) + i)]), 
                                .D4(odt_i[((2 * ODT_WIDTH) + i)]), 
                                .D5(odt_i[((2 * ODT_WIDTH) + i)]), 
                                .D6(odt_i[((3 * ODT_WIDTH) + i)]), 
                                .D7(odt_i[((3 * ODT_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(odt_w[i])) ; 
                end
            //      DELAYB #(
            //         .DEL_MODE ("USER_DEFINED"),
            //         .DEL_VALUE(CK_DELAY_VAL  ))
            //      u_ODT_DLB (
            //         .A   (odt_w[i]), 
            //         .Z   (odt_o_w[i]));
            DELAYC #(.DEL_MODE("USER_DEFINED"),
                    .DEL_VALUE("0"),
                    .COARSE_DELAY_MODE("STATIC"),
                    .COARSE_DELAY("0NS"),
                    .EDGE_MONITOR("DISABLED"),
                    .WAIT_FOR_EDGE("DISABLED")) u_ODT_DLA (.A(odt_w[i]), 
                        .LOAD_N(ck_adj_load_n_i), 
                        .MOVE(ck_adj_move_i), 
                        .DIRECTION(1'b0),  // always increment
                    .COARSE0(1'b0),  // Check behavior
                    .COARSE1(1'b0),  // Check behavior
                    .Z(odt_o_w[i]), 
                        .EDETERR(),  // open
                    .CFLAG(), 
                        .SCLK(sclk_i), 
                        .ECLK(eclk_i), 
                        .RANKSELECT(1'b0), 
                        .RANKENABLE(1'b0), 
                        .RANK0UPDATE(1'b0), 
                        .RANK1UPDATE(1'b0)) ; 
            BB u_ODT_BB (.B(odt_o[i]), 
                        .I(odt_o_w[i]), 
                        .T(ca_oe_n_i), 
                        .O()) ; // No data coming in
        end
        // CS Generation Logic
        for (i = 0;(i < CS_WIDTH);i = (i + 1))
        begin : CS
            if ((GEARING == 2)) 
                begin : CS__X2
                    OSHX2 u_CS (.D0(cs_i[((0 * CS_WIDTH) + i)]), 
                                .D1(cs_i[((1 * CS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(cs_w[i])) ; 
                end
            else
                begin : CS_X4
                    //         OSHX4 u_CS (
                    //            .D0  (cs_i[0*CS_WIDTH+i]), 
                    //            .D1  (cs_i[1*CS_WIDTH+i]), 
                    //            .D2  (cs_i[2*CS_WIDTH+i]), 
                    //            .D3  (cs_i[3*CS_WIDTH+i]), 
                    //            .ECLK(eclk_i     ), 
                    //            .SCLK(sclk_i     ), 
                    //            .RST (ddr_rst_i  ), 
                    //            .Q   (cs_w[i]    ));
                    ODDRX4 u_CS (.D0(cs_i[((0 * CS_WIDTH) + i)]), 
                                .D1(cs_i[((0 * CS_WIDTH) + i)]), 
                                .D2(cs_i[((1 * CS_WIDTH) + i)]), 
                                .D3(cs_i[((1 * CS_WIDTH) + i)]), 
                                .D4(cs_i[((2 * CS_WIDTH) + i)]), 
                                .D5(cs_i[((2 * CS_WIDTH) + i)]), 
                                .D6(cs_i[((3 * CS_WIDTH) + i)]), 
                                .D7(cs_i[((3 * CS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(cs_w[i])) ; 
                end
            DELAYC #(.DEL_MODE("USER_DEFINED"),
                    .DEL_VALUE("0"),
                    .COARSE_DELAY_MODE("STATIC"),
                    .COARSE_DELAY("0NS"),
                    .EDGE_MONITOR("DISABLED"),
                    .WAIT_FOR_EDGE("DISABLED")) u_CS_DLA (.A(cs_w[i]), 
                        .LOAD_N(cs_adj_load_n_i[i]), 
                        .MOVE(cs_adj_move_i[i]), 
                        .DIRECTION(cs_adj_dir_i[i]), 
                        .COARSE0(1'b0),  // Check behavior
                    .COARSE1(1'b0),  // Check behavior
                    .Z(cs_o_w[i]), 
                        .EDETERR(),  // open
                    .CFLAG(cs_adj_cout_o[i]), 
                        .SCLK(sclk_i), 
                        .ECLK(eclk_i), 
                        .RANKSELECT(1'b0), 
                        .RANKENABLE(1'b0), 
                        .RANK0UPDATE(1'b0), 
                        .RANK1UPDATE(1'b0)) ; 
            BB u_CS_BB (.B(cs_o[i]), 
                        .I(cs_o_w[i]), 
                        .T(ca_oe_n_i), 
                        .O()) ; // No data coming in
        end
        // CA Generation Logic
        for (i = 0;(i < CA_WIDTH);i = (i + 1))
        begin : CA
            if ((GEARING == 2)) 
                begin : CA_X2
                    OSHX2 u_CA (.D0(ca_i[((0 * CA_WIDTH) + i)]), 
                                .D1(ca_i[((1 * CA_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(ca_w[i])) ; 
                end
            else
                begin : CA_X4
                    //         OSHX4 u_CA (
                    //            .D0  (ca_i[0*CA_WIDTH+i]), 
                    //            .D1  (ca_i[1*CA_WIDTH+i]), 
                    //            .D2  (ca_i[2*CA_WIDTH+i]), 
                    //            .D3  (ca_i[3*CA_WIDTH+i]), 
                    //            .ECLK(eclk_i     ), 
                    //            .SCLK(sclk_i     ), 
                    //            .RST (ddr_rst_i  ), 
                    //            .Q   (ca_w[i]    ));
                    ODDRX4 u_CA (.D0(ca_i[((0 * CA_WIDTH) + i)]), 
                                .D1(ca_i[((0 * CA_WIDTH) + i)]), 
                                .D2(ca_i[((1 * CA_WIDTH) + i)]), 
                                .D3(ca_i[((1 * CA_WIDTH) + i)]), 
                                .D4(ca_i[((2 * CA_WIDTH) + i)]), 
                                .D5(ca_i[((2 * CA_WIDTH) + i)]), 
                                .D6(ca_i[((3 * CA_WIDTH) + i)]), 
                                .D7(ca_i[((3 * CA_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(ddr_rst_i), 
                                .Q(ca_w[i])) ; 
                end
            DELAYC #(.DEL_MODE("USER_DEFINED"),
                    .DEL_VALUE("0"),
                    .COARSE_DELAY_MODE("STATIC"),
                    .COARSE_DELAY("0NS"),
                    .EDGE_MONITOR("DISABLED"),
                    .WAIT_FOR_EDGE("DISABLED")) u_CA_DLA (.A(ca_w[i]), 
                        .LOAD_N(ca_adj_load_n_i), 
                        .MOVE(ca_adj_move_i), 
                        .DIRECTION(ca_adj_dir_i), 
                        .COARSE0(1'b0),  // Check behavior
                    .COARSE1(1'b0),  // Check behavior
                    .Z(ca_o_w[i]), 
                        .EDETERR(),  // open
                    .CFLAG(ca_adj_cout_w[i]), 
                        .SCLK(sclk_i), 
                        .ECLK(eclk_i), 
                        .RANKSELECT(1'b0), 
                        .RANKENABLE(1'b0), 
                        .RANK0UPDATE(1'b0), 
                        .RANK1UPDATE(1'b0)) ; 
            BB u_CA_BB (.B(ca_o[i]), 
                        .I(ca_o_w[i]), 
                        .T(ca_oe_n_i), 
                        .O()) ; // No data coming in
        end
    endgenerate
    //// simply making the reset signal synchronized to ECLK
    //OSHX4 u_reset_n (
    //   .D0  (reset_n_i), 
    //   .D1  (reset_n_i), 
    //   .D2  (reset_n_i), 
    //   .D3  (reset_n_i), 
    //   .ECLK(eclk_i   ), 
    //   .SCLK(sclk_i   ), 
    //   .RST (rst_i    ), 
    //   .Q   (reset_n_o));
    // reset going to memory is not affected by other reset so that the controller has full control over it
    //   always @(posedge sclk_i)
    //       reset_n_o <= reset_n_i;
    //   assign reset_n_o = reset_n_i;  // For UCSIP-1278
    always
        @(posedge sclk_i or 
            posedge rst_i)
        if (rst_i) 
            begin
                ca_adj_cout_r <=  {CA_WIDTH{1'b0}} ;
                ck_adj_cout_r <=  {CK_WIDTH{1'b0}} ;
                reset_n_o <=  1'b0 ;
            end
        else
            begin
                ca_adj_cout_r <=  ca_adj_cout_w ;
                ck_adj_cout_r <=  ck_adj_cout_w ;
                reset_n_o <=  reset_n_i ;// For UCSIP-1278
            end
endmodule



