//`include "mem_sync.v"
module lpddr4_mc_ipgen_dq_dqs_dm_unit #(parameter integer CS_WIDTH = 1, 
        parameter INTERFACE_TYPE = "LPDDR4", 
        parameter FAMILY = "LFCPNX", 
        parameter DATA_MASK_ENABLE = 1, 
        parameter integer BUS_WIDTH = 16, 
        parameter integer DQS_WIDTH = (BUS_WIDTH / 8), 
        parameter integer GEARING = 4, 
        parameter DQS_RD_DEL_VALUE = "0", 
        parameter DQS_RD_DEL_SIGN = "POSITIVE", 
        parameter DQS_WR_DEL_VALUE = "0", 
        parameter DQS_WR_DEL_SIGN = "POSITIVE", 
        parameter ALIGN_PIPELINE_EN = 1) (
    // -----------------------------------------------------------------------------
    // Module Parameters
    // -----------------------------------------------------------------------------
    // Enabled for testing
    // -----------------------------------------------------------------------------
    // Input/Output Ports
    // -----------------------------------------------------------------------------
    input eclk_i, 
    input sclk_i, 
    input pause_i, 
    input srst_i, 
    input rst_i, 
    //input                             iddr_rst_i, 
    // User Interface
    //input                             rank0update,
    //input                             rank1update,
    input [1:0] rank_sel_i, 
    input rank_enable, 
    input [((DQS_WIDTH * GEARING) - 1):0] dq_oe_n_i, 
    input [(((DQS_WIDTH * GEARING) * 2) - 1):0] dmi_i, 
    input [(((BUS_WIDTH * GEARING) * 2) - 1):0] dq_i, 
    output [(((DQS_WIDTH * GEARING) * 2) - 1):0] dmi_o, 
    output [(((BUS_WIDTH * GEARING) * 2) - 1):0] dq_o, 
    input [((DQS_WIDTH * GEARING) - 1):0] dqs_oe_n_i, 
    input [(((DQS_WIDTH * GEARING) * 2) - 1):0] dqs_i, 
    output [(DQS_WIDTH - 1):0] burst_det_o, 
    output [(DQS_WIDTH - 1):0] burst_det_sclk_o, 
    output [(DQS_WIDTH - 1):0] data_valid_o, 
    output [(DQS_WIDTH - 1):0] rd_section_o, 
    input [6:0] vref_i, 
    input [3:0] rd_i, 
    input [((DQS_WIDTH * 4) - 1):0] rd_clksel_i, 
    input selclk_i, 
    input [8:0] dll_code_i, 
    // Per DQS Group Delay Adjustment
    input [(DQS_WIDTH - 1):0] rd_loadn_i, 
    input [(DQS_WIDTH - 1):0] rd_move_i, 
    input [(DQS_WIDTH - 1):0] rd_dir_i, 
    output [(DQS_WIDTH - 1):0] rd_cout_o, 
    input [(DQS_WIDTH - 1):0] wr_loadn_i, 
    input [(DQS_WIDTH - 1):0] wr_move_i, 
    input [(DQS_WIDTH - 1):0] wr_dir_i, 
    output [(DQS_WIDTH - 1):0] wr_cout_o, 
    input [(DQS_WIDTH - 1):0] wrlvl_loadn_i, 
    input [(DQS_WIDTH - 1):0] wrlvl_move_i, 
    input [(DQS_WIDTH - 1):0] wrlvl_dir_i, 
    output [(DQS_WIDTH - 1):0] wrlvl_cout_o, 
    output [(BUS_WIDTH - 1):0] dqwl_o, 
    // Per Bit Delay Adjustment
    input [(BUS_WIDTH - 1):0] dq_out_adj_load_n_i, 
    input [(BUS_WIDTH - 1):0] dq_out_adj_move_i, 
    input [(BUS_WIDTH - 1):0] dq_out_adj_dir_i, 
    output [(BUS_WIDTH - 1):0] dq_out_adj_cout_o, 
    input [(DQS_WIDTH - 1):0] dmi_out_adj_load_n_i, 
    input [(DQS_WIDTH - 1):0] dmi_out_adj_move_i, 
    input [(DQS_WIDTH - 1):0] dmi_out_adj_dir_i, 
    output [(DQS_WIDTH - 1):0] dmi_out_adj_cout_o, 
    input [(BUS_WIDTH - 1):0] dq_in_adj_load_n_i, 
    input [(BUS_WIDTH - 1):0] dq_in_adj_move_i, 
    input [(BUS_WIDTH - 1):0] dq_in_adj_dir_i, 
    output [(BUS_WIDTH - 1):0] dq_in_adj_cout_o, 
    input [(DQS_WIDTH - 1):0] dmi_in_adj_load_n_i, 
    input [(DQS_WIDTH - 1):0] dmi_in_adj_move_i, 
    input [(DQS_WIDTH - 1):0] dmi_in_adj_dir_i, 
    output [(DQS_WIDTH - 1):0] dmi_in_adj_cout_o, 
    input [(DQS_WIDTH - 1):0] dqs_out_adj_load_n_i, 
    input [(DQS_WIDTH - 1):0] dqs_out_adj_move_i, 
    input [(DQS_WIDTH - 1):0] dqs_out_adj_dir_i, 
    output [(DQS_WIDTH - 1):0] dqs_out_adj_cout_o, 
    input dq_dmi_dly_rk0_upd, 
    input dq_dmi_dly_rk1_upd, 
    input dqs_out_dly_rk0_upd, 
    input dqs_out_dly_rk1_upd, 
    //input                             dmi_out_dly_rk0_upd,
    //input                             dmi_out_dly_rk1_upd,
    //input                             dq_in_dly_rk0_upd  ,
    //input                             dq_in_dly_rk1_upd  ,
    //input                             dmi_in_dly_rk0_upd ,
    //input                             dmi_in_dly_rk1_upd ,
    input [(CS_WIDTH - 1):0] rd_data_cs, 
    input [(CS_WIDTH - 1):0] wr_data_cs, 
    // LPDDR4 Interface
    inout [(BUS_WIDTH - 1):0] dq_io, 
    inout [(DQS_WIDTH - 1):0] dqs_io, 
    inout [(DQS_WIDTH - 1):0] dmi_io) ;
    // -----------------------------------------------------------------------------
    // Local Parameters
    // -----------------------------------------------------------------------------
    localparam MODX_VALUE = ((GEARING == 2) ? "MDDRX2" : "MDDRX4") ; 
    localparam DEL_MODE = ((GEARING == 2) ? "DQS_ALIGNED_X2" : "DQS_ALIGNED_X4") ; 
    localparam DMI_WIDTH = (DATA_MASK_ENABLE ? DQS_WIDTH : 0) ; 
    localparam USER_DQSW = ((DQS_WIDTH * GEARING) * 2) ; 
    localparam USER_BUSW = ((BUS_WIDTH * GEARING) * 2) ; 
    localparam DATA_GEAR = (GEARING * 2) ; 
    // This is only added for testing in simulation
    //`define DELAY_ENABLE
    localparam DELAY_LANE = 0 ; 
    // -----------------------------------------------------------------------------
    // Wire Declarations
    // -----------------------------------------------------------------------------
    wire [(DQS_WIDTH - 1):0] dmi_i_bb_w ; 
    wire [(DQS_WIDTH - 1):0] dqsr90_w ; 
    wire [(DQS_WIDTH - 1):0] dqsw270_w ; 
    wire [((DQS_WIDTH * 3) - 1):0] wrpntr_w ; 
    wire [((DQS_WIDTH * 3) - 1):0] rdpntr_w ; 
    wire [(BUS_WIDTH - 1):0] dq_oddr_w ; 
    wire [(BUS_WIDTH - 1):0] dq_o_odla_w ; 
    wire [(BUS_WIDTH - 1):0] dq_iddr_dla_w ; 
    wire [(BUS_WIDTH - 1):0] dq_i_bb_w ; 
    wire [(DQS_WIDTH - 1):0] dq_ts_w ; 
    wire [(BUS_WIDTH - 1):0] dq_ts_odla_w ; 
    wire [(BUS_WIDTH - 1):0] tout_w ; 
    wire [(DQS_WIDTH - 1):0] dqsw_w ; 
    wire [(DQS_WIDTH - 1):0] dqs_o_w ; 
    wire [(DQS_WIDTH - 1):0] dqs_odla_w ; 
    wire [(DQS_WIDTH - 1):0] dqs_ts_w ; 
    wire [(DQS_WIDTH - 1):0] dqs_ts_odla_w ; 
    wire [(DQS_WIDTH - 1):0] dqs_bb_o_w ; 
    wire [(DQS_WIDTH - 1):0] dmi_oddr_w ; 
    wire [(DQS_WIDTH - 1):0] dmi_o_odla_w ; 
    wire [(DQS_WIDTH - 1):0] dmi_iddr_dla_w ; 
    wire [(DQS_WIDTH - 1):0] dmi_ts_odla_w ; 
    //wire                         rank0update;
    //wire                         rank1update;
    wire [(USER_DQSW - 1):0] dmi_w ; 
    wire [(USER_BUSW - 1):0] dq_w ; 
    wire [(DQS_WIDTH - 1):0] data_valid_w ; 
    wire [(DQS_WIDTH - 1):0] choose_delayed_nxt ; 
    wire data_valid_w_all_1 ; 
    wire [(USER_DQSW - 1):0] dmi_ow ; 
    wire [(USER_BUSW - 1):0] dq_ow ; 
    wire [(DQS_WIDTH - 1):0] data_valid_ow ; 
    reg [(USER_DQSW - 1):0] dmi_r ; 
    reg [(USER_BUSW - 1):0] dq_r ; 
    (* syn_preserve=1 *) reg [(DQS_WIDTH - 1):0] data_valid_r ; 
    (* syn_preserve=1 *) reg data_valid_all_1_r ; 
    (* syn_preserve=1 *) reg [(DQS_WIDTH - 1):0] choose_delayed_r ; 
    wire [(USER_DQSW - 1):0] dmi_iw ; 
    wire [(USER_BUSW - 1):0] dq_iw ; 
    wire [(DQS_WIDTH - 1):0] data_valid_iw ; 
    wire rank_sel_w ; 
    assign rank_sel_w = ((CS_WIDTH == 2) ? (rd_data_cs[(CS_WIDTH - 1)] | wr_data_cs[(CS_WIDTH - 1)]) : 1'b0) ; 
    // -----------------------------------------------------------------------------
    // Generate Variables
    // -----------------------------------------------------------------------------
    genvar i, 
        j, 
        k, 
        l ; //, j;
    // -----------------------------------------------------------------------------
    // Assign Statements
    // -----------------------------------------------------------------------------
    assign dqwl_o = dq_iddr_dla_w ; 
    assign tout_w = {8{dq_ts_w}} ; 
    // -----------------------------------------------------------------------------
    // Submodule Instantiations
    // -----------------------------------------------------------------------------
    generate
        for (i = 0;(i < DQS_WIDTH);i = (i + 1))
        begin : DQSBUF
            if ((INTERFACE_TYPE == "LPDDR4")) 
            // for loop DQSBUF
                begin : VREF
                    DQSBUF_IVREF #(.GSR("DISABLED"),
                            .ENABLE_FIFO("ENABLED"),
                            .FORCE_READ("ENABLED"),
                            .FREE_WHEEL("DDR"),
                            .MODX(MODX_VALUE),
                            .MT_EN_READ("ENABLED"),
                            .MT_EN_WRITE("ENABLED"),
                            .MT_EN_WRITE_LEVELING("ENABLED"),
                            .RD_PNTR("0b000"),
                            .READ_ENABLE("ENABLED"),
                            .RX_CENTERED("ENABLED"),
                            .S_READ(DQS_RD_DEL_VALUE),
                            .S_WRITE(DQS_WR_DEL_VALUE),
                            .SIGN_READ(DQS_RD_DEL_SIGN),
                            .SIGN_WRITE(DQS_WR_DEL_SIGN),
                            .UPDATE_QU("UP1_AND_UP0_SAME"),
                            .WRITE_ENABLE("ENABLED"),
                            .SEL_READ_BIT_ENABLE_CYCLES("NORMAL"),
                            .BYPASS_WR_LEVEL_SMTH_LATCH("SMOOTHING_PATH"),
                            .BYPASS_WR_SMTH_LATCH("SMOOTHING_PATH"),
                            .BYPASS_READ_SMTH_LATCH("SMOOTHING_PATH"),
                            .LPDDR4_BL16_EN("ENABLED")) u0_DQSBUF (.BTDETECT(burst_det_o[i]), 
                                .BURSTDETECT(burst_det_sclk_o[i]), 
                                .DATAVALID(data_valid_w[i]), 
                                .DQSI(dqs_bb_o_w[i]),  // DQS BB.O
                            .DQSW(dqsw_w[i]), 
                                .DQSWRD(rd_section_o[i]), 
                                .PAUSE(pause_i), 
                                .RDCLKSEL(rd_clksel_i[(4 * i) +: 4]), 
                                .RDDIR(rd_dir_i[i]), 
                                .RDLOADN(rd_loadn_i[i]), 
                                .RDPNTR(rdpntr_w[(3 * i) +: 3]), 
                                .READ(rd_i), 
                                .READCOUT(rd_cout_o[i]), 
                                .READMOVE(rd_move_i[i]), 
                                .RST(rst_i), 
                                .SCLK(sclk_i), 
                                .SELCLK(selclk_i), 
                                .DQSR90(dqsr90_w[i]), 
                                .DQSW270(dqsw270_w[i]), 
                                .WRCOUT(wr_cout_o[i]), 
                                .WRDIR(wr_dir_i[i]), 
                                .WRLOAD_N(wr_loadn_i[i]), 
                                .WRLVCOUT(wrlvl_cout_o[i]), 
                                .WRLVDIR(wrlvl_dir_i[i]), 
                                .WRLVLOAD_N(wrlvl_loadn_i[i]), 
                                .WRLVMOVE(wrlvl_move_i[i]), 
                                .WRMOVE(wr_move_i[i]), 
                                .WRPNTR(wrpntr_w[(3 * i) +: 3]), 
                                .ECLKIN(eclk_i), 
                                .RSTSMCNT(rst_i), 
                                .DLLCODE(dll_code_i), 
                                .IVREFI(vref_i[6:0])) ; 
                end
            else
                begin : NOVREF
                    DQSBUF #(.GSR("DISABLED"),
                            .ENABLE_FIFO("ENABLED"),
                            .FORCE_READ("ENABLED"),
                            .FREE_WHEEL("DDR"),
                            .MODX(MODX_VALUE),
                            .MT_EN_READ("ENABLED"),
                            .MT_EN_WRITE("ENABLED"),
                            .MT_EN_WRITE_LEVELING("ENABLED"),
                            .RD_PNTR("0b000"),
                            .READ_ENABLE("ENABLED"),
                            .RX_CENTERED("ENABLED"),
                            .S_READ(DQS_RD_DEL_VALUE),
                            .S_WRITE(DQS_WR_DEL_VALUE),
                            .SIGN_READ(DQS_RD_DEL_SIGN),
                            .SIGN_WRITE(DQS_WR_DEL_SIGN),
                            .UPDATE_QU("UP1_AND_UP0_SAME"),
                            .WRITE_ENABLE("ENABLED"),
                            .SEL_READ_BIT_ENABLE_CYCLES("NORMAL"),
                            .BYPASS_WR_LEVEL_SMTH_LATCH("SMOOTHING_PATH"),
                            .BYPASS_WR_SMTH_LATCH("SMOOTHING_PATH"),
                            .BYPASS_READ_SMTH_LATCH("SMOOTHING_PATH")) u0_DQSBUF (.BTDETECT(burst_det_o[i]), 
                                .BURSTDETECT(burst_det_sclk_o[i]), 
                                .DATAVALID(data_valid_w[i]), 
                                .DQSI(dqs_bb_o_w[i]),  // DQS BB.O
                            .DQSW(dqsw_w[i]), 
                                .DQSWRD(rd_section_o[i]), 
                                .PAUSE(pause_i), 
                                .RDCLKSEL(rd_clksel_i), 
                                .RDDIR(rd_dir_i[i]), 
                                .RDLOADN(rd_loadn_i[i]), 
                                .RDPNTR(rdpntr_w[(3 * i) +: 3]), 
                                .READ(rd_i), 
                                .READCOUT(rd_cout_o[i]), 
                                .READMOVE(rd_move_i[i]), 
                                .RST(rst_i), 
                                .SCLK(sclk_i), 
                                .SELCLK(selclk_i), 
                                .DQSR90(dqsr90_w[i]), 
                                .DQSW270(dqsw270_w[i]), 
                                .WRCOUT(wr_cout_o[i]), 
                                .WRDIR(wr_dir_i[i]), 
                                .WRLOAD_N(wr_loadn_i[i]), 
                                .WRLVCOUT(wrlvl_cout_o[i]), 
                                .WRLVDIR(wrlvl_dir_i[i]), 
                                .WRLVLOAD_N(wrlvl_loadn_i[i]), 
                                .WRLVMOVE(wrlvl_move_i[i]), 
                                .WRMOVE(wr_move_i[i]), 
                                .WRPNTR(wrpntr_w[(3 * i) +: 3]), 
                                .ECLKIN(eclk_i), 
                                .RSTSMCNT(rst_i), 
                                .DLLCODE(dll_code_i)) ; 
                end
        end
        // -----------------------------------------------------------------------------
        // DQS Generation Logic
        // -----------------------------------------------------------------------------
        for (i = 0;(i < DQS_WIDTH);i = (i + 1))
        begin : DQS
            if ((GEARING == 2)) 
            // for loop DQS
                begin : DQS_X2
                    //assign dqs_tx_w = {dqs_i[1], 1'b0, dqs_i[0], 1'b0};
                    ODDRX2DQS u_ODDRX2DQS (// Inputs
                            .D0(dqs_i[((0 * DQS_WIDTH) + i)]), 
                                .D1(dqs_i[((1 * DQS_WIDTH) + i)]), 
                                .D2(dqs_i[((2 * DQS_WIDTH) + i)]), 
                                .D3(dqs_i[((3 * DQS_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW(dqsw_w[i]), 
                                // Outputs
                            .Q(dqs_o_w[i])) ; 
                end
            else
                begin : DQS_X4
                    //assign dqs_tx_w = {dqs_i[3], 1'b0, dqs_i[2], 1'b0,
                    //                   dqs_i[1], 1'b0, dqs_i[0], 1'b0};
                    ODDRX4DQS u_ODDRX4DQS (// Inputs
                            .D0(dqs_i[((0 * DQS_WIDTH) + i)]), 
                                .D1(dqs_i[((1 * DQS_WIDTH) + i)]), 
                                .D2(dqs_i[((2 * DQS_WIDTH) + i)]), 
                                .D3(dqs_i[((3 * DQS_WIDTH) + i)]), 
                                .D4(dqs_i[((4 * DQS_WIDTH) + i)]), 
                                .D5(dqs_i[((5 * DQS_WIDTH) + i)]), 
                                .D6(dqs_i[((6 * DQS_WIDTH) + i)]), 
                                .D7(dqs_i[((7 * DQS_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW(dqsw_w[i]), 
                                // Outputs
                            .Q(dqs_o_w[i])) ; 
                end
            if (((FAMILY == "LFCPNX") || (FAMILY == "LFMXO5"))) 
                begin : DQS_JD1
                    /*****
        OUTDELAYA #(
           .MARGIN_TEST_ENABLE("ENABLED")
        ) 
        u_DQS_ODLA (
           .DOUTI              (dqs_o_w[i]             ),
           .TOUTI              (dqs_ts_w[i]            ),
           .TOUT               (dqs_ts_odla_w[i]       ), 
           .DOUT               (dqs_odla_w[i]          ),
           .LOAD_N_LPDDR4_WT   (dqs_out_adj_load_n_i[i]),
           .DIRECTION_LPDDR4_WT(dqs_out_adj_dir_i[i]   ),
           .MOVE_LPDDR4_WT     (dqs_out_adj_move_i[i]  ),
           .COUT_LPDDR4_WT     (dqs_out_adj_cout_o[i]  ));   
      ****/
                    OUTDELAYC #(.MARGIN_TEST_ENABLE("ENABLED")) u_DQS_ODLC (.DOUTI(dqs_o_w[i]), 
                                .TOUTI(dqs_ts_w[i]),  // TS for set of 8-bits
                            .TOUT(dqs_ts_odla_w[i]),  // TS for individual bits
                            .DOUT(dqs_odla_w[i]), 
                                .RANKSELECT(1'b0),  //(|cs_i                ) 
                            .RANKENABLE(1'b0), 
                                .RANK0UPDATE(1'b0), 
                                .RANK1UPDATE(1'b0), 
                                .LOAD_N_LPDDR4_WT(dqs_out_adj_load_n_i[i]), 
                                .DIRECTION_LPDDR4_WT(dqs_out_adj_dir_i[i]), 
                                .MOVE_LPDDR4_WT(dqs_out_adj_move_i[i]), 
                                .COUT_LPDDR4_WT(dqs_out_adj_cout_o[i]), 
                                .SCLK(sclk_i)) ; 
                end
            else
                begin : DQS_J
                    assign dqs_odla_w[i] = dqs_o_w[i] ; 
                    assign dqs_ts_odla_w[i] = dqs_ts_w[i] ; 
                end
            BB u_DQS_BB (.B(dqs_io[i]), 
                        .I(dqs_odla_w[i]), 
                        .T(dqs_ts_odla_w[i]), 
                        .O(dqs_bb_o_w[i])) ; 
        end
        // -----------------------------------------------------------------------------
        // DQ/DQS Tri-State Generation Logic
        // -----------------------------------------------------------------------------
        for (i = 0;(i < DQS_WIDTH);i = (i + 1))
        begin : TS
            if ((GEARING == 2)) 
            // for loop TS
                begin : TS_X2
                    // DQ Tri-State Generation Logic for X2 Gearing
                    TSHX2DQ u_TSHX2DQ (// Inputs
                            .T0(dq_oe_n_i[(((-1) * DQS_WIDTH) + i)]), 
                                .T1(dq_oe_n_i[((1 * DQS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .DQSW270(dqsw270_w[i]), 
                                //Outputs
                            .Q(dq_ts_w[i])) ; 
                    // DQS Tri-State Generation Logic for X2 Gearing
                    TSHX2DQS u_TSHX2DQS (// Inputs
                            .T0(dqs_oe_n_i[((0 * DQS_WIDTH) + i)]), 
                                .T1(dqs_oe_n_i[((1 * DQS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .DQSW(dqsw_w), 
                                // Outputs
                            .Q(dqs_ts_w[i])) ; 
                end
            else
                begin : TS_X4
                    // DQ Tri-State Generation Logic for X4 Gearing
                    TSHX4DQ u_TSHX4DQ (// Inputs
                            .T0(dq_oe_n_i[((0 * DQS_WIDTH) + i)]), 
                                .T1(dq_oe_n_i[((1 * DQS_WIDTH) + i)]), 
                                .T2(dq_oe_n_i[((2 * DQS_WIDTH) + i)]), 
                                .T3(dq_oe_n_i[((3 * DQS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .DQSW270(dqsw270_w[i]), 
                                //Outputs
                            .Q(dq_ts_w[i])) ; 
                    // DQS Tri-State Generation Logic for X4 Gearing
                    TSHX4DQS u_TSHX4DQS (// Inputs
                            .T0(dqs_oe_n_i[((0 * DQS_WIDTH) + i)]), 
                                .T1(dqs_oe_n_i[((1 * DQS_WIDTH) + i)]), 
                                .T2(dqs_oe_n_i[((2 * DQS_WIDTH) + i)]), 
                                .T3(dqs_oe_n_i[((3 * DQS_WIDTH) + i)]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .DQSW(dqsw_w[i]), 
                                // Outputs
                            .Q(dqs_ts_w[i])) ; 
                end
        end
        // -----------------------------------------------------------------------------
        // DQ Generation Logic
        // -----------------------------------------------------------------------------
        for (i = 0;(i < BUS_WIDTH);i = (i + 1))
        begin : DQ
            //	  assign j = i/8;
            if ((GEARING == 2)) 
                begin : DQ_X2
                    ODDRX2DQ u_DQ_ODDRX2DQ (// Inputs
                            .D0(dq_i[((0 * BUS_WIDTH) + i)]), 
                                .D1(dq_i[((1 * BUS_WIDTH) + i)]), 
                                .D2(dq_i[((2 * BUS_WIDTH) + i)]), 
                                .D3(dq_i[((3 * BUS_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW270(dqsw270_w[(i / 8)]), 
                                // Outputs
                            .Q(dq_oddr_w[i])) ; 
                    // IDDRX2DQ
                    IDDRX2DQ u_DQ_IDDRX2DQ (// Inputs
                            .D(dq_iddr_dla_w[i]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                //            .RST                (iddr_rst_i           ),
                            .ECLK(eclk_i), 
                                .DQSR90(dqsr90_w[(i / 8)]), 
                                .RDPNTR0(rdpntr_w[((3 * (i / 8)) + 0)]), 
                                .RDPNTR1(rdpntr_w[((3 * (i / 8)) + 1)]), 
                                .RDPNTR2(rdpntr_w[((3 * (i / 8)) + 2)]), 
                                .WRPNTR0(wrpntr_w[((3 * (i / 8)) + 0)]), 
                                .WRPNTR1(wrpntr_w[((3 * (i / 8)) + 1)]), 
                                .WRPNTR2(wrpntr_w[((3 * (i / 8)) + 2)]), 
                                // Outputs
                            .Q0(dq_w[((0 * BUS_WIDTH) + i)]), 
                                .Q1(dq_w[((1 * BUS_WIDTH) + i)]), 
                                .Q2(dq_w[((2 * BUS_WIDTH) + i)]), 
                                .Q3(dq_w[((3 * BUS_WIDTH) + i)])) ; 
                end
            else
                begin : DQ_X4
                    ODDRX4DQ u_DQ_ODDRX4DQ (// Inputs
                            .D0(dq_i[((0 * BUS_WIDTH) + i)]), 
                                .D1(dq_i[((1 * BUS_WIDTH) + i)]), 
                                .D2(dq_i[((2 * BUS_WIDTH) + i)]), 
                                .D3(dq_i[((3 * BUS_WIDTH) + i)]), 
                                .D4(dq_i[((4 * BUS_WIDTH) + i)]), 
                                .D5(dq_i[((5 * BUS_WIDTH) + i)]), 
                                .D6(dq_i[((6 * BUS_WIDTH) + i)]), 
                                .D7(dq_i[((7 * BUS_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW270(dqsw270_w[(i / 8)]), 
                                // Outputs
                            .Q(dq_oddr_w[i])) ; 
                    // IDDRX2DQ
                    IDDRX4DQ u_DQ_IDDRX4DQ (// Inputs
                            .D(dq_iddr_dla_w[i]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                //            .RST                (iddr_rst_i         ),
                            .ECLK(eclk_i), 
                                .DQSR90(dqsr90_w[(i / 8)]),  //per 8-bit of data
                            .RDPNTR0(rdpntr_w[((3 * (i / 8)) + 0)]), 
                                .RDPNTR1(rdpntr_w[((3 * (i / 8)) + 1)]), 
                                .RDPNTR2(rdpntr_w[((3 * (i / 8)) + 2)]), 
                                .WRPNTR0(wrpntr_w[((3 * (i / 8)) + 0)]), 
                                .WRPNTR1(wrpntr_w[((3 * (i / 8)) + 1)]), 
                                .WRPNTR2(wrpntr_w[((3 * (i / 8)) + 2)]), 
                                // Outputs
                            .Q0(dq_w[((0 * BUS_WIDTH) + i)]), 
                                .Q1(dq_w[((1 * BUS_WIDTH) + i)]), 
                                .Q2(dq_w[((2 * BUS_WIDTH) + i)]), 
                                .Q3(dq_w[((3 * BUS_WIDTH) + i)]), 
                                .Q4(dq_w[((4 * BUS_WIDTH) + i)]), 
                                .Q5(dq_w[((5 * BUS_WIDTH) + i)]), 
                                .Q6(dq_w[((6 * BUS_WIDTH) + i)]), 
                                .Q7(dq_w[((7 * BUS_WIDTH) + i)])) ; 
                end
            if (((FAMILY == "LFCPNX") || (FAMILY == "LFMXO5"))) 
                begin : DQ_JD1
                    /****
        OUTDELAYA #(
           .MARGIN_TEST_ENABLE("ENABLED"))
        u_DQ_ODLA (
           .DOUTI              (dq_oddr_w[i]          ), 
           .TOUTI              (dq_ts_w[i/8]          ),  // TS for set of 8-bits
           .TOUT               (dq_ts_odla_w[i]       ),  // TS for individual bits
           .DOUT               (dq_o_odla_w[i]        ), 
           .LOAD_N_LPDDR4_WT   (dq_out_adj_load_n_i[i]), 
           .DIRECTION_LPDDR4_WT(dq_out_adj_dir_i[i]   ), 
           .MOVE_LPDDR4_WT     (dq_out_adj_move_i[i]  ), 
           .COUT_LPDDR4_WT     (dq_out_adj_cout_o[i]  ));
        
         ******/
                    OUTDELAYC #(.MARGIN_TEST_ENABLE("ENABLED")) u_DQ_ODLC (.DOUTI(dq_oddr_w[i]), 
                                .TOUTI(dq_ts_w[(i / 8)]),  // TS for set of 8-bits
                            .TOUT(dq_ts_odla_w[i]),  // TS for individual bits
                            .DOUT(dq_o_odla_w[i]), 
                                .RANKSELECT(1'b0),  //(|cs_i                ) 
                            .RANKENABLE(1'b0), 
                                .RANK0UPDATE(1'b0), 
                                .RANK1UPDATE(1'b0), 
                                .LOAD_N_LPDDR4_WT(dq_out_adj_load_n_i[i]), 
                                .DIRECTION_LPDDR4_WT(dq_out_adj_dir_i[i]), 
                                .MOVE_LPDDR4_WT(dq_out_adj_move_i[i]), 
                                .COUT_LPDDR4_WT(dq_out_adj_cout_o[i]), 
                                .SCLK(sclk_i)) ; 
                    DELAYC #(.DEL_MODE("USER_DEFINED"),
                            .DEL_VALUE("0"),
                            .COARSE_DELAY_MODE("STATIC"),
                            .COARSE_DELAY("0NS"),
                            .EDGE_MONITOR("DISABLED"),
                            .WAIT_FOR_EDGE("DISABLED")) u_DQ_DLC (.A(dq_i_bb_w[i]), 
                                .LOAD_N(dq_in_adj_load_n_i[i]), 
                                .MOVE(dq_in_adj_move_i[i]), 
                                .DIRECTION(dq_in_adj_dir_i[i]), 
                                .COARSE0(1'b0), 
                                .COARSE1(1'b0), 
                                .Z(dq_iddr_dla_w[i]), 
                                .EDETERR(),  // open, unused for now 
                            .CFLAG(dq_in_adj_cout_o[i]), 
                                .SCLK(sclk_i), 
                                .ECLK(eclk_i), 
                                .RANKSELECT(1'b0), 
                                .RANKENABLE(1'b0), 
                                .RANK0UPDATE(1'b0), 
                                .RANK1UPDATE(1'b0)) ; 
                end
            else
                begin : genblk2
                    assign dq_o_odla_w[i] = dq_oddr_w[i] ; 
                    assign dq_ts_odla_w[i] = dq_ts_w[(i / 8)] ; 
                    assign dq_iddr_dla_w[i] = dq_i_bb_w[i] ; 
                end
            BB u_DQ_BB (.B(dq_io[i]), 
                        .I(dq_o_odla_w[i]), 
                        .T(dq_ts_odla_w[i]), 
                        .O(dq_i_bb_w[i])) ; 
        end
        // -----------------------------------------------------------------------------
        // DM Generation Logic
        // -----------------------------------------------------------------------------
        for (i = 0;(i < DMI_WIDTH);i = (i + 1))
        begin : DMI
            if ((GEARING == 2)) 
            // For loop DMI
                begin : DMI_X2
                    ODDRX2DQ u_DMI_ODDRX2DQ (// Inputs
                            .D0(dmi_i[((0 * DMI_WIDTH) + i)]), 
                                .D1(dmi_i[((1 * DMI_WIDTH) + i)]), 
                                .D2(dmi_i[((2 * DMI_WIDTH) + i)]), 
                                .D3(dmi_i[((3 * DMI_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW270(dqsw270_w[i]), 
                                // Outputs
                            .Q(dmi_oddr_w[i])) ; 
                    IDDRX2DQ u_DMI_IDDRX2DQ (.D(dmi_iddr_dla_w[i]), 
                                .DQSR90(dqsr90_w[i]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                //            .RST             (iddr_rst_i          ),
                            .RDPNTR0(rdpntr_w[(3 * i)]), 
                                .RDPNTR1(rdpntr_w[((3 * i) + 1)]), 
                                .RDPNTR2(rdpntr_w[((3 * i) + 2)]), 
                                .WRPNTR0(wrpntr_w[(3 * i)]), 
                                .WRPNTR1(wrpntr_w[((3 * i) + 1)]), 
                                .WRPNTR2(wrpntr_w[((3 * i) + 2)]), 
                                .Q0(dmi_w[((0 * DMI_WIDTH) + i)]), 
                                .Q1(dmi_w[((1 * DMI_WIDTH) + i)]), 
                                .Q2(dmi_w[((2 * DMI_WIDTH) + i)]), 
                                .Q3(dmi_w[((3 * DMI_WIDTH) + i)])) ; 
                end
            else
                begin : DMI_X4
                    ODDRX4DQ u_DMI_ODDRX4DQ (// Inputs
                            .D0(dmi_i[((0 * DMI_WIDTH) + i)]), 
                                .D1(dmi_i[((1 * DMI_WIDTH) + i)]), 
                                .D2(dmi_i[((2 * DMI_WIDTH) + i)]), 
                                .D3(dmi_i[((3 * DMI_WIDTH) + i)]), 
                                .D4(dmi_i[((4 * DMI_WIDTH) + i)]), 
                                .D5(dmi_i[((5 * DMI_WIDTH) + i)]), 
                                .D6(dmi_i[((6 * DMI_WIDTH) + i)]), 
                                .D7(dmi_i[((7 * DMI_WIDTH) + i)]), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                .ECLK(eclk_i), 
                                .DQSW270(dqsw270_w[i]), 
                                // Outputs
                            .Q(dmi_oddr_w[i])) ; 
                    IDDRX4DQ u_DMI_IDDRX4DQ (.D(dmi_iddr_dla_w[i]), 
                                .DQSR90(dqsr90_w[i]), 
                                .ECLK(eclk_i), 
                                .SCLK(sclk_i), 
                                .RST(rst_i), 
                                //            .RST             (iddr_rst_i          ),
                            .RDPNTR0(rdpntr_w[(3 * i)]), 
                                .RDPNTR1(rdpntr_w[((3 * i) + 1)]), 
                                .RDPNTR2(rdpntr_w[((3 * i) + 2)]), 
                                .WRPNTR0(wrpntr_w[(3 * i)]), 
                                .WRPNTR1(wrpntr_w[((3 * i) + 1)]), 
                                .WRPNTR2(wrpntr_w[((3 * i) + 2)]), 
                                .Q0(dmi_w[((0 * DMI_WIDTH) + i)]), 
                                .Q1(dmi_w[((1 * DMI_WIDTH) + i)]), 
                                .Q2(dmi_w[((2 * DMI_WIDTH) + i)]), 
                                .Q3(dmi_w[((3 * DMI_WIDTH) + i)]), 
                                .Q4(dmi_w[((4 * DMI_WIDTH) + i)]), 
                                .Q5(dmi_w[((5 * DMI_WIDTH) + i)]), 
                                .Q6(dmi_w[((6 * DMI_WIDTH) + i)]), 
                                .Q7(dmi_w[((7 * DMI_WIDTH) + i)])) ; 
                end
            if (((FAMILY == "LFCPNX") || (FAMILY == "LFMXO5"))) 
                begin : DMI_JD1
                    /****
        OUTDELAYA #(
           .MARGIN_TEST_ENABLE("ENABLED"))
        u_DMI_ODLA (
           .DOUTI              (dmi_oddr_w[i]          ), 
           .TOUTI              (dq_ts_w[i]             ), 
           .TOUT               (dmi_ts_odla_w[i]       ), 
           .DOUT               (dmi_o_odla_w[i]        ), 
           .LOAD_N_LPDDR4_WT   (dmi_out_adj_load_n_i[i]), 
           .DIRECTION_LPDDR4_WT(dmi_out_adj_dir_i[i]   ), 
           .MOVE_LPDDR4_WT     (dmi_out_adj_move_i[i]  ), 
           .COUT_LPDDR4_WT     (dmi_out_adj_cout_o[i]  ));
        *****/
                    OUTDELAYC #(.MARGIN_TEST_ENABLE("ENABLED")) u_DMI_ODLC (.DOUTI(dmi_oddr_w[i]), 
                                .TOUTI(dq_ts_w[i]), 
                                .TOUT(dmi_ts_odla_w[i]), 
                                .DOUT(dmi_o_odla_w[i]), 
                                .RANKSELECT(1'b0),  //(|cs_i                ) 
                            .RANKENABLE(1'b0), 
                                .RANK0UPDATE(1'b0), 
                                .RANK1UPDATE(1'b0), 
                                .LOAD_N_LPDDR4_WT(dmi_out_adj_load_n_i[i]), 
                                .DIRECTION_LPDDR4_WT(dmi_out_adj_dir_i[i]), 
                                .MOVE_LPDDR4_WT(dmi_out_adj_move_i[i]), 
                                .COUT_LPDDR4_WT(dmi_out_adj_cout_o[i]), 
                                .SCLK(sclk_i)) ; 
                    DELAYC #(.DEL_MODE("USER_DEFINED"),
                            .DEL_VALUE("0"),
                            .COARSE_DELAY_MODE("STATIC"),
                            .COARSE_DELAY("0NS"),
                            .EDGE_MONITOR("DISABLED"),
                            .WAIT_FOR_EDGE("DISABLED")) u_DMI_DLC (.A(dmi_i_bb_w[i]), 
                                .LOAD_N(dmi_in_adj_load_n_i[i]), 
                                .MOVE(dmi_in_adj_move_i[i]), 
                                .DIRECTION(dmi_in_adj_dir_i[i]), 
                                .COARSE0(1'b0), 
                                .COARSE1(1'b0), 
                                .Z(dmi_iddr_dla_w[i]), 
                                .EDETERR(),  // open, unused for now 
                            .CFLAG(dmi_in_adj_cout_o[i]), 
                                .SCLK(sclk_i), 
                                .ECLK(eclk_i), 
                                .RANKSELECT(1'b0), 
                                .RANKENABLE(1'b0), 
                                .RANK0UPDATE(1'b0), 
                                .RANK1UPDATE(1'b0)) ; 
                end
            else
                begin : DMI_J
                    assign dmi_o_odla_w[i] = dmi_oddr_w[i] ; 
                    assign dmi_ts_odla_w[i] = dq_ts_w[i] ; 
                    assign dmi_iddr_dla_w[i] = dmi_i_bb_w[i] ; 
                end
            BB u_DQ_BB (.B(dmi_io[i]), 
                        .I(dmi_o_odla_w[i]), 
                        .T(dmi_ts_odla_w[i]), 
                        .O(dmi_i_bb_w[i]) //
                    ) ; 
        end
    endgenerate
    generate
        // add logic for choose_delayed
        // do selection like below
        //  dmi_r        choose_delayed[i] ? dmi_r        : dmi_w;
        //  dq_r         choose_delayed[i] ? dq_r         : dq_w;
        //  data_valid_r choose_delayed[i] ? data_valid_r : data_valid_w;
        for (j = 0;(j < DQS_WIDTH);j = (j + 1))
        begin : DQSG_ALIGN
            //      always@(*) begin
            //         if (choose_delayed_r[j])  // De-assert on falling edge of data_valid_w
            //            choose_delayed_nxt[j] = data_valid_w[j];                   
            //         else // Assert on rising edge of data_valid_w and All DQSBUF data valid not aligned
            //            choose_delayed_nxt[j] = data_valid_w[j] & ~data_valid_r[j] & ~data_valid_w_all_1;  
            //      end
            assign data_valid_iw[j] = data_valid_w[j] ; 
            // DQS_ALIGN
            // FIXME: Check in STA if this needs to be registered
            // Assert on rising edge of data_valid_w and All DQSBUF data valid not aligned
            // Assert also on datavalid maintained high and rising edge of data_valid_w_all_1
            // De-assert on falling edge of data_valid_w       
            //      assign choose_delayed_nxt[j] = data_valid_iw[j] & ~data_valid_r[j] ? ~data_valid_w_all_1 :
            //                                       (choose_delayed_r[j] ? data_valid_r[j] : 1'b0);
            assign choose_delayed_nxt[j] = ((choose_delayed_r[j] == 0) ? (((data_valid_iw[j] & (~data_valid_r[j])) & (~data_valid_w_all_1)) | (((data_valid_iw[j] & data_valid_r[j]) & (~data_valid_all_1_r)) & data_valid_w_all_1)) : data_valid_r[j]) ; 
            assign data_valid_ow[j] = (choose_delayed_nxt[j] ? data_valid_r[j] : data_valid_iw[j]) ; 
            for (k = 0;(k < DATA_GEAR);k = (k + 1))
            begin : GEAR
                assign dmi_iw[((k * DMI_WIDTH) + j)] = dmi_w[((k * DMI_WIDTH) + j)] ; 
                // GEAR   
                assign dq_iw[((k * BUS_WIDTH) + (j * 8)) +: 8] = dq_w[((k * BUS_WIDTH) + (j * 8)) +: 8] ; 
                assign dmi_ow[((k * DMI_WIDTH) + j)] = (choose_delayed_nxt[j] ? dmi_r[((k * DMI_WIDTH) + j)] : dmi_iw[((k * DMI_WIDTH) + j)]) ; 
                assign dq_ow[((k * BUS_WIDTH) + (j * 8)) +: 8] = (choose_delayed_nxt[j] ? dq_r[((k * BUS_WIDTH) + (j * 8)) +: 8] : dq_iw[((k * BUS_WIDTH) + (j * 8)) +: 8]) ; 
            end
        end
        if (ALIGN_PIPELINE_EN) 
            begin : PIPE
                reg [(USER_DQSW - 1):0] dmi_or ; 
                reg [(USER_BUSW - 1):0] dq_or ; 
                reg [(DQS_WIDTH - 1):0] data_valid_or ; 
                always
                    @(posedge sclk_i or 
                        posedge srst_i)
                    begin
                        if (srst_i) 
                            data_valid_or <=  {DQS_WIDTH{1'b0}} ;
                        else
                            data_valid_or <=  data_valid_ow ;
                    end
                always
                    @(posedge sclk_i)
                    begin
                        // No need for reset here since dq_r/dmi_r are invalid when data_valid_r=0
                        dmi_or <=  dmi_ow ;
                        dq_or <=  dq_ow ;
                    end
                assign dmi_o = dmi_or ; 
                assign dq_o = dq_or ; 
                assign data_valid_o = data_valid_or ; 
            end
        else
            begin : xPIPE
                assign dmi_o = dmi_ow ; 
                assign dq_o = dq_ow ; 
                assign data_valid_o = data_valid_ow ; 
            end
    endgenerate
    (* syn_preserve=1 *) reg [(DQS_WIDTH - 1):0] rvl_choose_delayed_r ; 
    (* syn_preserve=1 *) reg [(DQS_WIDTH - 1):0] rvl_data_valid_r ; 
    (* syn_preserve=1 *) reg rvl_data_valid_all_1 ; 
    //assign data_valid_w_all_1 = &data_valid_w;
    assign data_valid_w_all_1 = (&data_valid_iw) ; 
    always
        @(posedge sclk_i or 
            posedge srst_i)
        begin
            if (srst_i) 
                begin
                    data_valid_r <=  {DQS_WIDTH{1'b0}} ;
                    choose_delayed_r <=  {DQS_WIDTH{1'b0}} ;
                    data_valid_all_1_r <=  1'b0 ;
                    rvl_choose_delayed_r <=  {DQS_WIDTH{1'b0}} ;
                    rvl_data_valid_r <=  {DQS_WIDTH{1'b0}} ;
                    rvl_data_valid_all_1 <=  1'b0 ;
                end
            else
                begin
                    data_valid_r <=  data_valid_iw ;
                    choose_delayed_r <=  choose_delayed_nxt ;
                    data_valid_all_1_r <=  data_valid_w_all_1 ;
                    rvl_choose_delayed_r <=  choose_delayed_nxt ;
                    rvl_data_valid_r <=  data_valid_iw ;
                    rvl_data_valid_all_1 <=  data_valid_w_all_1 ;
                end
        end
    always
        @(posedge sclk_i)
        begin
            // No need for reset here since dq_r/dmi_r are invalid when data_valid_r=0
            dmi_r <=  dmi_iw ;
            dq_r <=  dq_iw ;
        end

// 4Nu
endmodule



