    //--------------------------------------------------------------------------
    reg [7:0] csr_rdat_nxt ; 
    wire [6:0] csr_addr ; 
    wire csr_wren ; 
    wire wrsel_register_01 ; 
    wire [7:0] pll_register_01_nxt ; 
    wire [7:0] pll_register_01 ; 
    //--------------------------------------------------------------------------
    //--- Registers ---
    //--------------------------------------------------------------------------
    reg phasedir_r ; 
    reg phasestep_r ; 
    reg phaseloadreg_r ; 
    reg [2:0] phasesel_r ; 
    reg [1:0] lmmi_sm_cs ; 
    reg lmmi_ready_r ; 
    reg lmmi_rvalid_r ; 
    reg [7:0] lmmi_rdata_r ; 
    assign pll_lmmi_wr_rdn = usr_lmmi_wr_rdn ; 
    assign pll_lmmi_offset = usr_lmmi_offset ; 
    assign pll_lmmi_wdata = usr_lmmi_wdata ; 
    assign usr_lmmi_ready = lmmi_ready_r ; 
    assign usr_lmmi_rdata_valid = lmmi_rvalid_r ; 
    assign usr_lmmi_rdata = lmmi_rdata_r ; 
    assign csr_phasedir = phasedir_r ; 
    assign csr_phasestep = phasestep_r ; 
    assign csr_phaseloadreg = phaseloadreg_r ; 
    assign csr_phasesel = phasesel_r ; 
    assign csr_wren = ((lmmi_sm_cs == ST_LMMI_WREQ) & usr_lmmi_offset[7]) ; 
    assign csr_addr = usr_lmmi_offset[6:0] ; 
    // CSR write select
    assign wrsel_register_01 = (csr_wren & (csr_addr == ADR_REG_01)) ; 
    // CSR write
    assign pll_register_01_nxt = (wrsel_register_01 ? usr_lmmi_wdata : pll_register_01) ; 
    // Register
    assign pll_register_01 = {pll_lock,
                1'b0,
                phasedir_r,
                phasestep_r,
                phaseloadreg_r,
                phasesel_r} ; 
    //--------------------------------------------
    //-- CSR Read Data --
    //--------------------------------------------
    always
        @(*)
        begin
            case (csr_addr)
            ADR_REG_01 : 
                csr_rdat_nxt = pll_register_01 ;
            default : 
                csr_rdat_nxt = 8'd0 ;
            endcase 
        end//--always @*--
    //--------------------------------------------
    //-- Sequential block --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    /*AUTORESET*/
                    // Beginning of autoreset for uninitialized flops
                    phasedir_r = 1'h0 ;
                    phaseloadreg_r = 1'h0 ;
                    phasesel_r = 3'h0 ;
                    phasestep_r = 1'h0 ;
                    // End of automatics
                end
            else
                begin
                    phasedir_r = pll_register_01_nxt[5] ;
                    phasestep_r = pll_register_01_nxt[4] ;
                    phaseloadreg_r = pll_register_01_nxt[3] ;
                    phasesel_r = pll_register_01_nxt[2:0] ;
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- Sequential block --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    lmmi_sm_cs <=  ST_LMMI_IDLE ;
                    /*AUTORESET*/
                    // Beginning of autoreset for uninitialized flops
                    lmmi_rdata_r <=  8'h0 ;
                    lmmi_ready_r <=  1'h0 ;
                    lmmi_rvalid_r <=  1'h0 ;
                    pll_lmmi_request <=  1'h0 ;
                    // End of automatics
                end
            else
                begin
                    case (lmmi_sm_cs)
                    ST_LMMI_WREQ : 
                        begin
                            lmmi_sm_cs <=  ST_LMMI_WREQ ;
                            if (usr_lmmi_offset[7]) 
                                begin
                                    lmmi_sm_cs <=  ST_LMMI_DONE ;
                                    lmmi_ready_r <=  1'b1 ;
                                    pll_lmmi_request <=  1'b0 ;
                                end
                            else
                                begin
                                    if (pll_lmmi_ready) 
                                        begin
                                            lmmi_sm_cs <=  ST_LMMI_DONE ;
                                            lmmi_ready_r <=  1'b1 ;
                                            pll_lmmi_request <=  1'b0 ;
                                        end
                                end
                        end// ST_LMMI_WREQ
                    ST_LMMI_RREQ : 
                        begin
                            lmmi_sm_cs <=  ST_LMMI_RREQ ;
                            if (usr_lmmi_offset[7]) 
                                begin
                                    lmmi_sm_cs <=  ST_LMMI_DONE ;
                                    lmmi_ready_r <=  1'b1 ;
                                    lmmi_rvalid_r <=  1'b1 ;
                                    lmmi_rdata_r <=  csr_rdat_nxt ;
                                    pll_lmmi_request <=  1'b0 ;
                                end
                            else
                                begin
                                    pll_lmmi_request <=  (pll_lmmi_request & (~pll_lmmi_ready)) ;
                                    lmmi_ready_r <=  ((pll_lmmi_request & pll_lmmi_ready) & (~lmmi_ready_r)) ;
                                    if (pll_lmmi_rdata_valid) 
                                        begin
                                            lmmi_sm_cs <=  ST_LMMI_DONE ;
                                            lmmi_rvalid_r <=  1'b1 ;
                                            lmmi_rdata_r <=  pll_lmmi_rdata ;
                                        end
                                end
                        end// ST_LMMI_RREQ
                    ST_LMMI_DONE : 
                        begin
                            lmmi_sm_cs <=  ST_LMMI_IDLE ;
                            lmmi_ready_r <=  1'b0 ;
                            lmmi_rvalid_r <=  1'b0 ;
                        end// ST_LMMI_RREQ
                    default : 
                        begin
                            // ST_LMMI_IDLE
                            lmmi_sm_cs <=  ST_LMMI_IDLE ;
                            lmmi_ready_r <=  1'b0 ;
                            lmmi_rvalid_r <=  1'b0 ;
                            pll_lmmi_request <=  1'b0 ;
                            if (usr_lmmi_request) 
                                begin
                                    pll_lmmi_request <=  (~usr_lmmi_offset[7]) ;
                                    if (usr_lmmi_wr_rdn) 
                                        begin
                                            lmmi_sm_cs <=  ST_LMMI_WREQ ;
                                        end
                                    else
                                        begin
                                            lmmi_sm_cs <=  ST_LMMI_RREQ ;
                                        end
                                end
                        end// ST_LMMI_IDLE
                    endcase 
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--

//--------------------------------------------------------------------------
//--- Module Instantiation ---
//--------------------------------------------------------------------------
//--pll_csr--
endmodule



// __RTL_MODULE__PLL_CSR__
//==========================================================================
// Module : lscc_apb2lmmi
//==========================================================================
module lpddr4_mc_ipgen_lscc_apb2lmmi #(parameter DATA_WIDTH = 32, 
        parameter ADDR_WIDTH = 16, 
        parameter REG_OUTPUT = 1) (
    //--begin_param--
    //----------------------------
    // Parameters
    //----------------------------
    // Data width
    // Address width
    // enable registered output
    //--end_param--
    //--begin_ports--
    //----------------------------
    // Global Signals (Clock and Reset)
    //----------------------------
    input clk_i,  // apb clock
    input rst_n_i,  // active low reset
    //----------------------------
    // APB Interface
    //----------------------------
    input apb_penable_i,  // apb enable
    input apb_psel_i,  // apb slave select
    input apb_pwrite_i,  // apb write 1, read 0
    input [(ADDR_WIDTH - 1):0] apb_paddr_i,  // apb address
    input [(DATA_WIDTH - 1):0] apb_pwdata_i,  // apb write data
    output reg apb_pready_o,  // apb ready
    output reg apb_pslverr_o,  // apb slave error
    output reg [(DATA_WIDTH - 1):0] apb_prdata_o,  // apb read data
    //----------------------------
    // LMMI-Extended Interface
    //----------------------------
    input lmmi_ready_i,  // slave is ready to start new transaction
    input lmmi_rdata_valid_i,  // read transaction is complete
    input lmmi_error_i,  // error indicator
    input [(DATA_WIDTH - 1):0] lmmi_rdata_i,  // read data
    output reg lmmi_request_o,  // start transaction
    output reg lmmi_wr_rdn_o,  // write 1, read 0
    output reg [(ADDR_WIDTH - 1):0] lmmi_offset_o,  // address/offset
    output reg [(DATA_WIDTH - 1):0] lmmi_wdata_o,  // write data
    output wire lmmi_resetn_o // reset to LMMI inteface
        ) ;
    //--end_ports--
    //--------------------------------------------------------------------------
    //--- Local Parameters/Defines ---
    //--------------------------------------------------------------------------
    localparam ST_BUS_IDLE = 4'b0001 ; 
    localparam ST_BUS_REQ = 4'b0010 ; // APB_SETUP
    localparam ST_BUS_DAT = 4'b0100 ; // APB_ACCESS
    localparam ST_BUS_WAIT = 4'b1000 ; 
    localparam SM_WIDTH = 4 ; 
    //--------------------------------------------------------------------------
    //--- Combinational Wire/Reg ---
    //--------------------------------------------------------------------------
    //--------------------------------------------------------------------------
    //--- Registers ---
    //--------------------------------------------------------------------------
    reg [(SM_WIDTH - 1):0] bus_sm_ns ; 
    reg [(SM_WIDTH - 1):0] bus_sm_cs ; 
    assign lmmi_resetn_o = rst_n_i ; 
    generate
        if (REG_OUTPUT) 
            begin : genblk1
                reg lmmi_request_nxt ; 
                reg lmmi_wr_rdn_nxt ; 
                reg [(ADDR_WIDTH - 1):0] lmmi_offset_nxt ; 
                reg [(DATA_WIDTH - 1):0] lmmi_wdata_nxt ; 
                reg apb_pready_nxt ; 
                reg apb_pslverr_nxt ; 
                reg [(DATA_WIDTH - 1):0] apb_prdata_nxt ; 
                //--------------------------------------------
                //-- Bus Statemachine --
                //--------------------------------------------
                always
                    @(*)
                    begin
                        bus_sm_ns = bus_sm_cs ;
                        case (bus_sm_cs)
                        ST_BUS_REQ : 
                            begin
                                if (lmmi_ready_i) 
                                    begin
                                        if (lmmi_wr_rdn_o) 
                                            begin
                                                bus_sm_ns = ST_BUS_WAIT ;
                                            end
                                        else
                                            begin
                                                if (lmmi_rdata_valid_i) 
                                                    bus_sm_ns = ST_BUS_WAIT ;
                                                else
                                                    bus_sm_ns = ST_BUS_DAT ;
                                            end
                                    end
                                else
                                    begin
                                        bus_sm_ns = ST_BUS_REQ ;
                                    end
                            end
                        ST_BUS_DAT : 
                            begin
                                if (lmmi_rdata_valid_i) 
                                    bus_sm_ns = ST_BUS_WAIT ;
                                else
                                    bus_sm_ns = ST_BUS_DAT ;
                            end
                        ST_BUS_WAIT : 
                            begin
                                bus_sm_ns = ST_BUS_IDLE ;
                            end
                        default : 
                            begin
                                if (apb_psel_i) 
                                    bus_sm_ns = ST_BUS_REQ ;
                                else
                                    bus_sm_ns = ST_BUS_IDLE ;
                            end
                        endcase 
                    end//--always @*--
                //--------------------------------------------
                //-- APB to LMMI conversion --
                //--------------------------------------------
                always
                    @(*)
                    begin
                        lmmi_request_nxt = lmmi_request_o ;
                        lmmi_wr_rdn_nxt = lmmi_wr_rdn_o ;
                        lmmi_offset_nxt = lmmi_offset_o ;
                        lmmi_wdata_nxt = lmmi_wdata_o ;
                        apb_pready_nxt = apb_pready_o ;
                        apb_pslverr_nxt = 1'b0 ;
                        apb_prdata_nxt = apb_prdata_o ;
                        case (bus_sm_cs)
                        ST_BUS_REQ : 
                            begin
                                if (lmmi_ready_i) 
                                    begin
                                        lmmi_request_nxt = 1'b0 ;
                                        lmmi_wr_rdn_nxt = 1'b0 ;
                                        if (lmmi_wr_rdn_o) 
                                            begin
                                                apb_pready_nxt = 1'b1 ;
                                            end
                                        else
                                            begin
                                                if (lmmi_rdata_valid_i) 
                                                    begin
                                                        apb_pready_nxt = 1'b1 ;
                                                        apb_prdata_nxt = lmmi_rdata_i ;
                                                        apb_pslverr_nxt = lmmi_error_i ;
                                                    end
                                            end
                                    end
                            end
                        ST_BUS_DAT : 
                            begin
                                if (lmmi_rdata_valid_i) 
                                    begin
                                        apb_pready_nxt = 1'b1 ;
                                        apb_prdata_nxt = lmmi_rdata_i ;
                                        apb_pslverr_nxt = lmmi_error_i ;
                                    end
                            end
                        ST_BUS_WAIT : 
                            begin
                                apb_pready_nxt = 1'b0 ;
                            end
                        default : 
                            begin
                                apb_pready_nxt = 1'b0 ;
                                if (apb_psel_i) 
                                    begin
                                        lmmi_request_nxt = 1'b1 ;
                                        lmmi_wr_rdn_nxt = apb_pwrite_i ;
                                        lmmi_offset_nxt = apb_paddr_i ;
                                        lmmi_wdata_nxt = apb_pwdata_i ;
                                    end
                                else
                                    begin
                                        lmmi_request_nxt = 1'b0 ;
                                        lmmi_wr_rdn_nxt = 1'b0 ;
                                    end
                            end
                        endcase 
                    end//--always @*--
                //--------------------------------------------
                //-- Sequential block --
                //--------------------------------------------
                always
                    @(posedge clk_i or 
                        negedge rst_n_i)
                    begin
                        if ((~rst_n_i)) 
                            begin
                                bus_sm_cs <=  ST_BUS_IDLE ;
                                /*AUTORESET*/
                                // Beginning of autoreset for uninitialized flops
                                apb_prdata_o <=  {DATA_WIDTH{1'b0}} ;
                                apb_pready_o <=  1'h0 ;
                                apb_pslverr_o <=  1'h0 ;
                                lmmi_offset_o <=  {ADDR_WIDTH{1'b0}} ;
                                lmmi_request_o <=  1'h0 ;
                                lmmi_wdata_o <=  {DATA_WIDTH{1'b0}} ;
                                lmmi_wr_rdn_o <=  1'h0 ;
                                // End of automatics
                            end
                        else
                            begin
                                bus_sm_cs <=  bus_sm_ns ;
                                lmmi_request_o <=  lmmi_request_nxt ;
                                lmmi_wr_rdn_o <=  lmmi_wr_rdn_nxt ;
                                lmmi_offset_o <=  lmmi_offset_nxt ;
                                lmmi_wdata_o <=  lmmi_wdata_nxt ;
                                apb_pready_o <=  apb_pready_nxt ;
                                apb_pslverr_o <=  apb_pslverr_nxt ;
                                apb_prdata_o <=  apb_prdata_nxt ;
                            end
                    end//--always @(posedge clk_i or negedge rst_n_i)--
            end
        else
            begin : genblk1
                // REG_OUTPUT == 0
                //--------------------------------------------
                //-- Bus Statemachine --
                //--------------------------------------------
                always
                    @(*)
                    begin
                        bus_sm_ns = bus_sm_cs ;
                        case (bus_sm_cs)
                        ST_BUS_IDLE : 
                            begin
                                if (apb_psel_i) 
                                    bus_sm_ns = ST_BUS_REQ ;
                                else
                                    bus_sm_ns = ST_BUS_IDLE ;
                            end
                        ST_BUS_REQ : 
                            begin
                                if (lmmi_ready_i) 
                                    if (((~apb_pwrite_i) && (~lmmi_rdata_valid_i))) 
                                        bus_sm_ns = ST_BUS_DAT ;
                                    else
                                        // Write access will go to IDLE when ready
                                        bus_sm_ns = ST_BUS_IDLE ;
                                else
                                    bus_sm_ns = ST_BUS_REQ ;
                            end
                        ST_BUS_DAT : 
                            begin
                                if ((apb_penable_i && ((~apb_pwrite_i) && lmmi_rdata_valid_i))) 
                                    bus_sm_ns = ST_BUS_IDLE ;
                                else
                                    bus_sm_ns = ST_BUS_DAT ;
                            end
                        default : 
                            begin
                                bus_sm_ns = ST_BUS_IDLE ;
                            end
                        endcase 
                    end//--always @*--
                //--------------------------------------------
                //-- LMMI request --
                //--------------------------------------------
                always
                    @(*)
                    begin
                        lmmi_request_o = (bus_sm_ns == ST_BUS_REQ) ;
                        lmmi_wr_rdn_o = apb_pwrite_i ;
                        lmmi_offset_o = apb_paddr_i ;
                        lmmi_wdata_o = apb_pwdata_i ;
                    end//--always @*--
                //--------------------------------------------
                //-- APB outputs --
                //--------------------------------------------
                always
                    @(*)
                    begin
                        apb_prdata_o = lmmi_rdata_i ;
                        apb_pslverr_o = (lmmi_rdata_valid_i && lmmi_error_i) ;
                        if (apb_pwrite_i) 
                            begin
                                apb_pready_o = lmmi_ready_i ;
                            end
                        else
                            begin
                                apb_pready_o = lmmi_rdata_valid_i ;
                            end
                    end//--always @*--
                //--------------------------------------------
                //-- Sequential block --
                //--------------------------------------------
                always
                    @(posedge clk_i or 
                        negedge rst_n_i)
                    begin
                        if ((~rst_n_i)) 
                            begin
                                bus_sm_cs <=  ST_BUS_IDLE ;
                            end
                        else
                            begin
                                bus_sm_cs <=  bus_sm_ns ;
                            end
                    end//--always @(posedge clk_i or negedge rst_n_i)--
            end
    endgenerate

//--------------------------------------------------------------------------
//--- Module Instantiation ---
//--------------------------------------------------------------------------
//--lscc_apb2lmmi--
endmodule



