//`include "mem_sync.v"
module lpddr4_mc_ipgen_clock_sync #(parameter CLK_CHANGE_EN = 1, 
        parameter GEARING = 2, 
        parameter POWER_ON_CLK_CBT = 1) (
    // -----------------------------------------------------------------------------
    // Module Parameters
    // -----------------------------------------------------------------------------
    // -----------------------------------------------------------------------------
    // Input/Output Ports
    // -----------------------------------------------------------------------------
    input rst_i, 
    input pll_rst_n_i, 
    input sync_clk_i, 
    input sync_rst_n_i, 
    input ddr_clk_sel_i, 
    input dll_update_en_i, 
    input dllcode_upd_n_i, 
    input clk_update_i, 
    input eclk_i, 
    input pll_lock_i, 
    input ddr_ck_en_i, 
    output [7:0] dcnt_o, 
    output ready_o, 
    output sync_pause_o, 
    output ddr_ck_en_o, 
    output sclk_o, 
    output eclk_o, 
    output [8:0] code_o, 
    output rst_o, 
    //output             sync_rst_o,    // rst_i that is syncronized to sync_clk
    output op_clk_en_o, 
    output sync_clk_update_o, 
    output sync_clk_sel_o, 
    input sync_clk_update_done_i) ;
    localparam GEARING_STR = ((GEARING == 4) ? "4" : "2") ; 
    wire stop_w ; 
    wire lock_w ; 
    wire eclkout_w ; 
    wire dll_rst_w ; 
    wire uddcntln_w ; 
    wire freeze_w ; 
    wire mem_sync_rst_w ; 
    assign rst_o = mem_sync_rst_w ; 
    assign eclk_o = eclkout_w ; 
    // -----------------------------------------------------------------------------
    // -----------------------------------------------------------------------------
    ECLKDIV #(.ECLK_DIV(GEARING_STR),
            .GSR("DISABLED")) u0_ECLKDIV (// There is reset issue when ENABLED and SW synth strategy "Force GSR" 
            // inputs
            .DIVRST(mem_sync_rst_w), 
                //  .DIVRST          (pll_rst_n_i),
            .ECLKIN(eclkout_w), 
                .SLIP(1'b0), 
                // outputs
            .DIVOUT(sclk_o)) ; 
    ECLKSYNC #(.STOP_EN("ENABLE")) u0_ECLKSYNC (.ECLKIN(eclk_i), 
                .ECLKOUT(eclkout_w), 
                .STOP(stop_w)) ; 
    lpddr4_mc_ipgen_mem_sync #(.POWER_ON_CLK_CBT(POWER_ON_CLK_CBT)) u1_mem_sync (.rst_i(rst_i), 
                .sclk_i(sclk_o), 
                .sync_clk_i(sync_clk_i), 
                .sync_rst_n_i(sync_rst_n_i), 
                .ddr_clk_sel_i(ddr_clk_sel_i), 
                .ddr_ck_en_i(ddr_ck_en_i), 
                .dll_update_en_i(dll_update_en_i), 
