                .sync_clk_sel_o(sync_clk_sel_o), 
                .sync_clk_update_done_i(sync_clk_update_done_i)) ; 
    wire [8:0] dcnt_w ; 
    DDRDLL #(.GSR("DISABLED"),
            .ENA_ROUNDOFF("ENABLED"),
            .FORCE_MAX_DELAY("CODE_OR_LOCK_FROM_DLL_LOOP")) u0_DDRDLL (// There is reset issue when ENABLED and SW synth strategy "Force GSR" 
            // inputs
            .FREEZE(freeze_w), 
                .CLKIN(eclkout_w), 
                .RST(dll_rst_w), 
                .UDDCNTL_N(uddcntln_w), 
                // outputs
            .CODE(code_o), 
                .LOCK(lock_w), 
                .DCNTL(dcnt_w)) ; 
    assign dcnt_o = dcnt_w[7:0] ; 

// 4Nu
endmodule



