    reg [1:0] rank_sel_r2 ; 
    reg [1:0] rank_sel_r3 ; 
    always
        @(posedge sclk_w or 
            posedge rst_i)
        begin
            if (rst_i) 
            //end 
                begin
                    rank0_cs_sel <=  1'b0 ;
                    rank1_cs_sel <=  1'b0 ;
                    rank0update <=  1'b0 ;
                    rank0update_r <=  1'b0 ;
                    rank1update <=  1'b0 ;
                    rank1update_r <=  1'b0 ;
                    rank_sel_r <=  2'b0 ;
                    rank_sel_r2 <=  2'b0 ;
                    rank_sel_r3 <=  2'b0 ;
                end
            else
                begin
