                    //      rank0update <= 1'b0;
                    //    end   
                    //    else begin
                    //      rank0update <= rank0update;
                    //      rank1update <= rank1update;
                    //    end 
                    //  end
                    //  else begin
                    rank_sel_r <=  rank_sel_i ;
                    rank_sel_r2 <=  rank_sel_r ;
                    if ((rank_sel_i[0] && rank_sel_i[1])) 
                        begin
                            rank0update <=  1'b1 ;
                            rank1update <=  1'b1 ;
                        end
                    else
                        if (rank_sel_i[0]) 
                            begin
                                rank0update <=  1'b1 ;
                                rank1update <=  1'b0 ;
                            end
                        else
                            begin
                                rank0update <=  1'b0 ;
                                rank1update <=  1'b1 ;
                            end
                end
        end
