            "0b0001" : 
                binstr2int4 = 1 ;
            "0b0010" : 
                binstr2int4 = 2 ;
            "0b0011" : 
                binstr2int4 = 3 ;
            "0b0100" : 
                binstr2int4 = 4 ;
            "0b0101" : 
                binstr2int4 = 5 ;
