    //localparam [3:0] OP_IPP_CTRL_INT  = binstr2int4(IPP_CTRL);
    //localparam [3:0] OP_IPI_CMP_INT   = binstr2int4(IPI_CMP);
    //localparam [6:0] CBT_DIVOP_INT    = 7;  //decstr2int(DIVOP_ACTUAL_STR);
    localparam [6:0] CBT_DIVOS_INT = ((CLK_FREQ == 300) ? 29 : ((CLK_FREQ == 350) ? 27 : 31)) ; //decstr2int(DIVOS_ACTUAL_STR);
    //localparam [6:0] CBT_DELA_INT     = 7;  //decstr2int(DELA);
    localparam [6:0] CBT_DELB_INT = ((CLK_FREQ == 300) ? 29 : ((CLK_FREQ == 350) ? 27 : 31)) ; //decstr2int(DELB);
    //localparam [3:0] CBT_IPP_CTRL_INT = 4;  //binstr2int4(IPP_CTRL);
    //localparam [3:0] CBT_IPI_CMP_INT  = 4;  //binstr2int4(IPI_CMP);
    reg lmmi_request_o ; 
    reg [6:0] lmmi_offset_o ; 
    reg [7:0] lmmi_wdata_o ; 
    assign lmmi_request = lmmi_request_o ; 
    assign lmmi_offset = lmmi_offset_o ; 
    assign lmmi_wdata = lmmi_wdata_o ; 
    always
        @(*)
        begin
            lmmi_offset_o = addr_count[7:1] ;
            if ((addr_count[7:1] == 0)) 
                //shadow update
                lmmi_wdata_o = 1 ;
            else
                if ((addr_count <= 107)) 
                    // write the read data// read data is 1 cycle delay
                    case (lmmi_offset_o)
                    6'h25 : 
                        //      6'h1A   : lmmi_wdata_o = sync_clk_sel ? {CBT_IPI_CMP_INT[2:0],lmmi_rdata[4:0]} : {OP_IPI_CMP_INT[2:0],lmmi_rdata[4:0]};
                        //      6'h1B   : lmmi_wdata_o = sync_clk_sel ? {lmmi_rdata[7:5],CBT_IPP_CTRL_INT,CBT_IPI_CMP_INT[3]} : {lmmi_rdata[7:5],OP_IPP_CTRL_INT,OP_IPI_CMP_INT[3]};
                        //      6'h24   : lmmi_wdata_o = sync_clk_sel ? {CBT_DELA_INT[4:0],lmmi_rdata[2:0]} : {OP_DELA_INT[4:0],lmmi_rdata[2:0]};
                        //      6'h25   : lmmi_wdata_o = sync_clk_sel ? {CBT_DELB_INT[5:0],CBT_DELA_INT[6:5]} : {OP_DELB_INT[5:0],OP_DELA_INT[6:5]};
                        lmmi_wdata_o = (sync_clk_sel ? {CBT_DELB_INT[5:0],
                                lmmi_rdata[1:0]} : {OP_DELB_INT[5:0],
                                lmmi_rdata[1:0]}) ;
                    6'h26 : 
                        lmmi_wdata_o = (sync_clk_sel ? {lmmi_rdata[7:1],
                                CBT_DELB_INT[6]} : {lmmi_rdata[7:1],
                                OP_DELB_INT[6]}) ;
                    6'h2A : 
                        //      6'h29   : lmmi_wdata_o = sync_clk_sel ? {CBT_DIVOP_INT[2:0],lmmi_rdata[4:0]} : {OP_DIVOP_INT[2:0],lmmi_rdata[4:0]};
                        //      6'h2A   : lmmi_wdata_o = sync_clk_sel ? {CBT_DIVOS_INT[3:0],CBT_DIVOP_INT[6:3]} : {OP_DIVOS_INT[3:0],OP_DIVOP_INT[6:3]};
                        lmmi_wdata_o = (sync_clk_sel ? {CBT_DIVOS_INT[3:0],
                                lmmi_rdata[3:0]} : {OP_DIVOS_INT[3:0],
                                lmmi_rdata[3:0]}) ;
                    6'h2B : 
                        lmmi_wdata_o = (sync_clk_sel ? {lmmi_rdata[7:3],
                                CBT_DIVOS_INT[6:4]} : {lmmi_rdata[7:3],
                                OP_DIVOS_INT[6:4]}) ;
                    6'h00 : 
                        lmmi_wdata_o = 8'h01 ;
                    default : 
                        lmmi_wdata_o = lmmi_rdata ;
                    endcase 
                else
                    lmmi_wdata_o = 0 ;
        end
    always
        @(posedge sync_clk_i or 
            negedge sync_rst_n_i)
        begin
            if ((!sync_rst_n_i)) 
                begin
                    addr_count <=  9'h02 ;
                end
            else
                begin
                    if ((lmmi_request_o && lmmi_ready)) 
                        if ((addr_count <= 107)) 
                            addr_count <=  (addr_count + 9'h01) ;
                        else
                            addr_count <=  9'h01 ;
                    else
                        // shadow update with write
                        addr_count <=  2 ;
                end
        end
    reg op_clk_en_r ; 
    always
        @(posedge sync_clk_i or 
            negedge sync_rst_n_i)
        begin
            if ((!sync_rst_n_i)) 
                begin
                    lmmi_request_o <=  1'b0 ;
                    sync_upd_done_r <=  1'b0 ;
                    pll_rst_n_r <=  1'b0 ;
                    op_clk_en_r <=  1'b1 ;
                end
            else
                begin
                    op_clk_en_r <=  op_clk_en_w ;
                    if (sync_clk_update) 
                        lmmi_request_o <=  1'b1 ;
                    else
                        if ((lmmi_ready && (lmmi_offset_o == 6'h00))) 
                            // The last PLL address to write
                            lmmi_request_o <=  1'b0 ;
                    if (sync_clk_update) 
                        sync_upd_done_r <=  1'b0 ;
                    else
                        if (((lmmi_ready && lmmi_request_o) && (lmmi_offset_o == 6'h00))) 
                            sync_upd_done_r <=  1'b1 ;
                        else
                            if ((((!lmmi_request_o) && op_clk_en_r) && (!op_clk_en_w))) 
                                // clock is disabled without clock frequency change 
                                sync_upd_done_r <=  1'b1 ;
                end
        end

// 4Nu
endmodule



//---------------------------------------------------------------------
// Module: lscc_cdc_hs_bus
//---------------------------------------------------------------------
// Copyright (c) 2024 by Lattice Semiconductor Corporation
//---------------------------------------------------------------------
//
//  Params:
//  + WIDTH         - Data bus width. Allowable range is 1 to 1024.
//  + SYNC_STAGE    - Number of register stages used in internal
//                    synchronizers
//  + UNRELATED_RST - Enable if src_rst_n and dest_rst_n are unrelated,
//                    disable if global rst is tied to both src_rst_n
//                    and dest_rst_n
//  + SRC_RST_MODE  - Source reset mode
//                    (SYNC - Synchronous, ASYNC - Asynchronous)
//  + DEST_RST_MODE - Destination reset mode
//  + RST_INIT      - Default reset value
//                    (SYNC - Synchronous, ASYNC - Asynchronous)
//  + SRC_REQ_EN    - Enable or disable the use of the src_req
//                    ports. When disabled, a comparator will be
//                    instantiated to determine if the data is
//                    new.
//  + REGMODE       - If enabled, there will be additional flop 
//                    at the output before sending the output data
//  + SIM_ASSERT_EN - Assertion enable
//
//  Ports:
//  + src_rst_n  - Source reset (active low)
//  + src_clk    - Source clock
//  + src_req    - Source input to request for new data to be transferred
//                 to destination side
//  + src_ready  - Source output to indicate that the input data has been
//                 transferred to destination; a version of dest_valid
//                 and dest_ack combined that is synchronized over to
//                 source
//  + in_data    - Input data in src_clk domain
//
//  + dest_rst_n - Destination reset (active low)
//  + dest_clk   - Destination clock
//  + dest_valid - Destination output to indicate that the output data
//                 is valid to be sampled; it is a pulsed signal
//  + dest_ack   - Destination input to indicate that the output data
//                 has been successfully sampled externally and
//                 acknowledge that the next data can be sent from src
//  + out_data   - Output data after sync in dest_clk domain
//
//  Operation:
//  The handshake can be used in 3 modes:
//  1. Trigger mode
//     - Full operational usage of this handshake block in which user
//       has a src_req signal that triggers when to transfer new data
//       over to destination side (make use of all ports).
//  2. Periodic mode
//     - src_ready can be wired to src_req externally, and dest_valid
//       can be wired to dest_ack externally. In this mode, data will
//       be transferred to destination end periodically regardless of
//       valid data change or not at the rate following the latency
//       mentioned below.
//  3. Data Change mode
//     - If user would like the handshake to trigger based on input
//       data change instead, then the src_req may be tied to '0' and
//       use the SRC_REQ_EN param instead. This mode is similar to
//       trigger mode other than the absence of src_req.
//
//  Limitations:
//  1. src_req must not be asserted all the time, else the src_ready
//     would stay deasserted, and never gets into ready state
//  2. dest_ack must be a FF output. It should not come from
//     combinational logic to prevent glitching that could propagate
//     into an invalid src_ready.
//  3. The handshake takes
//        (SYNC_STAGE+2) src_clk + (SYNC_STAGE+2) dest_clk
//     before the next in_data can be sent.
//     And it takes
//        1 src_clk + (SYNC_STAGE+1) dest_clk
//     before the out_data reflects in_data value along with dest_valid.
//     User should not change the in_data faster than the latency above.
//
//  Notes:
//  1. Input Request Generation.
//     When generating the input request (req_pulse), it has to be glitch 
//     free especially when reset skew happens. To do this, src_ready is
//     used as the mask to prevent unintentional glitch from generating
//     a request. How is this happenning? The arrival of src_rst_n to 
//     src_req_r vs the arrival time of src_rst_n on the external FF 
//     that drives src_req may cause a glitch that could be captured 
//     by dest_clk, and transferred to the dest_clk domain as a valid 
//     request. The src_ready signal will be able to mask this, provided
//     these logic are all implemented in a single LUT.
//     This is how src_ready can prevent the glitch from progating as 
//     request on the dest_clk domain:
//      i. src_rst_n asserts a src_clk or two after src_req assertion and
//         src_req_r FF resets first. Now, src_ready would have deasserted 
//         one clock after src_req assertion, hence becoming a mask and 
//         prevent the glitch that occurs from being seen on the output. 
//         Also, src_req is also reset to '0' by src_rst_n.
//      ii. src_rst_n asserts at the same time as src_req assertion. It 
//          may assert after src_req assertion and the samething would happen.
//          Now, src_ready is asserted and would not be able to act as the 
//          mask. hence allowing the glitch to go through. However, there's
//          the dest_sync_rst_n, which is the double sync copy of src_rst_n
//          that will be transferred to the dest_clk domain, and should be
//          able to block the glitch from actually being detected as a 
//          request on the dest_clk domain. The race condition here will be
//          explained below. 
//  2. Output Data Valid Generation
//     There is a reset crossing case to be considered here:
//      i. If the dest_clk domain toggle signals are currently '1' and the
//         src_clk domain toggle flop is reset to '0' (src_rst_n asserts
//         while dest_rst_n doesn't), it could propagate to be a false
//         dest_valid pulse.
//         This is also resolved with dest_sync_rst_n intercepting the
//         toggle in the dest_clk domain.
//     Also, the toggle FF output may be metastable upon async reset 
//     deassertion (close to src_clk edge) because the FF D is always 
//     NOT of Q (D != Q). Hence we use the reset sync deassertion 
//     version of reset for this FF when src_rst_n is asynchronous.
//---------------------------------------------------------------------
(* LATTICE_IP_MODULE=1 *) module lpddr4_mc_ipgen_lscc_cdc_hs_bus #(parameter WIDTH = 32, 
        parameter SYNC_STAGE = 2, 
        parameter UNRELATED_RST = 1'b1, 
        parameter SRC_RST_MODE = "ASYNC", 
        parameter DEST_RST_MODE = "ASYNC", 
        parameter [(WIDTH - 1):0] RST_INIT = {WIDTH{1'b0}}, 
        parameter SRC_REQ_EN = 1'b1, 
        parameter REGMODE = 1'b0, 
        parameter SIM_ASSERT_EN = 1'b1) (
    input logic src_rst_n, 
    input logic src_clk, 
    input logic src_req, 
    output logic src_ready, 
    input logic [(WIDTH - 1):0] in_data, 
    input logic dest_rst_n, 
    input logic dest_clk, 
    output logic dest_valid, 
    input logic dest_ack, 
    output logic [(WIDTH - 1):0] out_data) ;
    //-------------------------------------------------------------------
    // Reset Synchronizers
    //-------------------------------------------------------------------
    logic src_sync_rst_n ; 
    logic src_rsd_rst_n ; 
    logic src_slow_rsd_rst_n ; 
    logic dest_sync_rst_n ; 
    logic dest_slow_rsd_rst_n ; 
    lpddr4_mc_ipgen_hs_reset_sync #(.SYNC_STAGE(SYNC_STAGE),
            .UNRELATED_RST(UNRELATED_RST),
            .SRC_RST_MODE(SRC_RST_MODE),
            .DEST_RST_MODE(DEST_RST_MODE),
            .USE_FAST_SYNC(1'b1)) u_lscc_sync_src_rst (.src_rst_n(src_rst_n), 
                .src_clk(src_clk), 
                .dest_rst_n(dest_rst_n), 
                .dest_clk(dest_clk), 
                .src_rsd_rst_n(src_rsd_rst_n), 
                .src_slow_rsd_rst_n(src_slow_rsd_rst_n), 
                .dest_sync_rst_n(dest_sync_rst_n)) ; 
    lpddr4_mc_ipgen_hs_reset_sync #(.SYNC_STAGE(SYNC_STAGE),
            .UNRELATED_RST(UNRELATED_RST),
            .SRC_RST_MODE(DEST_RST_MODE),
            .DEST_RST_MODE(SRC_RST_MODE),
            .USE_FAST_SYNC(1'b0)) u_lscc_sync_dest_rst (.src_rst_n(dest_rst_n), 
                .src_clk(dest_clk), 
                .dest_rst_n(src_rst_n), 
                .dest_clk(src_clk), 
                .src_rsd_rst_n(), 
                .src_slow_rsd_rst_n(dest_slow_rsd_rst_n), 
                .dest_sync_rst_n(src_sync_rst_n)) ; 
    //-------------------------------------------------------------------
    // Data Comparator
    //-------------------------------------------------------------------
    logic [(WIDTH - 1):0] in_data_dly ; 
    logic src_req_lcl ; 
    generate
        if (SRC_REQ_EN) 
            begin : genblk1
                assign src_req_lcl = src_req ; 
                assign in_data_dly = {WIDTH{1'b0}} ; 
            end
        else
            begin : genblk1
                // When src_req is disabled, we will need a comparator to detect
                // a change in data, and generate the equivalent of src_req. Here
                // we have a pipeline stage to generate a registered copy of data
                // for the comparator, where the output of the comparator is a
                // single cycle pulse.
                if ((SRC_RST_MODE == "ASYNC")) 
                    begin : genblk1
                        always_ff
                            @(posedge src_clk or 
                                negedge src_rst_n)
                            begin
                                if ((!src_rst_n)) 
                                    begin
                                        in_data_dly <=  {WIDTH{1'b0}} ;
                                    end
                                else
                                    begin
                                        in_data_dly <=  in_data ;
                                    end
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge src_clk)
                            begin
                                if ((!src_rst_n)) 
                                    begin
                                        in_data_dly <=  {WIDTH{1'b0}} ;
                                    end
                                else
                                    begin
                                        in_data_dly <=  in_data ;
                                    end
                            end
                    end
                assign src_req_lcl = (|(in_data ^ in_data_dly)) ; 
            end
    endgenerate
    // Specific consideration is taken for req_pulse. See notes above.
    (* syn_preserve=1 *) logic src_req_r ; 
    (* syn_keep=1 *) logic req_pulse ; 
    assign req_pulse = ((src_req_lcl & (~src_req_r)) & src_ready) ; 
    generate
        if ((SRC_RST_MODE == "ASYNC")) 
            begin : genblk2
                always_ff
                    @(posedge src_clk or 
                        negedge src_rst_n)
                    begin
                        if ((!src_rst_n)) 
                            src_req_r <=  1'b0 ;
                        else
                            src_req_r <=  src_req_lcl ;
                    end
            end
        else
            begin : genblk2
                always_ff
                    @(posedge src_clk)
                    begin
                        if ((!src_rst_n)) 
                            src_req_r <=  1'b0 ;
                        else
                            src_req_r <=  src_req_lcl ;
                    end
            end
    endgenerate
    //-------------------------------------------------------------------
    // Input Data Bus Register
    //-------------------------------------------------------------------
    (* syn_preserve=1 *) logic [(WIDTH - 1):0] in_data_r = RST_INIT ; 
    logic [(WIDTH - 1):0] in_data_nxt ; 
    // req_pulse becomes the EN pin of the in_data_r FF
    assign in_data_nxt = (req_pulse ? in_data : in_data_r) ; 
    // When both src_rst_n and dest_rst_n are unrelated, we do not
    // want to reset the in_data_r register, to prevent corrupted
    // data from being registered on the destination side. 
    logic src_rst_data_path_n ; 
    assign src_rst_data_path_n = (UNRELATED_RST ? 1'b1 : src_rst_n) ; 
    generate
        if ((SRC_RST_MODE == "ASYNC")) 
            begin : genblk3
                always
                    @(posedge src_clk or 
                        negedge src_rst_data_path_n)
                    begin
                        if ((!src_rst_data_path_n)) 
                            in_data_r <=  RST_INIT ;
                        else
                            in_data_r <=  in_data_nxt ;
                    end
            end
        else
            begin : genblk3
                always
                    @(posedge src_clk)
                    begin
                        if ((!src_rst_data_path_n)) 
                            in_data_r <=  RST_INIT ;
                        else
                            in_data_r <=  in_data_nxt ;
                    end
            end
    endgenerate
    // ------------ SRC CLK DOMAIN ------------
    // Toggle generator to convert pulse to level signal
    logic req_toggle ; 
    logic req_toggle_nxt ; 
    // req_pulse becomes the EN pin of the req_toggle FF
    // There are two sections where the src_sync_rst_n would 
    // be used as the qualifier. When src_sync_rst_n asserts,
    // we want to do two things:
    // 1. EN the re_toggle flop: req_pulse & ~src_sync_rst_n
    // 2. Drive 1'b0 to D input: ~req_toggle & src_sync_rst_n
    // The reason for doing this is to ensure that when reset 
    // happens on the destination clock domain, we want to ensure
    // that req_toggle gets cleared too, to match the state of
    // valid toggle. Therefore, ~src_sync_rst_n is used to drive
    // the EN input of the flop. Also, src_sync_rst_n is used as
    // D input to clear it to 1'b0.
    assign req_toggle_nxt = ((req_pulse | (~src_sync_rst_n)) ? ((~req_toggle) & src_sync_rst_n) : req_toggle) ; 
    generate
        if (((SRC_RST_MODE == "ASYNC") || UNRELATED_RST)) 
            begin : genblk4
                // The req_toggle register is reset using the RSD copy of
                // src_rst_n. In the event that src_rst_n is synchronous, 
                // we will still treat this as asynchronous reset because
                // this register needs to be reset the same time as the 
                // the other registers in src_rst_n domain. 
                // Generation of src_rsd_rst_n
                //             ___
                //            |   |
                //            |   | -----> src_rsd_rst_n
                //            |   |
                //            |___|
                //              ^
                //              |
                // src_rst_n ---
                // Now, if src_rst_n is synchronous, src_rsd_rst_n will
                // assert at the same time as src_rst_n and RE of src_clk
                // The assertion edge of src_rsd_rst_n will only be seen
                // by reg_toggle one src_clk cycle, which shouldn't be the
                // case. Hence, req_toggle needs to be reset asynchronously.
                // We need req_toggle to be reset by src_rsd_rst_n because
                // we want it to stay reset until the reset has propagated
                // through the reset chain.
                always_ff
                    @(posedge src_clk or 
                        negedge src_rsd_rst_n)
                    begin
                        if ((!src_rsd_rst_n)) 
                            req_toggle <=  1'b0 ;
                        else
                            req_toggle <=  req_toggle_nxt ;
                    end
            end
        else
            begin : genblk4
                always_ff
                    @(posedge src_clk)
                    begin
                        if ((!src_rst_n)) 
                            req_toggle <=  1'b0 ;
                        else
                            req_toggle <=  req_toggle_nxt ;
                    end
            end
    endgenerate
    // ------------ DEST CLK DOMAIN ------------
    logic valid_toggle ; 
    logic valid_toggle_masked ; 
    logic valid_toggle_r_masked ; 
    logic valid_toggle_r ; 
    logic valid_pulse ; 
    // Toggle signal synchronized to dest_clk
    lpddr4_mc_ipgen_lscc_sync #(.SYNC_STAGE(SYNC_STAGE),
            .DEST_RST_MODE(DEST_RST_MODE),
            .RST_INIT(1'b0),
            .REGMODE(1'b0)) u_lscc_sync_req (.in_data(req_toggle), 
                .dest_rst_n(dest_rst_n), 
                .dest_clk(dest_clk), 
                .out_data(valid_toggle)) ; 
    // valid toggle will be masked by two signals:
    // 1. Synchronized version of src_rst. This is to ensure that invalid src_req
    //    does not propagate downstream into an incorrect dest_valid.
    // 2. Reset deassertion synchronized copy of dest_rst_n, where the deassertion
    //    edge is delayed until the reset has propagated through the reset sync 
    //    chain. This is to prevent dest_valid from asserting from a short dest_rst_n,
    //    which doesn't make it on time to clear the incoming req_toggle, as the 
    //    req_toggle register gets reset after dest_rst_n gets sync over to src_clk
    //    domain.
    assign valid_toggle_masked = ((dest_sync_rst_n & dest_slow_rsd_rst_n) ? valid_toggle : 1'b0) ; 
    assign valid_toggle_r_masked = ((dest_sync_rst_n & dest_slow_rsd_rst_n) ? valid_toggle_r : 1'b0) ; 
    // Generate a valid pulse based on valid_toggle change
    assign valid_pulse = (valid_toggle_masked ^ valid_toggle_r_masked) ; 
    generate
        if ((DEST_RST_MODE == "ASYNC")) 
            begin : genblk5
                always_ff
                    @(posedge dest_clk or 
                        negedge dest_rst_n)
                    begin
                        if ((!dest_rst_n)) 
                            valid_toggle_r <=  1'b0 ;
                        else
                            valid_toggle_r <=  valid_toggle_masked ;
                    end
            end
        else
            begin : genblk5
                always_ff
                    @(posedge dest_clk)
                    begin
                        if ((!dest_rst_n)) 
                            valid_toggle_r <=  1'b0 ;
                        else
                            valid_toggle_r <=  valid_toggle_masked ;
                    end
            end
    endgenerate
    //-------------------------------------------------------------------
    // Output Data Valid Logic
    //-------------------------------------------------------------------
    logic data_valid_nxt ; 
    (* syn_preserve=1 *) logic data_valid ; 
    // data_valid will assert one clock cycle after valid_pulse.
    // It will stay asserted as long as dest_ack is not asserted.
    // Once dest_ack asserts, data_valid will deassert. The reason
    // being that if dest_ack is not asserted, this means the 
    // destination side logic hasn't been able to respond to the
    // data_valid yet, hence the need for it to stay asserted.
    assign data_valid_nxt = (valid_pulse ? valid_pulse : (data_valid & (~dest_ack))) ; 
    generate
        if ((DEST_RST_MODE == "ASYNC")) 
            begin : genblk6
                always_ff
                    @(posedge dest_clk or 
                        negedge dest_rst_n)
                    begin
                        if ((!dest_rst_n)) 
                            data_valid <=  1'b0 ;
                        else
                            data_valid <=  data_valid_nxt ;
                    end
            end
        else
            begin : genblk6
                always_ff
                    @(posedge dest_clk)
                    begin
                        if ((!dest_rst_n)) 
                            data_valid <=  1'b0 ;
                        else
                            data_valid <=  data_valid_nxt ;
                    end
            end
    endgenerate
    // Connect to output port
    generate
        if (REGMODE) 
            begin : genblk7
                if ((DEST_RST_MODE == "ASYNC")) 
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk or 
                                negedge dest_rst_n)
                            begin
                                if ((!dest_rst_n)) 
                                    dest_valid <=  1'b0 ;
                                else
                                    dest_valid <=  data_valid ;
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk)
                            begin
                                if ((!dest_rst_n)) 
                                    dest_valid <=  1'b0 ;
                                else
                                    dest_valid <=  data_valid ;
                            end
                    end
            end
        else
            begin: genblk7
                assign dest_valid = data_valid ; 
            end
    endgenerate
    //-------------------------------------------------------------------
    // Output Data Bus Register
    //-------------------------------------------------------------------
    (* syn_preserve=1, CDC_Register=1 *) logic [(WIDTH - 1):0] out_data_r ; 
    logic [(WIDTH - 1):0] out_data_nxt ; 
    // valid_pulse becomes the EN pin of the out_data_r FF
    assign out_data_nxt = (valid_pulse ? in_data_r : out_data_r) ; 
    generate
        if ((DEST_RST_MODE == "ASYNC")) 
            begin : genblk8
                always_ff
                    @(posedge dest_clk or 
                        negedge dest_rst_n)
                    begin
                        if ((!dest_rst_n)) 
                            out_data_r <=  RST_INIT ;
                        else
                            out_data_r <=  out_data_nxt ;
                    end
            end
        else
            begin : genblk8
                always_ff
                    @(posedge dest_clk)
                    begin
                        if ((!dest_rst_n)) 
                            out_data_r <=  RST_INIT ;
                        else
                            out_data_r <=  out_data_nxt ;
                    end
            end
    endgenerate
    // Connect to output port
    generate
        if (REGMODE) 
            begin : genblk9
                if ((DEST_RST_MODE == "ASYNC")) 
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk or 
                                negedge dest_rst_n)
                            begin
                                if ((!dest_rst_n)) 
                                    out_data <=  RST_INIT ;
                                else
                                    out_data <=  out_data_r ;
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk)
                            begin
                                if ((!dest_rst_n)) 
                                    out_data <=  RST_INIT ;
                                else
                                    out_data <=  out_data_r ;
                            end
                    end
            end
        else
            begin: genblk9
                assign out_data = out_data_r ; 
            end
    endgenerate
    //-------------------------------------------------------------------
    // Input Ready Out Generation
    //-------------------------------------------------------------------
    // There is also a reset crossing case to be considered here:
    // 1. dest_rst_n is asserted (dest_rst_n asserts while src_rst_n
    //    doesn't) shortly after req_toggle just toggled to '0' as a new
    //    request coming in, this could prematurely trigger an invalid
    //    src_ready.
    //    This is resolved with src_sync_rst_n intercepting the src_ready
    //    in the src_clk domain.
    //-------------------------------------------------------------------
    // ------------ DEST CLK DOMAIN ------------
    logic valid_toggle_ack ; 
    logic valid_toggle_ack_nxt ; 
    // dest_ack becomes the EN pin of the valid_toggle_ack FF,
    // dest_ack is used to qualify the valid_toggle signal for
    // src_ready generation
    assign valid_toggle_ack_nxt = ((dest_ack || (!dest_sync_rst_n)) ? valid_toggle_r_masked : valid_toggle_ack) ; 
    generate
        if ((DEST_RST_MODE == "ASYNC")) 
            begin : genblk10
                always_ff
                    @(posedge dest_clk or 
                        negedge dest_rst_n)
                    begin
                        if ((!dest_rst_n)) 
                            valid_toggle_ack <=  1'b0 ;
                        else
                            valid_toggle_ack <=  valid_toggle_ack_nxt ;
                    end
            end
        else
            begin : genblk10
                always_ff
                    @(posedge dest_clk)
                    begin
                        if ((!dest_rst_n)) 
                            valid_toggle_ack <=  1'b0 ;
                        else
                            valid_toggle_ack <=  valid_toggle_ack_nxt ;
                    end
            end
    endgenerate
    // ------------ SRC CLK DOMAIN ------------
    logic ready_toggle ; 
    logic ready_nxt ; 
    // Toggle signal synchronized to src_clk
    lpddr4_mc_ipgen_lscc_sync #(.SYNC_STAGE(SYNC_STAGE),
            .DEST_RST_MODE(SRC_RST_MODE),
            .RST_INIT(1'b0),
            .REGMODE(1'b0)) u_lscc_sync_rdy (.in_data(valid_toggle_ack), 
                .dest_rst_n(src_rst_n), 
                .dest_clk(src_clk), 
                .out_data(ready_toggle)) ; 
    // Comparator to check the following before asserting src_ready
    // 1. src toggle = dest toggle: This means that the request has
    //                              safely transferred to destination.
    // 2. src_req is not asserted: This means that the previous transfer
    //                             is done.
    // 3. src reset propagated through the chain: This means that the 
    //                                            dest_sync_rst_n used 
    //                                            to gate the valid_toggle
    //                                            has been released and 
    //                                            new transfer can proceed
    // 4. sync copy of dest reset not asserted: Deassert ready when destination
    //                                          domain is in reset
    assign ready_nxt = ((((ready_toggle == req_toggle) & (~src_req_lcl)) & src_slow_rsd_rst_n) & src_sync_rst_n) ; 
    generate
        if ((SRC_RST_MODE == "ASYNC")) 
            begin : genblk11
                always_ff
                    @(posedge src_clk or 
                        negedge src_rst_n)
                    begin
                        if ((!src_rst_n)) 
                            src_ready <=  1'b0 ;
                        else
                            src_ready <=  ready_nxt ;
                    end
            end
        else
            begin : genblk11
                always_ff
                    @(posedge src_clk)
                    begin
                        if ((!src_rst_n)) 
                            src_ready <=  1'b0 ;
                        else
                            src_ready <=  ready_nxt ;
                    end
            end
    endgenerate
endmodule



//---------------------------------------------------------------------
// Module: hs_reset_sync (submodule)
//---------------------------------------------------------------------
// Copyright (c) 2024 by Lattice Semiconductor Corporation
//---------------------------------------------------------------------
//
//  Purpose:
//  Synchronize src_rst_n from src_clk domain into dest_clk domain
//  generating a reset that is separate from the dest_rst_n. Created
//  purely for the handshake module use case.
//  It models a simplified pulse sync to ensure a short reset on src
//  will also be captured by the dest_clk.
//  This block exports three synchronized version of resets:
//  1. src_rsd_rst_n: RSD version of src_rst_n
//  2. src_slow_rsd_rst_n: RSD version of src_rst_n that stays asserted
//                         as the reset propagates through the entire
//                         reset sync chain
//  3. dest_sync_rst_n: Version of src_rst_n that is synchronized to
//                      dest_clk domain
//
//---------------------------------------------------------------------
(* LATTICE_IP_MODULE=1 *) module lpddr4_mc_ipgen_hs_reset_sync #(parameter SYNC_STAGE = 2, 
        parameter UNRELATED_RST = 1'b1, 
        parameter SRC_RST_MODE = "ASYNC", 
        parameter DEST_RST_MODE = "ASYNC", 
        parameter USE_FAST_SYNC = 1'b0) (
    input logic src_rst_n, 
    input logic src_clk, 
    input logic dest_rst_n, 
    input logic dest_clk, 
    output logic src_rsd_rst_n, 
    output logic src_slow_rsd_rst_n, 
    output logic dest_sync_rst_n) ;
    generate
        if (UNRELATED_RST) 
            begin : genblk1
                logic src_rst_n_r, 
                    src_rst_n_nxt ; 
                logic src_rstn_sync, 
                    dest_rstn_sync ; 
                // Synchronized src_rst_n output for dest_clk domain
                assign dest_sync_rst_n = src_rstn_sync ; 
                // src_rst_n that is synchronized to src_clk on deassertion
                // RSD = reset sync deassertion
                assign src_rsd_rst_n = src_rst_n_r ; 
                // src_slow_rsd_rst_n that is synchronized to src_clk on 
                // deassertion. The deassertion will only happen after 
                // the reset has propagated through the entire sync chain
                assign src_slow_rsd_rst_n = (dest_rstn_sync & src_rsd_rst_n) ; 
                // Pulse sync ack qualifier
                assign src_rst_n_nxt = (src_rst_n_r | (~dest_rstn_sync)) ; 
                if ((SRC_RST_MODE == "ASYNC")) 
                    begin : genblk1
                        always_ff
                            @(posedge src_clk or 
                                negedge src_rst_n)
                            begin
                                if ((!src_rst_n)) 
                                    src_rst_n_r <=  1'b0 ;
                                else
                                    src_rst_n_r <=  src_rst_n_nxt ;
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge src_clk)
                            begin
                                if ((!src_rst_n)) 
                                    src_rst_n_r <=  1'b0 ;
                                else
                                    src_rst_n_r <=  src_rst_n_nxt ;
                            end
                    end
                // Reset synchronized to dest_clk. We are doing a SYNC_STAGE
                // synchronizer, with the first stage being regsitered on 
                // falling edge clock. This is to ensure that the reset sync 
                // will always arrive ahead of the toggle sync using worst
                // case scenario
                (* syn_preserve=1 *) logic src_to_dest_rstn_cc ; 
                logic [(SYNC_STAGE - 2):0] src_to_dest_rstn ; 
                if (USE_FAST_SYNC) 
                    begin : genblk2
                        if ((DEST_RST_MODE == "ASYNC")) 
                            begin : genblk1
                                always_ff
                                    @(negedge dest_clk or 
                                        negedge dest_rst_n)
                                    begin
                                        if ((!dest_rst_n)) 
                                            src_to_dest_rstn_cc <=  1'b1 ;
                                        else
                                            src_to_dest_rstn_cc <=  src_rst_n_r ;
                                    end
                            end
                        else
                            begin : genblk1
                                always_ff
                                    @(negedge dest_clk)
                                    begin
                                        if ((!dest_rst_n)) 
                                            src_to_dest_rstn_cc <=  1'b1 ;
                                        else
                                            src_to_dest_rstn_cc <=  src_rst_n_r ;
                                    end
                            end
                    end
                else
                    begin : genblk2
                        if ((DEST_RST_MODE == "ASYNC")) 
                            begin : genblk1
                                always_ff
                                    @(posedge dest_clk or 
                                        negedge dest_rst_n)
                                    begin
                                        if ((!dest_rst_n)) 
                                            src_to_dest_rstn_cc <=  1'b1 ;
                                        else
                                            src_to_dest_rstn_cc <=  src_rst_n_r ;
                                    end
                            end
                        else
                            begin : genblk1
                                always_ff
                                    @(posedge dest_clk)
                                    begin
                                        if ((!dest_rst_n)) 
                                            src_to_dest_rstn_cc <=  1'b1 ;
                                        else
                                            src_to_dest_rstn_cc <=  src_rst_n_r ;
                                    end
                            end
                    end
                if ((DEST_RST_MODE == "ASYNC")) 
                    begin : genblk3
                        always_ff
                            @(posedge dest_clk or 
                                negedge dest_rst_n)
                            begin
                                if ((!dest_rst_n)) 
                                    src_to_dest_rstn <=  {(SYNC_STAGE - 1){1'b1}} ;
                                else
                                    src_to_dest_rstn <=  ((SYNC_STAGE > 2) ? {src_to_dest_rstn[(SYNC_STAGE - 3):0],
                                            src_to_dest_rstn_cc} : src_to_dest_rstn_cc) ;
                            end
                    end
                else
                    begin : genblk3
                        always_ff
                            @(posedge dest_clk)
                            begin
                                if ((!dest_rst_n)) 
                                    src_to_dest_rstn <=  {(SYNC_STAGE - 1){1'b1}} ;
                                else
                                    src_to_dest_rstn <=  ((SYNC_STAGE > 2) ? {src_to_dest_rstn[(SYNC_STAGE - 3):0],
                                            src_to_dest_rstn_cc} : src_to_dest_rstn_cc) ;
                            end
                    end
                assign src_rstn_sync = src_to_dest_rstn[(SYNC_STAGE - 2)] ; 
                // Reset output synchronized back to src_clk as ack for pulse sync
                lpddr4_mc_ipgen_lscc_sync #(.SYNC_STAGE(SYNC_STAGE),
                        .DEST_RST_MODE("ASYNC"),
                        .RST_INIT(1'b1),
                        .REGMODE(1'b0)) u_lscc_sync_to_src (.in_data(src_rstn_sync), 
                            .dest_rst_n(src_rst_n), 
                            .dest_clk(src_clk), 
                            .out_data(dest_rstn_sync)) ; 
            end
        else
            begin : genblk1
                assign dest_sync_rst_n = 1'b1 ; 
                assign src_rsd_rst_n = src_rst_n ; 
                assign src_slow_rsd_rst_n = 1'b1 ; 
            end
    endgenerate
endmodule



/*
Purpose:
  Provides one layer of pipelining to allow data to 
  be registered when receiver is Full, and a write
  still happens, due to pipeline latency.
  
  This is a simple skid buffer that looks like this:
  
                                     |\
  -- input -- -- -- -- -- -- -- -- --| \
             |                       |  |
             |       ____            |  |-- -- output -->
             |-- -- |D  Q|-- -- -- --|  |
                    |    |           | / 
                    |____|           |/|
                                       | 
                                       |
                                      sel
*/
(* LATTICE_IP_MODULE=1 *) module lpddr4_mc_ipgen_lpddr4_mc_skid_buffer #(parameter WIDTH = 32) (
    // Clock and reset
    input clk_i, 
    input rstn_i, 
    // Wr data and controls
    input wr_valid_i, 
    input [(WIDTH - 1):0] wr_data_i, 
    output wr_ready_o, 
    // Rd data and controls
    output rd_valid_o, 
    output [(WIDTH - 1):0] rd_data_o, 
    input rd_ready_i) ;
    // Internal buffer
    logic [(WIDTH - 1):0] data_r ; 
    // Holds the state, whether in buffered mode
    // or not. Buffered means taking data from
    // internal buffer.
    logic buffered_r ; 
    // Holds the internal ready state
    (* syn_preserve=1 *) logic ready_r ; 
    // Drives ready_o with the registered version of ready
    assign wr_ready_o = ready_r ; 
    // Data mux
    assign rd_data_o = (buffered_r ? data_r : wr_data_i) ; 
    // Data Valid mux
    assign rd_valid_o = (buffered_r ? 1'b1 : (wr_valid_i & ready_r)) ; 
    // Skid Buffer state machine
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((!rstn_i)) 
                begin
                    buffered_r <=  1'b0 ;
                    ready_r <=  1'b0 ;
                    data_r <=  {WIDTH{1'b0}} ;
                end
            else
                begin
                    if (buffered_r) 
                        begin
                            if (rd_ready_i) 
                                begin
                                    ready_r <=  1'b1 ;
                                    buffered_r <=  1'b0 ;// Back to normal mode
                                end
                        end
                    else
                        begin
                            ready_r <=  1'b1 ;
                            if (((wr_valid_i && ready_r) && (!rd_ready_i))) 
                                begin
                                    ready_r <=  1'b0 ;
                                    data_r <=  wr_data_i ;// Skid happens, store data
                                    buffered_r <=  1'b1 ;// Goto buffered mode
                                end
                        end
                end
        end
endmodule



//---------------------------------------------------------------------
// Module: lscc_reset_sync
//---------------------------------------------------------------------
// Copyright (c) 2024 by Lattice Semiconductor Corporation
//---------------------------------------------------------------------
//
//  Params:
//  + SYNC_STAGE    -   Number of register stages used in synchronizers
//                      Allowable range is from 2 to 4
//  + SIM_ASSERT_EN -   Assertion enable
//
//  Ports:
//  + src_rst_n     -   Source reset (active low)
//
//  + dest_clk      -   Destination clock
//  + dest_rst      -   Destination reset (active high)
//  + dest_rst_n    -   Destination reset (active low)
//
//---------------------------------------------------------------------
(* LATTICE_IP_MODULE=1 *) module lpddr4_mc_ipgen_lscc_reset_sync #(parameter SYNC_STAGE = 2, 
        parameter SIM_ASSERT_EN = 1'b1) (
    input logic src_rst_n, 
    input logic dest_clk, 
    output logic dest_rst, 
    output logic dest_rst_n) ;
    (* syn_preserve=1 *) logic [(SYNC_STAGE - 1):0] rstn_sync = {SYNC_STAGE{1'b1}} ; 
    (* syn_preserve=1 *) logic [(SYNC_STAGE - 1):0] rst_sync = {SYNC_STAGE{1'b0}} ; 
    always
        @(posedge dest_clk)
        begin
            rstn_sync <=  {rstn_sync[(SYNC_STAGE - 2):0],
                    src_rst_n} ;
            rst_sync <=  {rst_sync[(SYNC_STAGE - 2):0],
                    (~src_rst_n)} ;
        end
    assign dest_rst = rst_sync[(SYNC_STAGE - 1)] ; 
    assign dest_rst_n = rstn_sync[(SYNC_STAGE - 1)] ; 
endmodule



