module lpddr4_mc_ipgen_lpddr4_mc_ecc_gen #(parameter DATA_WIDTH = 32, 
        parameter ECC_WIDTH = 8) (
    input clk, 
    input rst_n, 
    input [(DATA_WIDTH - 1):0] data_in, 
    output logic [(DATA_WIDTH - 1):0] data_out, 
    output logic [(8 - 1):0] calc_ecc) ;
    logic [(DATA_WIDTH - 1):0] D ; 
    logic [(DATA_WIDTH - 1):0] sig_data_out ; 
    logic [(8 - 1):0] P ; 
    logic [(8 - 1):0] sig_calc_ecc ; 
    assign D = data_in ; 
    assign sig_calc_ecc = {P[7],
                P[6],
                P[5],
                P[4],
                P[3],
                P[2],
                P[1],
                P[0]} ; 
    generate
        if ((DATA_WIDTH == 64)) 
            begin : genblk1
                assign P[7] = ((((((((((((((((((((D[39] ^ D[40]) ^ D[41]) ^ D[42]) ^ D[43]) ^ D[48]) ^ D[49]) ^ D[50]) ^ D[51]) ^ D[52]) ^ D[53]) ^ D[54]) ^ D[55]) ^ D[56]) ^ D[57]) ^ D[58]) ^ D[59]) ^ D[60]) ^ D[61]) ^ D[62]) ^ D[63]) ; 
                assign P[6] = ((((((((((((((((((((((D[24] ^ D[25]) ^ D[26]) ^ D[27]) ^ D[28]) ^ D[29]) ^ D[30]) ^ D[31]) ^ D[32]) ^ D[33]) ^ D[34]) ^ D[35]) ^ D[36]) ^ D[37]) ^ D[38]) ^ D[46]) ^ D[47]) ^ D[58]) ^ D[59]) ^ D[60]) ^ D[61]) ^ D[62]) ^ D[63]) ; 
                assign P[5] = (((((((((((((((((((((((((D[10] ^ D[11]) ^ D[12]) ^ D[13]) ^ D[14]) ^ D[15]) ^ D[16]) ^ D[17]) ^ D[18]) ^ D[19]) ^ D[21]) ^ D[22]) ^ D[23]) ^ D[34]) ^ D[35]) ^ D[36]) ^ D[37]) ^ D[38]) ^ D[44]) ^ D[45]) ^ D[53]) ^ D[54]) ^ D[55]) ^ D[56]) ^ D[57]) ^ D[63]) ; 
                assign P[4] = ((((((((((((((((((((((((((D[4] ^ D[5]) ^ D[6]) ^ D[7]) ^ D[8]) ^ D[9]) ^ D[16]) ^ D[17]) ^ D[18]) ^ D[19]) ^ D[20]) ^ D[22]) ^ D[23]) ^ D[30]) ^ D[31]) ^ D[32]) ^ D[33]) ^ D[38]) ^ D[44]) ^ D[45]) ^ D[47]) ^ D[49]) ^ D[50]) ^ D[51]) ^ D[52]) ^ D[57]) ^ D[62]) ; 
                assign P[3] = ((((((((((((((((((((((((((D[1] ^ D[2]) ^ D[3]) ^ D[7]) ^ D[8]) ^ D[9]) ^ D[13]) ^ D[14]) ^ D[15]) ^ D[19]) ^ D[20]) ^ D[21]) ^ D[23]) ^ D[27]) ^ D[28]) ^ D[29]) ^ D[33]) ^ D[37]) ^ D[42]) ^ D[43]) ^ D[44]) ^ D[45]) ^ D[46]) ^ D[48]) ^ D[52]) ^ D[56]) ^ D[61]) ; 
                assign P[2] = (((((((((((((((((((((((((((D[0] ^ D[2]) ^ D[3]) ^ D[5]) ^ D[6]) ^ D[9]) ^ D[11]) ^ D[12]) ^ D[15]) ^ D[18]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[25]) ^ D[26]) ^ D[29]) ^ D[32]) ^ D[36]) ^ D[40]) ^ D[41]) ^ D[44]) ^ D[45]) ^ D[46]) ^ D[47]) ^ D[48]) ^ D[51]) ^ D[55]) ^ D[60]) ; 
                assign P[1] = (((((((((((((((((((((((((((D[0] ^ D[1]) ^ D[3]) ^ D[4]) ^ D[6]) ^ D[8]) ^ D[10]) ^ D[12]) ^ D[14]) ^ D[17]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[23]) ^ D[24]) ^ D[26]) ^ D[28]) ^ D[31]) ^ D[35]) ^ D[39]) ^ D[41]) ^ D[43]) ^ D[45]) ^ D[46]) ^ D[47]) ^ D[50]) ^ D[54]) ^ D[59]) ; 
                assign P[0] = (((((((((((((((((((((((((((D[0] ^ D[1]) ^ D[2]) ^ D[4]) ^ D[5]) ^ D[7]) ^ D[10]) ^ D[11]) ^ D[13]) ^ D[16]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[23]) ^ D[24]) ^ D[25]) ^ D[27]) ^ D[30]) ^ D[34]) ^ D[39]) ^ D[40]) ^ D[42]) ^ D[44]) ^ D[46]) ^ D[47]) ^ D[49]) ^ D[53]) ^ D[58]) ; 
            end
        if ((DATA_WIDTH == 32)) 
            begin : genblk2
                assign P[7] = 1'b0 ; 
                assign P[6] = (((((((D[24] ^ D[25]) ^ D[26]) ^ D[27]) ^ D[28]) ^ D[29]) ^ D[30]) ^ D[31]) ; 
                assign P[5] = ((((((((((((D[10] ^ D[11]) ^ D[12]) ^ D[13]) ^ D[14]) ^ D[15]) ^ D[16]) ^ D[17]) ^ D[18]) ^ D[19]) ^ D[21]) ^ D[22]) ^ D[23]) ; 
                assign P[4] = ((((((((((((((D[4] ^ D[5]) ^ D[6]) ^ D[7]) ^ D[8]) ^ D[9]) ^ D[16]) ^ D[17]) ^ D[18]) ^ D[19]) ^ D[20]) ^ D[22]) ^ D[23]) ^ D[30]) ^ D[31]) ; 
                assign P[3] = (((((((((((((((D[1] ^ D[2]) ^ D[3]) ^ D[7]) ^ D[8]) ^ D[9]) ^ D[13]) ^ D[14]) ^ D[15]) ^ D[19]) ^ D[20]) ^ D[21]) ^ D[23]) ^ D[27]) ^ D[28]) ^ D[29]) ; 
                assign P[2] = (((((((((((((((D[0] ^ D[2]) ^ D[3]) ^ D[5]) ^ D[6]) ^ D[9]) ^ D[11]) ^ D[12]) ^ D[15]) ^ D[18]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[25]) ^ D[26]) ^ D[29]) ; 
                assign P[1] = (((((((((((((((((D[0] ^ D[1]) ^ D[3]) ^ D[4]) ^ D[6]) ^ D[8]) ^ D[10]) ^ D[12]) ^ D[14]) ^ D[17]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[23]) ^ D[24]) ^ D[26]) ^ D[28]) ^ D[31]) ; 
                assign P[0] = (((((((((((((((((D[0] ^ D[1]) ^ D[2]) ^ D[4]) ^ D[5]) ^ D[7]) ^ D[10]) ^ D[11]) ^ D[13]) ^ D[16]) ^ D[20]) ^ D[21]) ^ D[22]) ^ D[23]) ^ D[24]) ^ D[25]) ^ D[27]) ^ D[30]) ; 
            end
        if ((DATA_WIDTH == 16)) 
            begin : genblk3
                assign P[7] = 1'b0 ; 
                assign P[6] = 1'b0 ; 
                assign P[5] = (((((D[10] ^ D[11]) ^ D[12]) ^ D[13]) ^ D[14]) ^ D[15]) ; 
                assign P[4] = (((((D[4] ^ D[5]) ^ D[6]) ^ D[7]) ^ D[8]) ^ D[9]) ; 
                assign P[3] = ((((((((D[1] ^ D[2]) ^ D[3]) ^ D[7]) ^ D[8]) ^ D[9]) ^ D[13]) ^ D[14]) ^ D[15]) ; 
                assign P[2] = ((((((((D[0] ^ D[2]) ^ D[3]) ^ D[5]) ^ D[6]) ^ D[9]) ^ D[11]) ^ D[12]) ^ D[15]) ; 
                assign P[1] = ((((((((D[0] ^ D[1]) ^ D[3]) ^ D[4]) ^ D[6]) ^ D[8]) ^ D[10]) ^ D[12]) ^ D[14]) ; 
                assign P[0] = ((((((((D[0] ^ D[1]) ^ D[2]) ^ D[4]) ^ D[5]) ^ D[7]) ^ D[10]) ^ D[11]) ^ D[13]) ; 
            end
        if ((DATA_WIDTH == 8)) 
            begin : genblk4
                assign P[7] = 1'b0 ; 
                assign P[6] = 1'b0 ; 
                assign P[5] = 1'b0 ; 
                assign P[4] = (((D[4] ^ D[5]) ^ D[6]) ^ D[7]) ; 
                assign P[3] = (((D[1] ^ D[2]) ^ D[3]) ^ D[7]) ; 
                assign P[2] = ((((D[0] ^ D[2]) ^ D[3]) ^ D[5]) ^ D[6]) ; 
                assign P[1] = ((((D[0] ^ D[1]) ^ D[3]) ^ D[4]) ^ D[6]) ; 
                assign P[0] = (((((D[0] ^ D[1]) ^ D[2]) ^ D[4]) ^ D[5]) ^ D[7]) ; 
            end
    endgenerate
    always
        @(posedge clk or 
            negedge rst_n)
        if ((!rst_n)) 
            data_out <=  0 ;
        else
            data_out <=  {data_in} ;
    always
        @(posedge clk or 
            negedge rst_n)
        if ((!rst_n)) 
            calc_ecc <=  0 ;
        else
            calc_ecc <=  sig_calc_ecc ;

//assign calc_ecc = sig_calc_ecc;
//assign data_out = data_in;
endmodule



