    always_ff
        @(posedge sclk_o or 
            negedge rst_n_i)
        begin
            if ((!rst_n_i)) 
                begin
                    srst_n_r <=  1'b0 ;
                    srst_n <=  1'b0 ;
                    srst_n_rep <=  1'b0 ;
                end
            else
                begin
                    srst_n_r <=  1'b1 ;
                    srst_n <=  srst_n_r ;
                    srst_n_rep <=  srst_n_r ;
                end
        end
    always_ff
        @(posedge hclk_w or 
            negedge areset_n_i)
        begin
            if ((!areset_n_i)) 
                begin
                    arst_n_r <=  1'b0 ;
                    arst_n <=  1'b0 ;
                end
            else
                begin
                    arst_n_r <=  1'b1 ;
                    arst_n <=  arst_n_r ;
                end
        end
    always_ff
