            begin : RD_PIPE
                always_ff
                    @(posedge sclk_o)
                    begin
                        read_dmi_r <=  read_dmi_w ;
                        read_dq_r <=  read_dq_w ;
                    end
                always_ff
                    @(posedge sclk_o or 
                        negedge srst_n)
                    if ((!srst_n)) 
                        read_data_valid_r <=  {DQS_WIDTH{1'b0}} ;
                    else
                        //read_data_valid_r <= read_data_valid_w;
                        read_data_valid_r <=  {DQS_WIDTH{(&read_data_valid_w)}} ;
            end
        else
            begin : RD_NOPIPE
                assign read_dmi_r = read_dmi_w ; 
                assign read_dq_r = read_dq_w ; 
                assign read_data_valid_r = read_data_valid_w ; 
            end
